def get_nba_store_filter_check__9f3f70fc(env, config: Dict[str, Any]):
    """
    Get NBA store filter state with improved URL parsing and product verification.

    Args:
        env: Environment object with vm_ip, chromium_port, server_port
        config: Configuration dict with:
            - expected_filters: dict of {filter_name: filter_value} to check in URL params
            - filter_selectors: list of CSS selectors to find filter elements (fallback to common patterns)
            - product_selector: CSS selector to find product elements (optional)
            - min_products: minimum number of products expected (optional, default: 1)

    Returns:
        dict: {
            "filters_in_url": dict of {filter_name: True/False},
            "filters_on_page": list of filter texts found on page,
            "product_count": int,
            "has_products": bool,
            "url_params": dict of parsed URL parameters
        }
    """
    logger.info(f'[DEBUG] get_nba_store_filter_check__9f3f70fc called with config: {config}')
    host = env.vm_ip
    port = env.chromium_port
    server_port = env.server_port
    remote_debugging_url = f'http://{host}:{port}'
    expected_filters = config.get('expected_filters', {})
    filter_selectors = config.get('filter_selectors', ['.filter-selector-link', "[class*='filter']", "[class*='facet']", "[class*='refinement']", '[data-filter]'])
    product_selector = config.get('product_selector', "[class*='product'], [data-product], .product-card, .product-item")
    min_products = config.get('min_products', 1)
    with sync_playwright() as p:
        try:
            browser = p.chromium.connect_over_cdp(remote_debugging_url)
        except Exception as e:
            logger.warning(f'[DEBUG] Failed to connect to Chrome, starting new instance: {e}')
            app = 'chromium' if 'arm' in platform.machine() else 'google-chrome'
            payload = json.dumps({'command': [app, '--remote-debugging-port=1337'], 'shell': False})
            headers = {'Content-Type': 'application/json'}
            requests.post(f'http://{host}:{server_port}/setup/launch', headers=headers, data=payload)
            time.sleep(5)
            browser = p.chromium.connect_over_cdp(remote_debugging_url)
        target_page = None
        for context in browser.contexts:
            for page in context.pages:
                try:
                    if not page.is_closed():
                        target_page = page
                        break
                except Exception as e:
                    logger.debug(f'[DEBUG] Error accessing page: {e}')
                    continue
            if target_page:
                break
        if not target_page:
            logger.error('[DEBUG] No active page found')
            browser.close()
            return {'filters_in_url': {}, 'filters_on_page': [], 'product_count': 0, 'has_products': False, 'url_params': {}}
        try:
            target_page.wait_for_load_state('networkidle', timeout=30000)
        except Exception as e:
            logger.warning(f'[DEBUG] Page load wait timeout: {e}')
        result = {'filters_in_url': {}, 'filters_on_page': [], 'product_count': 0, 'has_products': False, 'url_params': {}}
        try:
            current_url = target_page.url
            logger.info(f'[DEBUG] Current URL: {current_url}')
            parsed_url = urlparse(current_url)
            url_params = parse_qs(parsed_url.query)
            result['url_params'] = {k: v[0] if len(v) == 1 else v for (k, v) in url_params.items()}
            logger.info(f"[DEBUG] Parsed URL params: {result['url_params']}")
            for (filter_name, expected_value) in expected_filters.items():
                found = False
                if filter_name.lower() in [k.lower() for k in url_params.keys()]:
                    found = True
                if not found:
                    for param_values in url_params.values():
                        for val in param_values if isinstance(param_values, list) else [param_values]:
                            val_lower = unquote(val).lower()
                            filter_lower = filter_name.lower()
                            import re
                            pattern = '\\b' + re.escape(filter_lower) + '\\b'
                            if re.search(pattern, val_lower):
                                found = True
                                break
                        if found:
                            break
                if not found:
                    path_lower = parsed_url.path.lower()
                    filter_lower = filter_name.lower()
                    import re
                    pattern = '\\b' + re.escape(filter_lower) + '\\b'
                    if re.search(pattern, path_lower):
                        found = True
                result['filters_in_url'][filter_name.lower()] = found
                logger.info(f"[DEBUG] Filter '{filter_name}' in URL: {found}")
            all_filter_texts = []
            for selector in filter_selectors:
                try:
                    elements = target_page.query_selector_all(selector)
                    for element in elements:
                        try:
                            text = element.text_content()
                            if text and text.strip():
                                all_filter_texts.append(text.strip())
                        except Exception as e:
                            logger.debug(f'[DEBUG] Error getting text from element: {e}')
                except Exception as e:
                    logger.debug(f"[DEBUG] Selector '{selector}' failed: {e}")
            result['filters_on_page'] = all_filter_texts
            logger.info(f'[DEBUG] Found {len(all_filter_texts)} filter elements on page')
            try:
                product_elements = target_page.query_selector_all(product_selector)
                result['product_count'] = len(product_elements)
                result['has_products'] = len(product_elements) >= min_products
                logger.info(f'[DEBUG] Found {len(product_elements)} product elements')
            except Exception as e:
                logger.warning(f'[DEBUG] Error counting products: {e}')
                result['product_count'] = 0
                result['has_products'] = False
        except Exception as e:
            logger.error(f'[DEBUG] Error in get_nba_store_filter_check: {e}')
        browser.close()
    logger.info(f'[DEBUG] Final result: {result}')
    return result

def get_docx_field_counts__b380992f(env, config):
    """Get counts of each paper field type.

    Args:
        env: DesktopEnv instance
        config: Configuration dict

    Returns:
        int: Minimum count across all field types
    """
    import os
    from docx import Document
    path = config['path']
    dest = config.get('dest', os.path.basename(path))
    cache_path = os.path.join(env.cache_dir, dest)
    file_bytes = env.controller.get_file(path)
    if not file_bytes:
        return 0
    with open(cache_path, 'wb') as f:
        f.write(file_bytes)
    doc = Document(cache_path)
    paragraphs = [p.text.strip() for p in doc.paragraphs if p.text.strip()]
    titles = sum((1 for p in paragraphs if p.startswith('Title:')))
    authors = sum((1 for p in paragraphs if p.startswith('Authors:')))
    abstracts = sum((1 for p in paragraphs if p.startswith('Abstract:')))
    arxiv = sum((1 for p in paragraphs if p.startswith('Arxiv PDF:')))
    return min(titles, authors, abstracts, arxiv)

def get_docx_fontsize_info__84983c7d(env, config):
    """Extract font size information for uppercase text.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: Font sizes of uppercase text
    """
    vm_path = config.get('path', '/home/user/Desktop/presentation_instruction_2023_Feb.docx')
    file_bytes = env.controller.get_file(vm_path)
    if not file_bytes:
        return {'uppercase_font_sizes': []}
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(delete=False, suffix='.docx') as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        font_sizes = []
        for para in doc.paragraphs:
            for run in para.runs:
                text = run.text
                if text and text.isupper() and (len(text.strip()) > 0):
                    if run.font.size:
                        font_sizes.append(run.font.size.pt)
                    else:
                        font_sizes.append(None)
        for table in doc.tables:
            for row in table.rows:
                for cell in row.cells:
                    for para in cell.paragraphs:
                        for run in para.runs:
                            text = run.text
                            if text and text.isupper() and (len(text.strip()) > 0):
                                if run.font.size:
                                    font_sizes.append(run.font.size.pt)
                                else:
                                    font_sizes.append(None)
        return {'uppercase_font_sizes': font_sizes}
    finally:
        os.unlink(tmp_path)

