def get_odt_font_sizes__a34364cfed7c7e9e11ed1d12c2e11819(env, config: dict) -> Dict[str, Any]:
    """
    Extract text with their font sizes from an ODT file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the ODT file

    Returns:
        Dict with text instances and their font sizes
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'text_with_sizes': []}
    with tempfile.NamedTemporaryFile(suffix='.odt', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        with zipfile.ZipFile(tmp_path, 'r') as z:
            content_xml = z.read('content.xml')
        root = ET.fromstring(content_xml)
        ns = {'text': 'urn:oasis:names:tc:opendocument:xmlns:text:1.0', 'style': 'urn:oasis:names:tc:opendocument:xmlns:style:1.0', 'office': 'urn:oasis:names:tc:opendocument:xmlns:office:1.0', 'fo': 'urn:oasis:names:tc:opendocument:xmlns:xsl-fo-compatible:1.0'}
        style_font_sizes = {}
        auto_styles = root.find('.//office:automatic-styles', ns)
        if auto_styles:
            for style in auto_styles.findall('.//style:style', ns):
                text_props = style.find('.//style:text-properties', ns)
                if text_props is not None:
                    font_size = text_props.get('{urn:oasis:names:tc:opendocument:xmlns:xsl-fo-compatible:1.0}font-size')
                    if font_size:
                        style_name = style.get('{urn:oasis:names:tc:opendocument:xmlns:style:1.0}name')
                        if style_name:
                            style_font_sizes[style_name] = font_size
        text_with_sizes = []
        body = root.find('.//office:body', ns)
        if body:
            text_body = body.find('.//office:text', ns)
            if text_body:
                for para in text_body.findall('.//text:p', ns):
                    para_style = para.get('{urn:oasis:names:tc:opendocument:xmlns:text:1.0}style-name')
                    spans = para.findall('.//text:span', ns)
                    if spans:
                        for span in spans:
                            style_name = span.get('{urn:oasis:names:tc:opendocument:xmlns:text:1.0}style-name')
                            if style_name in style_font_sizes:
                                text_content = ''.join(span.itertext())
                                if text_content.strip():
                                    text_with_sizes.append({'text': text_content.strip(), 'font_size': style_font_sizes[style_name]})
                    elif para_style in style_font_sizes:
                        text_content = ''.join(para.itertext())
                        if text_content.strip():
                            text_with_sizes.append({'text': text_content.strip(), 'font_size': style_font_sizes[para_style]})
        return {'text_with_sizes': text_with_sizes}
    finally:
        os.unlink(tmp_path)

