def get_pictures_hash_mapping__ce2b64a2(env, config):
    """
    Get a mapping of SHA256 content hashes to filenames for images in the Pictures directory.

    This function transparently verifies the task by:
    1. Listing all files in /home/user/Pictures/ (verifies files remain in the correct directory)
    2. Computing SHA256 hash of file contents (ensures files weren't replaced, only renamed)
    3. Returning a dict mapping hash -> filename (allows checking if renamed files have acceptable names)

    The evaluation works as follows:
    - Original files (picture1.jpg, picture2.jpg, picture3.jpg) have specific content hashes
    - If files are correctly renamed to mountain names, those same content hashes will map to new filenames
    - The metric checks if the new filename (value) is in the list of acceptable mountain names for that content hash (key)
    - This verifies: (a) files stayed in Pictures directory, (b) file contents unchanged (actual renaming, not replacement),
      (c) new filenames match acceptable mountain name variations

    Args:
        env: Environment object with controller
        config: Configuration dict with optional 'directory' key (defaults to /home/user/Pictures)

    Returns:
        dict: Mapping of SHA256 hashes to filenames, e.g.:
              {
                  "ec076282f61ba74642e94b5a6a1250c6988204d59d9b02936606b6b8ef1e4433": "Kilimanjaro.jpg",
                  "6ed4239ecc2be3ec15ad65a78c5c823b9004d640b8cc83a6a7af5930f354de91": "Mount Everest.jpg",
                  "79f45d40d8413d4e81f1b9734ea39e58622cafd79e12bab32959643fc245147c": "Hua Shan.jpg"
              }
              Returns empty dict if directory doesn't exist or is empty
    """
    pictures_dir = config.get('directory', '/home/user/Pictures')
    try:
        result = env.controller.execute(f'ls -1 "{pictures_dir}"')
        if not result or result.strip() == '':
            return {}
        filenames = [f.strip() for f in result.strip().split('\n') if f.strip()]
    except Exception:
        return {}
    hash_to_filename = {}
    for filename in filenames:
        if not filename:
            continue
        file_path = os.path.join(pictures_dir, filename)
        file_bytes = env.controller.get_file(file_path)
        if not file_bytes:
            continue
        hash_obj = hashlib.sha256(file_bytes)
        file_hash = hash_obj.hexdigest()
        hash_to_filename[file_hash] = filename
    return hash_to_filename

def get_writer_line_spacing__ded8af3e2f2cb08d572f4f0efb0f8c9d(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract line spacing information from paragraphs in a DOCX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the DOCX file

    Returns:
        Dict with line spacing information
    """
    try:
        file_bytes = env.controller.get_file(config['path'])
        if not file_bytes:
            logger.error(f"Failed to get file: {config['path']}")
            return {'paragraph_spacings': []}
        with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        try:
            doc = Document(tmp_path)
            paragraph_spacings = []
            for (i, para) in enumerate(doc.paragraphs):
                if para.text.strip():
                    spacing = para.paragraph_format.line_spacing
                    if hasattr(spacing, 'pt'):
                        spacing_value = spacing.pt
                    else:
                        spacing_value = spacing
                    paragraph_spacings.append({'index': i, 'spacing': spacing_value, 'text_preview': para.text[:30]})
            return {'paragraph_spacings': paragraph_spacings, 'count': len(paragraph_spacings)}
        finally:
            os.unlink(tmp_path)
    except Exception as e:
        logger.error(f'Error extracting line spacing: {e}')
        return {'paragraph_spacings': []}

def get_docx_second_para__e8a68271(env, config: dict) -> Optional[str]:
    """Extract the paragraph containing course code pattern (letters followed by numbers).

    Searches all paragraphs for a pattern matching course codes like 'CHIN9505' or 'CHIN 9505'.
    This is more robust than assuming a fixed paragraph index.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path'

    Returns:
        Text of the paragraph containing the course code, or None if not found
    """
    file_path = config.get('path')
    if not file_path:
        return None
    try:
        doc = Document(file_path)
        course_code_pattern = re.compile('[A-Z]{3,5}\\s?\\d{4}')
        for para in doc.paragraphs:
            if course_code_pattern.search(para.text):
                return para.text
        return None
    except Exception as e:
        return None

def get_bib_venues__7e57116f(env, config: Dict[str, Any]) -> List[str]:
    """
    Extract publication venues (booktitle/journal) from BibTeX entries.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        List[str]: List of normalized venue names
    """
    file_path = config.get('path', '/home/user/Desktop/references.bib')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return []
    content = file_bytes.decode('utf-8', errors='ignore')
    booktitle_pattern = 'booktitle\\s*=\\s*\\{([^}]+(?:\\{[^}]*\\}[^}]*)*)\\}'
    journal_pattern = 'journal\\s*=\\s*\\{([^}]+(?:\\{[^}]*\\}[^}]*)*)\\}'
    booktitles = re.findall(booktitle_pattern, content, re.IGNORECASE | re.DOTALL)
    journals = re.findall(journal_pattern, content, re.IGNORECASE | re.DOTALL)
    venues = booktitles + journals
    normalized_venues = []
    for venue in venues:
        clean_venue = ' '.join(venue.split())
        normalized_venues.append(clean_venue.strip().lower())
    return normalized_venues

def get_docx_italic_text__76058fefce7e815a7bac48fc07e35830(env, config: Dict[str, Any]) -> Any:
    """Extract text content that has italic formatting.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key for file path on VM

    Returns:
        List of strings representing text with italic formatting
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return []
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        italic_texts = []
        for paragraph in doc.paragraphs:
            italic_parts = []
            for run in paragraph.runs:
                if run.font.italic and run.text.strip():
                    italic_parts.append(run.text.strip())
            if italic_parts:
                combined_text = ' '.join(italic_parts).strip()
                if combined_text:
                    italic_texts.append(combined_text)
        return italic_texts
    finally:
        os.unlink(tmp_path)

def get_cs_avg_rate__fe33fa8497826ffab54958d76a7a0463(env, config):
    """Extract average success rate and yearly rates from CS-GRF-Analysis.xlsx

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: {
            'average_rate': float,
            'yearly_rates': {year: rate, ...}
        }
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return None
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        yearly_rates = {}
        average_rate = None
        for row in ws.iter_rows(min_row=2, values_only=True):
            if not row or not row[0]:
                continue
            label = str(row[0]).strip()
            value = row[1]
            if value is None:
                continue
            if 'average' in label.lower():
                average_rate = float(value)
            else:
                try:
                    year_str = ''.join((c for c in label if c.isdigit()))
                    if year_str:
                        year = int(year_str)
                        if 2019 <= year <= 2023:
                            yearly_rates[year] = float(value)
                except (ValueError, TypeError):
                    continue
        if average_rate is None:
            return None
        return {'average_rate': average_rate, 'yearly_rates': yearly_rates}
    finally:
        os.unlink(tmp_path)

