def get_javascript_enabled__980fd38b(env, config: Dict[str, str]):
    """Check if JavaScript is enabled in Chrome preferences."""
    os_type = env.vm_platform
    if os_type == 'Windows':
        preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('LOCALAPPDATA'),\n                                            'Google\\Chrome\\User Data\\Default\\Preferences'))")['output'].strip()
    elif os_type == 'Darwin':
        preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), 'Library/Application Support/Google/Chrome/Default/Preferences'))")['output'].strip()
    elif os_type == 'Linux':
        if 'arm' in platform.machine():
            preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), 'snap/chromium/common/chromium/Default/Preferences'))")['output'].strip()
        else:
            preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), '.config/google-chrome/Default/Preferences'))")['output'].strip()
    else:
        raise Exception('Unsupported operating system')
    try:
        content = env.controller.get_file(preference_file_path)
        data = json.loads(content)
        profile = data.get('profile', {})
        default_content_settings = profile.get('default_content_settings', {})
        javascript = default_content_settings.get('javascript', 1)
        return 'false' if javascript == 2 else 'true'
    except Exception as e:
        logger.error(f'Error: {e}')
        return 'true'

def get_default_word_processor__e2fc8f40(env, config: dict):
    """Gets the default application for word processor documents.

    Args:
        env: Environment object
        config: Configuration dict

    Returns:
        The most common default word processor registered for document MIME types
    """
    os_type = env.vm_platform
    if os_type == 'Linux':
        extensions = ['vnd.ms-word', 'vnd.openxmlformats-officedocument.wordprocessingml.document', 'vnd.oasis.opendocument.text', 'rtf']
        apps = []
        for ext in extensions:
            app = get_vm_command_line(env, {'command': ['xdg-mime', 'query', 'default', f'application/{ext}']})
            if app:
                apps.append(app)
        if len(apps) == 0:
            return 'unknown'
        else:
            return Counter(apps).most_common(1)[0][0]
    elif os_type == 'Darwin':
        raise Exception('Unsupported operating system', os_type)
    elif os_type == 'Windows':
        raise Exception('Unsupported operating system', os_type)
    else:
        raise Exception('Unsupported operating system', os_type)

def get_docx_heading_check__ca69839e(env, config: dict):
    """Check if document contains heading styles, content, and Chrome history.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'dest' parameters

    Returns:
        dict: Contains has_headings, heading_count, content_char_count, and chrome_history_visited
    """
    try:
        file_bytes = env.controller.get_file(config['path'])
        if not file_bytes:
            logger.error('Document file not found')
            return None
        cache_path = os.path.join(env.cache_dir, config['dest'])
        os.makedirs(os.path.dirname(cache_path), exist_ok=True)
        with open(cache_path, 'wb') as f:
            f.write(file_bytes)
        doc = Document(cache_path)
        heading_count = 0
        total_text_chars = 0
        for para in doc.paragraphs:
            if para.style.name.startswith('Heading') or para.style.name.startswith('Title'):
                heading_count += 1
            else:
                para_text = para.text.strip()
                total_text_chars += len(para_text)
        chrome_history_visited = False
        try:
            os_type = env.vm_platform
            if os_type == 'Linux':
                if 'arm' in platform.machine():
                    chrome_history_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), 'snap/chromium/common/chromium/Default/History'))")['output'].strip()
                else:
                    chrome_history_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), '.config', 'google-chrome', 'Default', 'History'))")['output'].strip()
            elif os_type == 'Darwin':
                chrome_history_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), 'Library', 'Application Support', 'Google', 'Chrome', 'Default', 'History'))")['output'].strip()
            elif os_type == 'Windows':
                chrome_history_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('USERPROFILE'), 'AppData', 'Local', 'Google', 'Chrome', 'User Data', 'Default', 'History'))")['output'].strip()
            else:
                logger.warning(f'Unsupported OS type: {os_type}')
                chrome_history_path = None
            if chrome_history_path:
                history_content = env.controller.get_file(chrome_history_path)
                history_cache_path = os.path.join(env.cache_dir, 'History_check')
                with open(history_cache_path, 'wb') as f:
                    f.write(history_content)
                conn = sqlite3.connect(history_cache_path)
                cursor = conn.cursor()
                cursor.execute("SELECT url FROM urls WHERE url LIKE '%linux.org%'")
                history_items = cursor.fetchall()
                conn.close()
                if history_items:
                    chrome_history_visited = True
                    logger.info(f'Found {len(history_items)} linux.org entries in Chrome history')
                else:
                    logger.info('No linux.org entries found in Chrome history')
            else:
                logger.warning('Could not determine Chrome history path')
        except Exception as e:
            logger.warning(f'Error checking Chrome history: {e}')
            chrome_history_visited = False
        result = {'has_headings': heading_count > 0, 'heading_count': heading_count, 'content_char_count': total_text_chars, 'chrome_history_visited': chrome_history_visited}
        logger.info(f'Document check: {result}')
        return result
    except Exception as e:
        logger.error(f'Error checking document: {e}')
        return None

def get_inverted_colors__2e82fb06(env, config):
    """
    Check if colors have been inverted compared to original.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'original_path'

    Returns:
        dict: Dictionary with inversion check result
    """
    try:
        result_path = config.get('path')
        original_path = config.get('original_path', '/home/user/Desktop/character.png')
        if not result_path:
            logger.error('No result path provided')
            return None
        result_content = env.controller.get_file(result_path)
        original_content = env.controller.get_file(original_path)
        if not result_content or not original_content:
            logger.error('Failed to get files')
            return None
        result_local = os.path.join(env.cache_dir, 'result_invert.png')
        original_local = os.path.join(env.cache_dir, 'original_invert.png')
        with open(result_local, 'wb') as f:
            f.write(result_content)
        with open(original_local, 'wb') as f:
            f.write(original_content)
        result_img = Image.open(result_local).convert('RGB')
        original_img = Image.open(original_local).convert('RGB')
        import numpy as np
        result_arr = np.array(result_img)
        original_arr = np.array(original_img)
        inverted_original = 255 - original_arr
        is_inverted = np.allclose(result_arr, inverted_original, atol=10)
        logger.info(f'Colors inverted: {is_inverted}')
        return {'is_inverted': is_inverted}
    except Exception as e:
        logger.error(f'Error checking color inversion: {e}')
        import traceback
        logger.error(traceback.format_exc())
        return None

def get_docx_paragraph_italic__4e5c493c(env, config):
    """Check if a specific paragraph is italic.

    Args:
        env: DesktopEnv instance
        config: Config with 'path', 'dest', and 'para_idx'

    Returns:
        dict: {"para_idx": int, "is_italic": bool}
    """
    file_path = config.get('path', '')
    para_idx = config.get('para_idx', 0)
    file_bytes = env.controller.get_file(file_path)
    if file_bytes is None:
        return {'para_idx': para_idx, 'is_italic': False}
    doc = Document(io.BytesIO(file_bytes))
    if para_idx >= len(doc.paragraphs):
        return {'para_idx': para_idx, 'is_italic': False}
    para = doc.paragraphs[para_idx]
    if not para.runs:
        return {'para_idx': para_idx, 'is_italic': False}
    italic_runs = sum((1 for run in para.runs if run.italic))
    total_runs = len(para.runs)
    is_italic = italic_runs / total_runs >= 0.8
    return {'para_idx': para_idx, 'is_italic': is_italic}

def get_ext_description__8ebf3af1a88b653a220b5e5431096f3a(env, config: Dict[str, Any]) -> str:
    """Get the extension description from Chrome preferences for an extension at a specific path.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'extension_path' key

    Returns:
        str: Extension description if found, empty string otherwise
    """
    os_type = env.vm_platform
    target_path = config.get('extension_path', '')
    if os_type == 'Windows':
        preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('LOCALAPPDATA'),\n            'Google\\Chrome\\User Data\\Default\\Preferences'))")['output'].strip()
    elif os_type == 'Darwin':
        preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), 'Library/Application Support/Google/Chrome/Default/Preferences'))")['output'].strip()
    elif os_type == 'Linux':
        if 'arm' in platform.machine():
            preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), 'snap/chromium/common/chromium/Default/Preferences'))")['output'].strip()
        else:
            preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), '.config/google-chrome/Default/Preferences'))")['output'].strip()
    else:
        raise Exception('Unsupported operating system')
    try:
        content = env.controller.get_file(preference_file_path)
        data = json.loads(content)
        all_extensions = data.get('extensions', {}).get('settings', {})
        for (ext_id, ext_data) in all_extensions.items():
            path = ext_data.get('path', '')
            if path == target_path:
                manifest = ext_data.get('manifest', {})
                description = manifest.get('description', '')
                return description
        return ''
    except Exception as e:
        logger.error(f'Error reading Chrome Preferences file: {e}')
        return ''

