def get_first_para_alignment__8ecea6af(env, config: dict):
    """Extract first paragraph alignment from a DOCX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' parameter

    Returns:
        str: Alignment value ('center', 'left', 'right', 'justify', 'unknown')
    """
    path = config.get('path', '/home/user/Desktop/Sample_Statutory_Declaration.docx')
    file_bytes = env.controller.get_file(path)
    if not file_bytes:
        return 'unknown'
    import tempfile
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp_file:
        tmp_file.write(file_bytes)
        tmp_path = tmp_file.name
    try:
        doc = Document(tmp_path)
        if not doc.paragraphs:
            return 'unknown'
        for para in doc.paragraphs:
            if para.text.strip():
                alignment = para.alignment
                if alignment == WD_PARAGRAPH_ALIGNMENT.CENTER or alignment == 1:
                    return 'center'
                elif alignment == WD_PARAGRAPH_ALIGNMENT.LEFT or alignment == 0:
                    return 'left'
                elif alignment == WD_PARAGRAPH_ALIGNMENT.RIGHT or alignment == 2:
                    return 'right'
                elif alignment == WD_PARAGRAPH_ALIGNMENT.JUSTIFY or alignment == 3:
                    return 'justify'
                else:
                    return 'left'
        return 'unknown'
    except Exception as e:
        return 'unknown'
    finally:
        import os
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

