def get_docx_line_spacing__a9d0805bcb8b4e6ece1e430f77b701f7(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract line spacing from all paragraphs in a .docx file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM file path)

    Returns:
        Dict with keys:
        - 'spacings': List[float] - list of line spacing values for each paragraph
        - 'all_same': bool - whether all paragraphs have the same line spacing
        - 'common_spacing': float - the spacing value if all same, or None
        - 'error': str - error message if any
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'spacings': [], 'all_same': False, 'common_spacing': None, 'error': 'File not found'}
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        spacings = []
        for para in doc.paragraphs:
            spacing = para.paragraph_format.line_spacing
            if spacing is not None:
                if hasattr(spacing, 'pt'):
                    spacings.append(spacing.pt)
                else:
                    spacings.append(float(spacing))
            else:
                spacings.append(1.0)
        if spacings:
            all_same = all((abs(s - spacings[0]) < 0.01 for s in spacings))
            common_spacing = spacings[0] if all_same else None
        else:
            all_same = False
            common_spacing = None
        return {'spacings': spacings, 'all_same': all_same, 'common_spacing': common_spacing, 'error': None}
    except Exception as e:
        return {'spacings': [], 'all_same': False, 'common_spacing': None, 'error': str(e)}
    finally:
        os.unlink(tmp_path)

