def get_odt_title_color__a0593874(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Extract text color of the first paragraph.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict with 'color' key (e.g., "#0000ff" for blue)
    """
    file_path = config.get('path')
    if not file_path:
        logger.error('No file path provided')
        return {'color': None}
    try:
        file_bytes = env.controller.get_file(file_path)
        if not file_bytes:
            logger.error(f'Could not read file: {file_path}')
            return {'color': None}
        import tempfile
        import os
        with tempfile.NamedTemporaryFile(suffix='.odt', delete=False) as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        try:
            with zipfile.ZipFile(tmp_path, 'r') as z:
                content_xml = z.read('content.xml').decode('utf-8')
            root = ET.fromstring(content_xml)
            namespaces = {'office': 'urn:oasis:names:tc:opendocument:xmlns:office:1.0', 'text': 'urn:oasis:names:tc:opendocument:xmlns:text:1.0', 'style': 'urn:oasis:names:tc:opendocument:xmlns:style:1.0', 'fo': 'urn:oasis:names:tc:opendocument:xmlns:xsl-fo-compatible:1.0'}
            body = root.find('.//office:body', namespaces)
            if body is None:
                return {'color': None}
            text_elem = body.find('.//office:text', namespaces)
            if text_elem is None:
                return {'color': None}
            first_para = text_elem.find('.//text:p', namespaces)
            if first_para is None:
                return {'color': None}
            para_text = ''.join(first_para.itertext()).strip()
            expected_title = 'Sample Recruitment Phone Script'
            if expected_title not in para_text:
                logger.warning(f"First paragraph does not contain expected title. Found: '{para_text}'")
            color = None
            para_style = first_para.get('{urn:oasis:names:tc:opendocument:xmlns:text:1.0}style-name')
            spans = first_para.findall('.//text:span', namespaces)
            auto_styles = root.find('.//office:automatic-styles', namespaces)
            if auto_styles is not None:
                if para_style:
                    style_elem = auto_styles.find(f'.//style:style[@style:name="{para_style}"]', namespaces)
                    if style_elem is not None:
                        text_props = style_elem.find('.//style:text-properties', namespaces)
                        if text_props is not None:
                            color = text_props.get('{urn:oasis:names:tc:opendocument:xmlns:xsl-fo-compatible:1.0}color')
                if color is None:
                    for span in spans:
                        span_style = span.get('{urn:oasis:names:tc:opendocument:xmlns:text:1.0}style-name')
                        if span_style:
                            style_elem = auto_styles.find(f'.//style:style[@style:name="{span_style}"]', namespaces)
                            if style_elem is not None:
                                text_props = style_elem.find('.//style:text-properties', namespaces)
                                if text_props is not None:
                                    color = text_props.get('{urn:oasis:names:tc:opendocument:xmlns:xsl-fo-compatible:1.0}color')
                                    if color:
                                        break
            return {'color': color}
        finally:
            if os.path.exists(tmp_path):
                os.unlink(tmp_path)
    except Exception as e:
        logger.error(f'Error checking color: {e}')
        return {'color': None}

def get_docx_title_format__6b952432076b60abfa1d5a5ccb6ba9ac(env, config):
    """Extract title paragraph formatting from a Word document.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: Title formatting information including text, font size, bold, alignment
    """
    file_path = config.get('path', '')
    if not file_path:
        return {}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        if len(doc.paragraphs) == 0:
            return {}
        title_para = doc.paragraphs[0]
        result = {'text': title_para.text.strip(), 'alignment': str(title_para.alignment) if title_para.alignment is not None else 'LEFT', 'font_size': None, 'bold': False, 'font_name': None}
        if len(title_para.runs) > 0:
            first_run = title_para.runs[0]
            if first_run.font.size:
                result['font_size'] = first_run.font.size.pt
            result['bold'] = first_run.font.bold if first_run.font.bold is not None else False
            result['font_name'] = first_run.font.name
        return result
    finally:
        os.unlink(tmp_path)

def get_docx_bold_words__7d6f236e93132e0aa7bafdaffae753c1(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract bold text information from first paragraph of a DOCX file.

    Reads the DOCX file and returns information about which words are bold
    in the first content paragraph.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict with bold word information
    """
    try:
        import sys
        sys.path.insert(0, '/usr/lib/python3/dist-packages')
        from docx import Document
    except ImportError:
        return {'error': 'python-docx not available'}
    file_path = config.get('path', '')
    if not file_path:
        return {'error': 'No path specified'}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'error': f'Could not read file: {file_path}'}
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        first_para = None
        for para in doc.paragraphs:
            if para.text.strip():
                first_para = para
                break
        if not first_para:
            return {'error': 'No non-empty paragraphs found'}
        bold_words = []
        for run in first_para.runs:
            if run.bold:
                words = run.text.split()
                bold_words.extend([w.lower().strip('.,!?;:') for w in words if w.strip()])
        return {'first_para_text': first_para.text, 'bold_words': bold_words, 'bold_word_count': len(bold_words)}
    finally:
        os.unlink(tmp_path)

