def get_docx_text_formatting__2ccb30d0bc330cfb3498fc1ffe64e170(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Extract text content and formatting from a DOCX file, along with source JSON data.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict containing paragraphs with text and formatting info, plus source JSON responses
    """
    file_path = config.get('path', '')
    if not file_path:
        return {'paragraphs': [], 'source_responses': []}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'paragraphs': [], 'source_responses': []}
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        paragraphs_data = []
        for (para_idx, para) in enumerate(doc.paragraphs):
            para_text = para.text
            if not para_text.strip():
                paragraphs_data.append({'text': '', 'runs': []})
                continue
            runs_data = []
            for run in para.runs:
                run_info = {'text': run.text, 'bold': run.bold if run.bold is not None else False, 'italic': run.italic if run.italic is not None else False, 'underline': run.underline if run.underline is not None else False}
                if run.font.highlight_color is not None:
                    run_info['highlight'] = str(run.font.highlight_color)
                else:
                    run_info['highlight'] = None
                runs_data.append(run_info)
            paragraphs_data.append({'text': para_text, 'runs': runs_data})
        source_json_path = '/home/user/Desktop/llm_answers.json'
        source_responses = []
        try:
            json_bytes = env.controller.get_file(source_json_path)
            if json_bytes:
                json_data = json.loads(json_bytes.decode('utf-8'))
                if isinstance(json_data, dict):
                    for (key, value) in json_data.items():
                        if 'GPT4' in key or 'gpt4' in key or 'gpt-4' in key:
                            if isinstance(value, str):
                                source_responses.append(value)
                            elif isinstance(value, list):
                                source_responses.extend([str(v) for v in value])
                        elif isinstance(value, dict) and ('response' in value or 'text' in value or 'content' in value):
                            response_text = value.get('response') or value.get('text') or value.get('content')
                            if response_text:
                                source_responses.append(str(response_text))
                elif isinstance(json_data, list):
                    for item in json_data:
                        if isinstance(item, dict):
                            if any(('gpt4' in str(k).lower() or 'gpt-4' in str(k).lower() for k in item.keys())):
                                response_text = item.get('response') or item.get('text') or item.get('content')
                                if response_text:
                                    source_responses.append(str(response_text))
                        elif isinstance(item, str):
                            source_responses.append(item)
        except Exception as e:
            pass
        return {'paragraphs': paragraphs_data, 'source_responses': source_responses}
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

def get_writer_last_para_italic__c229c32a319e90bb97341db58c4bb431(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract italic formatting information from the last paragraph of a DOCX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the DOCX file

    Returns:
        Dict with italic information about the last paragraph
    """
    try:
        file_bytes = env.controller.get_file(config['path'])
        if not file_bytes:
            logger.error(f"Failed to get file: {config['path']}")
            return {'has_italic': False}
        with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        try:
            doc = Document(tmp_path)
            last_para = None
            for para in reversed(doc.paragraphs):
                if para.text.strip():
                    last_para = para
                    break
            if last_para is None:
                logger.warning('No non-empty paragraphs found')
                return {'has_italic': False}
            has_italic = False
            for run in last_para.runs:
                if run.italic and run.text.strip():
                    has_italic = True
                    break
            return {'has_italic': has_italic, 'text_preview': last_para.text[:50]}
        finally:
            os.unlink(tmp_path)
    except Exception as e:
        logger.error(f'Error extracting italic info: {e}')
        return {'has_italic': False}

