def get_active_url_from_accessTree(env, config: Dict[str, str]):
    """Get active URL from accessibility tree"""
    import lxml.etree
    _accessibility_ns_map = {'st': 'uri:deskat:state.at-spi.gnome.org', 'attr': 'uri:deskat:attributes.at-spi.gnome.org', 'cp': 'uri:deskat:component.at-spi.gnome.org', 'doc': 'uri:deskat:document.at-spi.gnome.org', 'docattr': 'uri:deskat:attributes.document.at-spi.gnome.org', 'txt': 'uri:deskat:text.at-spi.gnome.org', 'val': 'uri:deskat:value.at-spi.gnome.org', 'act': 'uri:deskat:action.at-spi.gnome.org'}
    xml_str = env.controller.get_accessibility_tree()
    if xml_str is None:
        return None
    root = lxml.etree.fromstring(xml_str.encode('utf-8'))
    prefix = config.get('goto_prefix', 'https://www.')
    for frame in root.xpath("//frame[@st:focused='true']", namespaces=_accessibility_ns_map):
        name = frame.get('name')
        if name and name.startswith(prefix):
            return name
    return None

def get_ext_enabled_status__b3e890183c7023f0433e90e86375ba61(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Get the enabled status of an unpacked extension at a specific path.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'extension_path' key

    Returns:
        Dict with 'path', 'enabled', and 'found' keys
    """
    os_type = env.vm_platform
    target_path = config.get('extension_path', '')
    if os_type == 'Windows':
        preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('LOCALAPPDATA'),\n            'Google\\Chrome\\User Data\\Default\\Preferences'))")['output'].strip()
    elif os_type == 'Darwin':
        preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), 'Library/Application Support/Google/Chrome/Default/Preferences'))")['output'].strip()
    elif os_type == 'Linux':
        if 'arm' in platform.machine():
            preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), 'snap/chromium/common/chromium/Default/Preferences'))")['output'].strip()
        else:
            preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), '.config/google-chrome/Default/Preferences'))")['output'].strip()
    else:
        raise Exception('Unsupported operating system')
    try:
        content = env.controller.get_file(preference_file_path)
        data = json.loads(content)
        all_extensions = data.get('extensions', {}).get('settings', {})
        for (ext_id, ext_data) in all_extensions.items():
            path = ext_data.get('path', '')
            if path == target_path:
                state = ext_data.get('state', 0)
                return {'path': path, 'enabled': state == 1, 'found': True}
        return {'path': target_path, 'enabled': False, 'found': False}
    except Exception as e:
        logger.error(f'Error reading Chrome Preferences file: {e}')
        return {'path': target_path, 'enabled': False, 'found': False}

def get_docx_first_line_indent__2b727758(env, config):
    """
    Extract first-line indentation values from paragraphs in a .docx file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: Statistics about first-line indentation including count and avg
    """
    from docx import Document
    from docx.shared import Pt
    import io
    file_path = config['path']
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'count': 0, 'with_indent': 0, 'avg_indent': 0}
    doc = Document(io.BytesIO(file_bytes))
    para_count = 0
    with_indent_count = 0
    indent_sum = 0
    for para in doc.paragraphs:
        if para.text.strip():
            para_count += 1
            first_line_indent = para.paragraph_format.first_line_indent
            if first_line_indent and first_line_indent > 0:
                with_indent_count += 1
                indent_sum += first_line_indent.pt
    avg_indent = indent_sum / with_indent_count if with_indent_count > 0 else 0
    return {'count': para_count, 'with_indent': with_indent_count, 'avg_indent': avg_indent}

def get_docx_alignment__a8ff2fd074ac464fd585d401137e176f(env, config: Dict[str, Any]):
    """Extract paragraph alignment from a DOCX file and check if it was modified.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM path) and 'dest' (cache filename)

    Returns:
        Dict with alignments: dict mapping paragraph index to alignment name
              and file_modified: boolean indicating if file was modified after task start
    """
    path = config['path']
    dest = config.get('dest', os.path.basename(path))
    file_mtime = None
    try:
        stat_result = env.controller.execute(f"stat -c %Y '{path}'")
        if stat_result and stat_result.strip().isdigit():
            file_mtime = int(stat_result.strip())
    except Exception as e:
        print(f'Error getting file modification time: {e}')
    file_bytes = env.controller.get_file(path)
    if not file_bytes:
        return {'alignments': {}, 'file_modified': False}
    cache_path = os.path.join(env.cache_dir, dest)
    os.makedirs(env.cache_dir, exist_ok=True)
    with open(cache_path, 'wb') as f:
        f.write(file_bytes)
    file_modified = False
    if file_mtime is not None and hasattr(env, 'start_time'):
        file_modified = file_mtime > env.start_time
    try:
        doc = Document(cache_path)
        alignments = {}
        for (i, paragraph) in enumerate(doc.paragraphs):
            alignment = paragraph.paragraph_format.alignment
            if alignment == WD_PARAGRAPH_ALIGNMENT.CENTER:
                alignments[i] = 'CENTER'
            elif alignment == WD_PARAGRAPH_ALIGNMENT.LEFT:
                alignments[i] = 'LEFT'
            elif alignment == WD_PARAGRAPH_ALIGNMENT.RIGHT:
                alignments[i] = 'RIGHT'
            elif alignment == WD_PARAGRAPH_ALIGNMENT.JUSTIFY:
                alignments[i] = 'JUSTIFY'
            else:
                alignments[i] = 'NONE'
        return {'alignments': alignments, 'file_modified': file_modified}
    except Exception as e:
        print(f'Error reading DOCX: {e}')
        return {'alignments': {}, 'file_modified': False}

