def get_docx_para_underline_count__1d2131d8(env, config: dict) -> int:
    """Count number of underlined paragraphs in DOCX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        int: Number of paragraphs that are underlined
    """
    file_path = config.get('path', '/home/user/Desktop/CCCH9003_Tutorial_guidelines.docx')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return 0
    doc = Document(io.BytesIO(file_bytes))
    underline_count = 0
    for para in doc.paragraphs:
        if para.text.strip():
            if para.runs:
                if all((run.underline for run in para.runs if run.text.strip())):
                    underline_count += 1
    return underline_count

def get_docx_contains_phrases__f5820188(env, config):
    """
    Read a docx file and check which phrases from a list are present.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'phrases' keys

    Returns:
        list: List of phrases that were found in the document
    """
    from docx import Document
    import tempfile
    import os
    file_path = config.get('path', '')
    phrases = config.get('phrases', [])
    try:
        file_bytes = env.controller.get_file(file_path)
        if file_bytes is None:
            return []
        with tempfile.NamedTemporaryFile(delete=False, suffix='.docx') as tmp_file:
            tmp_file.write(file_bytes)
            tmp_path = tmp_file.name
        try:
            doc = Document(tmp_path)
            full_text = '\n'.join([para.text for para in doc.paragraphs])
            found = []
            for phrase in phrases:
                if phrase.lower() in full_text.lower():
                    found.append(phrase)
            return found
        finally:
            if os.path.exists(tmp_path):
                os.unlink(tmp_path)
    except Exception as e:
        return []

def get_docx_reference_text__4ebdf6683df2ead225927fa34f510869(env, config: Dict[str, Any]) -> str:
    """Extract text from References section of a docx file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key for the docx file path

    Returns:
        str: Text from References section only, or empty string if section not found
    """
    file_path = config.get('path', '')
    if not file_path:
        return ''
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return ''
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        from docx import Document
        doc = Document(tmp_path)
        references_text = []
        in_references_section = False
        for para in doc.paragraphs:
            text = para.text.strip()
            if text.lower() in ['references', 'reference', 'bibliography', 'works cited']:
                in_references_section = True
                continue
            if in_references_section:
                if text and len(text) > 0:
                    is_potential_heading = len(text) < 50 and (text.isupper() or (text[0].isupper() and ':' not in text and ('.' not in text[:20]))) and (not any((c.isdigit() for c in text[:10])))
                    if is_potential_heading and text.lower() in ['appendix', 'appendices', 'notes', 'acknowledgments', 'acknowledgements', 'index', 'glossary']:
                        break
                    references_text.append(text)
        return '\n'.join(references_text)
    except Exception as e:
        print(f'Error reading docx: {e}')
        return ''
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

