def get_docx_nonempty_para_count__59156416(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Parse a docx file and extract paper entries.
    Each paper should have 4 lines: title, authors, abstract, and arxiv link.

    Args:
        env: Environment object
        config: Configuration dict with 'path' key pointing to the docx file

    Returns:
        Dict containing:
            - 'papers': List of paper dicts with 'title', 'authors', 'abstract', 'link'
            - 'valid_paper_count': Number of valid papers found
    """
    path = config['path']
    cache_dir = env.cache_dir
    dest = os.path.basename(path)
    _path = os.path.join(cache_dir, dest)
    content = env.controller.get_vm_file(path)
    if content is None:
        logger.error(f'Failed to get file from VM: {path}')
        return {'papers': [], 'valid_paper_count': 0}
    with open(_path, 'wb') as f:
        f.write(content)
    try:
        doc = Document(_path)
        paragraphs = []
        for para in doc.paragraphs:
            text = para.text.strip()
            if text:
                paragraphs.append(text)
        logger.info(f'Found {len(paragraphs)} non-empty paragraphs')
        papers = []
        valid_paper_count = 0
        i = 0
        while i + 3 < len(paragraphs):
            title = paragraphs[i].strip()
            authors = paragraphs[i + 1].strip()
            abstract = paragraphs[i + 2].strip()
            link = paragraphs[i + 3].strip()
            is_valid = len(title) >= 5 and len(authors) >= 3 and (len(abstract) >= 20) and (len(link) >= 10) and ('arxiv' in link.lower())
            paper = {'title': title, 'authors': authors, 'abstract': abstract, 'link': link, 'is_valid': is_valid}
            papers.append(paper)
            if is_valid:
                valid_paper_count += 1
            i += 4
        logger.info(f'Found {len(papers)} paper entries, {valid_paper_count} are valid')
        return {'papers': papers, 'valid_paper_count': valid_paper_count, 'total_paragraphs': len(paragraphs)}
    except Exception as e:
        logger.error(f'Error parsing docx file {path}: {e}')
        return {'papers': [], 'valid_paper_count': 0, 'total_paragraphs': 0}

def get_docx_first_line_alignment__de33d712(env, config: dict):
    """Extract first paragraph alignment from DOCX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with file path

    Returns:
        str: Alignment type ('LEFT', 'CENTER', 'RIGHT', 'JUSTIFY', or 'NONE')
    """
    file_path = config.get('path', '')
    if not file_path:
        return 'NONE'
    try:
        file_bytes = env.controller.get_file(file_path)
        if not file_bytes:
            return 'NONE'
        from io import BytesIO
        doc = Document(BytesIO(file_bytes))
        if not doc.paragraphs:
            return 'NONE'
        first_para = doc.paragraphs[0]
        alignment = first_para.paragraph_format.alignment
        if alignment == WD_PARAGRAPH_ALIGNMENT.LEFT:
            return 'LEFT'
        elif alignment == WD_PARAGRAPH_ALIGNMENT.CENTER:
            return 'CENTER'
        elif alignment == WD_PARAGRAPH_ALIGNMENT.RIGHT:
            return 'RIGHT'
        elif alignment == WD_PARAGRAPH_ALIGNMENT.JUSTIFY:
            return 'JUSTIFY'
        else:
            return 'LEFT'
    except Exception as e:
        print(f'Error reading DOCX alignment: {e}')
        return 'NONE'

def get_docx_para_strikethrough__99c63b9d(env, config):
    """Check if a specific paragraph has strikethrough.

    Args:
        env: DesktopEnv instance
        config: Config with 'path', 'dest', and 'para_idx'

    Returns:
        dict: {"para_idx": int, "is_strikethrough": bool}
    """
    file_path = config.get('path', '')
    para_idx = config.get('para_idx', 0)
    file_bytes = env.controller.get_file(file_path)
    if file_bytes is None:
        return {'para_idx': para_idx, 'is_strikethrough': False}
    doc = Document(io.BytesIO(file_bytes))
    if para_idx >= len(doc.paragraphs):
        return {'para_idx': para_idx, 'is_strikethrough': False}
    para = doc.paragraphs[para_idx]
    if not para.runs:
        return {'para_idx': para_idx, 'is_strikethrough': False}
    strikethrough_runs = sum((1 for run in para.runs if run.font.strike))
    total_runs = len(para.runs)
    is_strikethrough = strikethrough_runs / total_runs >= 0.8
    return {'para_idx': para_idx, 'is_strikethrough': is_strikethrough}

