def get_docx_station_ranking__201b847b(env, config):
    """Get stations ranked by frequency (most common first).

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and optional 'top_n' keys

    Returns:
        List of tuples (station_id, count) sorted by count descending
    """
    file_path = config.get('path')
    top_n = config.get('top_n', None)
    if not file_path:
        logger.error('No file path provided in config')
        return []
    try:
        file_bytes = env.controller.get_file(file_path)
        if not file_bytes:
            logger.error(f'Could not retrieve file from VM: {file_path}')
            return []
        import tempfile
        with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        doc = Document(tmp_path)
        station_counts = {}
        for para in doc.paragraphs:
            text = para.text.strip()
            if text:
                parts = text.split(',')
                if len(parts) >= 3:
                    station = parts[2].strip()
                    station_counts[station] = station_counts.get(station, 0) + 1
        import os
        os.unlink(tmp_path)
        sorted_stations = sorted(station_counts.items(), key=lambda x: (-x[1], x[0]))
        if top_n is not None:
            return sorted_stations[:top_n]
        return sorted_stations
    except Exception as e:
        logger.error(f'Error ranking stations: {e}')
        return []

