def get_docx_line_count__e2e4b1c2(env, config):
    """Get document line information including counts and last line text.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: {
            'total_line_count': int,  # Total non-empty lines
            'has_empty_lines': bool,  # Whether any empty lines exist
            'last_line_text': str,    # Text of the last non-empty line
            'record_count': int       # Count of non-empty lines excluding last line
        }
    """
    file_path = config.get('path')
    if not file_path:
        logger.error('No file path provided in config')
        return {'total_line_count': 0, 'has_empty_lines': False, 'last_line_text': '', 'record_count': 0}
    try:
        file_bytes = env.controller.get_file(file_path)
        if not file_bytes:
            logger.error(f'Could not retrieve file from VM: {file_path}')
            return {'total_line_count': 0, 'has_empty_lines': False, 'last_line_text': '', 'record_count': 0}
        import tempfile
        import os
        with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        doc = Document(tmp_path)
        all_paragraphs = doc.paragraphs
        has_empty_lines = any((not para.text.strip() for para in all_paragraphs))
        non_empty_paras = [para for para in all_paragraphs if para.text.strip()]
        total_line_count = len(non_empty_paras)
        last_line_text = non_empty_paras[-1].text.strip() if non_empty_paras else ''
        record_count = total_line_count - 1 if total_line_count > 0 else 0
        os.unlink(tmp_path)
        return {'total_line_count': total_line_count, 'has_empty_lines': has_empty_lines, 'last_line_text': last_line_text, 'record_count': record_count}
    except Exception as e:
        logger.error(f'Error analyzing document: {e}')
        return {'total_line_count': 0, 'has_empty_lines': False, 'last_line_text': '', 'record_count': 0}

