def get_docx_para_bold__e827cac2f74d65f3a208e0b75b986710(env, config: Dict[str, Any]) -> Dict[int, bool]:
    """Extract bold formatting status from specified paragraphs in a DOCX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - path: VM path to the .docx file
            - paragraph_indices: List of paragraph indices to check

    Returns:
        Dict mapping paragraph index to boolean (True if all runs are bold)
    """
    file_path = config.get('path')
    if not file_path:
        logger.error('No file path provided in config')
        return {}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        logger.error(f'Failed to get file from VM: {file_path}')
        return {}
    import tempfile
    import os
    try:
        with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        doc = Document(tmp_path)
        paragraph_indices = config.get('paragraph_indices', [])
        result = {}
        for idx in paragraph_indices:
            if idx < len(doc.paragraphs):
                para = doc.paragraphs[idx]
                if para.runs:
                    text_runs = [r for r in para.runs if r.text.strip()]
                    if text_runs:
                        is_bold = all((r.font.bold for r in text_runs))
                        result[idx] = is_bold
                    else:
                        result[idx] = False
                else:
                    result[idx] = False
            else:
                logger.warning(f'Paragraph index {idx} out of range')
                result[idx] = False
        return result
    except Exception as e:
        logger.error(f'Error processing DOCX file: {e}')
        return {}
    finally:
        if 'tmp_path' in locals() and os.path.exists(tmp_path):
            os.unlink(tmp_path)

def get_docx_word_count__b9089229(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Get word count and text content of the conclusion paragraph (index 14) of a DOCX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path'

    Returns:
        dict: Dictionary with 'word_count' (int) and 'text' (str) of paragraph 14
    """
    file_path = config.get('path', '')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'word_count': 0, 'text': ''}
    import tempfile
    with tempfile.NamedTemporaryFile(delete=False, suffix='.docx') as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        if len(doc.paragraphs) > 14:
            para_text = doc.paragraphs[14].text.strip()
            word_count = len(para_text.split())
            return {'word_count': word_count, 'text': para_text}
        return {'word_count': 0, 'text': ''}
    finally:
        import os
        os.unlink(tmp_path)

