def get_bib_author_count__4924bfa1(env, config: dict):
    """Extract information about the Attention paper bibtex entry.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' parameter

    Returns:
        dict: Information about the bibtex entry including:
            - has_entry: bool, whether any bibtex entry exists
            - entry_type: str, type of entry (@inproceedings, @article, etc.)
            - title: str, title of the paper
            - author_count: int, number of authors
            - booktitle: str, conference/journal name
            - has_attention_title: bool, whether title contains 'Attention'
            - is_conference: bool, whether entry type is @inproceedings
            - is_nips: bool, whether booktitle contains NIPS/NeurIPS
            - has_vaswani: bool, whether Vaswani is an author
            - entry_count: int, total number of bibtex entries in file
    """
    import re
    path = config.get('path', '/home/user/Desktop/references.bib')
    file_content = env.controller.get_file(path)
    if not file_content:
        return {'has_entry': False, 'entry_type': '', 'title': '', 'author_count': 0, 'booktitle': '', 'has_attention_title': False, 'is_conference': False, 'is_nips': False, 'has_vaswani': False, 'entry_count': 0}
    content = file_content.decode('utf-8', errors='ignore')
    entry_pattern = '@(\\w+)\\s*\\{([^@]*?)\\n\\}'
    all_entries = re.findall(entry_pattern, content, re.MULTILINE | re.DOTALL)
    entry_count = len(all_entries)
    target_entry = None
    entry_type = ''
    for (etype, entry_content) in all_entries:
        title_match = re.search('title\\s*=\\s*\\{([^}]+)\\}', entry_content, re.IGNORECASE)
        if title_match:
            title = title_match.group(1).strip()
            if 'attention' in title.lower():
                target_entry = entry_content
                entry_type = etype.lower()
                break
    if not target_entry:
        return {'has_entry': False, 'entry_type': '', 'title': '', 'author_count': 0, 'booktitle': '', 'has_attention_title': False, 'is_conference': False, 'is_nips': False, 'has_vaswani': False, 'entry_count': entry_count}
    title_match = re.search('title\\s*=\\s*\\{([^}]+)\\}', target_entry, re.IGNORECASE)
    title = title_match.group(1).strip() if title_match else ''
    author_match = re.search('author\\s*=\\s*\\{([^}]+)\\}', target_entry, re.IGNORECASE | re.MULTILINE | re.DOTALL)
    author_count = 0
    has_vaswani = False
    if author_match:
        author_field = author_match.group(1)
        individual_authors = re.split('\\s+and\\s+', author_field)
        authors_set = set()
        for author in individual_authors:
            cleaned = ' '.join(author.split()).strip()
            if cleaned:
                authors_set.add(cleaned)
                if 'vaswani' in cleaned.lower():
                    has_vaswani = True
        author_count = len(authors_set)
    booktitle_match = re.search('booktitle\\s*=\\s*\\{([^}]+)\\}', target_entry, re.IGNORECASE)
    booktitle = booktitle_match.group(1).strip() if booktitle_match else ''
    has_attention_title = 'attention' in title.lower()
    is_conference = entry_type == 'inproceedings'
    is_nips = any((keyword in booktitle.lower() for keyword in ['nips', 'neurips']))
    return {'has_entry': True, 'entry_type': entry_type, 'title': title, 'author_count': author_count, 'booktitle': booktitle, 'has_attention_title': has_attention_title, 'is_conference': is_conference, 'is_nips': is_nips, 'has_vaswani': has_vaswani, 'entry_count': entry_count}

def get_nba_store_filters__9f3f70fc(env, config: Dict[str, Any]):
    """
    Get applied filters from NBA store page.
    This function checks both the page HTML for filter elements and the URL for filter parameters.
    It uses multiple selector strategies to find filter elements and product listings.

    Args:
        env: Environment object
        config: Configuration dict with:
            - expected_filters: list of expected filter terms (e.g., ["under $100", "men", "shoes", "jordan"])

    Returns:
        dict: Dictionary with filter terms as keys and boolean values indicating if they're applied.
              Also includes "is_other_exist" to indicate unexpected filters.
              Also includes "has_products" to verify products are displayed.
    """
    logger.info('[NBA_STORE_FILTERS] Starting to get NBA store filters')
    from lxml.cssselect import CSSSelector
    import lxml.etree
    _accessibility_ns_map = {'st': 'uri:deskat:state.at-spi.gnome.org', 'attr': 'uri:deskat:attributes.at-spi.gnome.org', 'cp': 'uri:deskat:component.at-spi.gnome.org', 'doc': 'uri:deskat:document.at-spi.gnome.org', 'docattr': 'uri:deskat:attributes.document.at-spi.gnome.org', 'txt': 'uri:deskat:text.at-spi.gnome.org', 'val': 'uri:deskat:value.at-spi.gnome.org', 'act': 'uri:deskat:action.at-spi.gnome.org'}
    if hasattr(env, 'controller') and callable(getattr(env.controller, 'get_accessibility_tree', None)):
        accessibility_tree = env.controller.get_accessibility_tree()
        if accessibility_tree is None:
            logger.error('[NBA_STORE_FILTERS] Failed to get accessibility tree')
            return {}
    else:
        logger.error("[NBA_STORE_FILTERS] Controller or method 'get_accessibility_tree' not found")
        return {}
    try:
        at = lxml.etree.fromstring(accessibility_tree)
    except Exception as e:
        logger.error(f'[NBA_STORE_FILTERS] Error parsing accessibility tree: {e}')
        return {}
    arch = platform.machine()
    if 'arm' in arch:
        selector_string = 'application[name=Chromium] entry[name=Address\\ and\\ search\\ bar]'
    else:
        selector_string = 'application[name=Google\\ Chrome] entry[name=Address\\ and\\ search\\ bar]'
    try:
        selector = CSSSelector(selector_string, namespaces=_accessibility_ns_map)
    except Exception as e:
        logger.error(f'[NBA_STORE_FILTERS] Failed to parse selector: {e}')
        return {}
    elements = selector(at) if selector else []
    if not elements:
        logger.error('[NBA_STORE_FILTERS] No address bar element found')
        return {}
    active_element = elements[0]
    if not active_element.text:
        logger.error('[NBA_STORE_FILTERS] No text in address bar')
        return {}
    goto_prefix = config.get('goto_prefix', 'https://')
    active_tab_url = f'{goto_prefix}{active_element.text}'
    logger.info(f'[NBA_STORE_FILTERS] Active tab URL: {active_tab_url}')
    host = env.vm_ip
    port = env.chromium_port
    server_port = env.server_port
    remote_debugging_url = f'http://{host}:{port}'
    expected_filters = config.get('expected_filters', [])
    logger.info(f'[NBA_STORE_FILTERS] Expected filters: {expected_filters}')
    try:
        with sync_playwright() as p:
            try:
                browser = p.chromium.connect_over_cdp(remote_debugging_url)
                logger.info('[NBA_STORE_FILTERS] Connected to Chrome')
            except Exception as e:
                logger.error(f'[NBA_STORE_FILTERS] Failed to connect to Chrome: {e}')
                return {}
            target_page = None
            for context in browser.contexts:
                for page in context.pages:
                    try:
                        page.wait_for_load_state('networkidle', timeout=10000)
                        if page.is_closed():
                            continue
                        page_url = page.url
                        if unquote(page_url).rstrip('/') == unquote(active_tab_url).rstrip('/'):
                            target_page = page
                            logger.info(f'[NBA_STORE_FILTERS] Found target page: {page_url}')
                            break
                    except Exception as e:
                        logger.debug(f'[NBA_STORE_FILTERS] Error checking page: {e}')
                        continue
            if target_page is None:
                logger.error('[NBA_STORE_FILTERS] Could not find target page')
                browser.close()
                return {}
            result = {}
            for filter_term in expected_filters:
                result[filter_term.lower()] = False
            try:
                page_url = target_page.url.lower()
                logger.info(f'[NBA_STORE_FILTERS] Checking URL: {page_url}')
                parsed_url = urlparse(target_page.url)
                query_params = parse_qs(parsed_url.query)
                logger.info(f'[NBA_STORE_FILTERS] URL query params: {query_params}')
                for filter_term in expected_filters:
                    filter_lower = filter_term.lower()
                    if filter_lower in page_url or filter_lower.replace(' ', '-') in page_url or filter_lower.replace(' ', '%20') in page_url:
                        result[filter_lower] = True
                        logger.info(f"[NBA_STORE_FILTERS] Found '{filter_term}' in URL")
            except Exception as e:
                logger.warning(f'[NBA_STORE_FILTERS] Error checking URL: {e}')
            filter_selectors = ["[class*='filter']", "[class*='facet']", "[class*='refinement']", "[class*='tag']", "[class*='pill']", "[class*='chip']", "[class*='selected']", "[class*='active']", "[class*='applied']", "[class*='badge']", '[data-filter]', '[data-facet]', '[data-refinement]', "[aria-label*='filter']", "[aria-label*='Remove']", "[aria-label*='selected']", '.filter-selector-link', "button[class*='filter']", "span[class*='filter']", "div[class*='filter']", "[class*='Filter']", "[class*='ProductFilter']", "[class*='refinement-bar']", "[class*='applied-filter']"]
            found_filter_texts = []
            for selector in filter_selectors:
                try:
                    elements = target_page.query_selector_all(selector)
                    if elements:
                        logger.info(f"[NBA_STORE_FILTERS] Found {len(elements)} elements with selector '{selector}'")
                        for element in elements[:20]:
                            try:
                                text = element.text_content()
                                if text:
                                    text = text.strip()
                                    if text and len(text) < 100:
                                        found_filter_texts.append(text)
                            except:
                                pass
                except Exception as e:
                    logger.debug(f"[NBA_STORE_FILTERS] Selector '{selector}' failed: {e}")
                    continue
            found_filter_texts = list(dict.fromkeys(found_filter_texts))
            logger.info(f'[NBA_STORE_FILTERS] Found filter texts: {found_filter_texts}')
            for filter_term in expected_filters:
                filter_lower = filter_term.lower()
                for found_text in found_filter_texts:
                    found_lower = found_text.lower()
                    if filter_lower in found_lower or found_lower in filter_lower:
                        result[filter_lower] = True
                        logger.info(f"[NBA_STORE_FILTERS] Found '{filter_term}' in page element: '{found_text}'")
                        break
            result['is_other_exist'] = False
            for found_text in found_filter_texts:
                found_lower = found_text.lower()
                matches_expected = False
                for filter_term in expected_filters:
                    filter_lower = filter_term.lower()
                    if filter_lower in found_lower or found_lower in filter_lower:
                        matches_expected = True
                        break
                if not matches_expected and len(found_text) > 2 and (len(found_text) < 50):
                    non_filter_keywords = ['search', 'menu', 'cart', 'account', 'sign', 'login', 'close', 'back', 'next', 'previous']
                    is_non_filter = any((keyword in found_lower for keyword in non_filter_keywords))
                    if not is_non_filter:
                        logger.warning(f"[NBA_STORE_FILTERS] Found unexpected filter text: '{found_text}'")
                        result['is_other_exist'] = True
                        break
            product_selectors = ["[class*='product']", "[class*='Product']", "[class*='item']", "[class*='Item']", "[class*='card']", "[class*='Card']", '[data-product]', '[data-item]', "[data-qa*='product']", 'article', '.product-card', '.product-item', '.product-grid', "[class*='ProductCard']", "[class*='product-tile']", "[class*='shoe-card']"]
            product_count = 0
            for selector in product_selectors:
                try:
                    elements = target_page.query_selector_all(selector)
                    for element in elements:
                        try:
                            html = element.inner_html().lower()
                            text = element.text_content()
                            has_price = '$' in text or 'price' in html or 'usd' in html
                            has_image = 'img' in html or 'image' in html
                            has_link = 'href' in html or '<a' in html
                            is_reasonable_size = len(html) > 100 and len(html) < 50000
                            if (has_price or has_image) and is_reasonable_size:
                                product_count += 1
                                if product_count >= 3:
                                    logger.info(f"[NBA_STORE_FILTERS] Found product-like element with selector '{selector}'")
                                    break
                        except:
                            pass
                    if product_count >= 3:
                        break
                except Exception as e:
                    logger.debug(f"[NBA_STORE_FILTERS] Product selector '{selector}' failed: {e}")
                    continue
            result['has_products'] = product_count >= 3
            logger.info(f"[NBA_STORE_FILTERS] Product count estimate: {product_count}, has_products: {result['has_products']}")
            browser.close()
            logger.info(f'[NBA_STORE_FILTERS] Final result: {result}')
            return result
    except Exception as e:
        logger.error(f'[NBA_STORE_FILTERS] Error: {e}')
        return {}

def get_docx_reference_text__1c2bc3649ac7e718b9bda55292e2182a(env, config: Dict[str, Any]) -> str:
    """Extract text from References section of a docx file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key for the docx file path

    Returns:
        str: Text from the References section only (including the References heading and all content until the next section or end of document)
    """
    file_path = config.get('path', '')
    if not file_path:
        return ''
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return ''
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        from docx import Document
        doc = Document(tmp_path)
        references_text = []
        in_references_section = False
        for para in doc.paragraphs:
            text = para.text.strip()
            if text.lower() in ['references', 'reference', 'bibliography', 'works cited']:
                in_references_section = True
                references_text.append(text)
                continue
            if in_references_section:
                if text and len(text) < 50 and text.isupper() and (text not in references_text):
                    break
                if text:
                    references_text.append(text)
        return '\n'.join(references_text)
    except Exception as e:
        print(f'Error reading docx: {e}')
        return ''
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

def get_docx_font_colors__19e803f1f0b772e18ba3645767900e72(env, config: Dict[str, Any]) -> List[Tuple[int, int, int]]:
    """Extract font colors from the document.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key for file path on VM

    Returns:
        List of RGB color tuples (r, g, b) found in the document
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return []
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        colors = []
        for paragraph in doc.paragraphs:
            for run in paragraph.runs:
                if run.text.strip() and run.font.color and run.font.color.rgb:
                    rgb = run.font.color.rgb
                    color_tuple = (rgb[0], rgb[1], rgb[2])
                    colors.append(color_tuple)
        for table in doc.tables:
            for row in table.rows:
                for cell in row.cells:
                    for paragraph in cell.paragraphs:
                        for run in paragraph.runs:
                            if run.text.strip() and run.font.color and run.font.color.rgb:
                                rgb = run.font.color.rgb
                                color_tuple = (rgb[0], rgb[1], rgb[2])
                                colors.append(color_tuple)
        for section in doc.sections:
            if section.header:
                for paragraph in section.header.paragraphs:
                    for run in paragraph.runs:
                        if run.text.strip() and run.font.color and run.font.color.rgb:
                            rgb = run.font.color.rgb
                            color_tuple = (rgb[0], rgb[1], rgb[2])
                            colors.append(color_tuple)
            if section.footer:
                for paragraph in section.footer.paragraphs:
                    for run in paragraph.runs:
                        if run.text.strip() and run.font.color and run.font.color.rgb:
                            rgb = run.font.color.rgb
                            color_tuple = (rgb[0], rgb[1], rgb[2])
                            colors.append(color_tuple)
        return colors
    finally:
        os.unlink(tmp_path)

