def get_docx_citation_doi__604e43d2(env, config: Dict[str, Any]) -> dict:
    """Extract DOI from a specific reference.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'author'

    Returns:
        dict: Contains 'found' and 'doi' fields (doi is the extracted DOI string or None)
    """
    file_path = config.get('path', '')
    author = config.get('author', '')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'found': False, 'doi': None}
    import tempfile
    with tempfile.NamedTemporaryFile(delete=False, suffix='.docx') as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        in_references = False
        for para in doc.paragraphs:
            text = para.text.strip()
            if text == 'References':
                in_references = True
                continue
            if in_references and author.lower() in text.lower():
                doi_pattern = '10\\.\\d{4,}/[^\\s,;]+'
                match = re.search(doi_pattern, text)
                doi_value = match.group(0) if match else None
                return {'found': True, 'doi': doi_value}
        return {'found': False, 'doi': None}
    finally:
        import os
        os.unlink(tmp_path)

def get_docx_para_font_size__a90829ab367a8620a4069966fc2b957c(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract font size information from first paragraph of a DOCX file.

    Reads the DOCX file and returns font size information for the first paragraph.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict with font size information
    """
    try:
        import sys
        sys.path.insert(0, '/usr/lib/python3/dist-packages')
        from docx import Document
        from docx.shared import Pt
    except ImportError:
        return {'error': 'python-docx not available'}
    file_path = config.get('path', '')
    if not file_path:
        return {'error': 'No path specified'}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'error': f'Could not read file: {file_path}'}
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        first_para = None
        for para in doc.paragraphs:
            if para.text.strip():
                first_para = para
                break
        if not first_para:
            return {'error': 'No non-empty paragraphs found'}
        font_sizes = []
        for run in first_para.runs:
            if run.font.size is not None:
                size_pt = run.font.size.pt
                font_sizes.append(size_pt)
        if font_sizes:
            predominant_size = max(set(font_sizes), key=font_sizes.count)
        else:
            predominant_size = None
        return {'first_para_text': first_para.text[:100] + '...', 'font_sizes': font_sizes, 'predominant_font_size': predominant_size, 'all_runs_same_size': len(set(font_sizes)) <= 1 if font_sizes else True}
    finally:
        os.unlink(tmp_path)

def get_docx_line_spacing__378c589d(env, config):
    """
    Extract line spacing information from paragraphs in a .docx file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: Line spacing statistics
    """
    from docx import Document
    import io
    file_path = config['path']
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'count': 0, 'with_spacing_15': 0}
    doc = Document(io.BytesIO(file_bytes))
    para_count = 0
    spacing_15_count = 0
    for para in doc.paragraphs:
        if para.text.strip():
            para_count += 1
            line_spacing = para.paragraph_format.line_spacing
            if line_spacing is not None:
                if isinstance(line_spacing, (int, float)):
                    if abs(line_spacing - 1.5) < 0.1:
                        spacing_15_count += 1
    return {'count': para_count, 'with_spacing_15': spacing_15_count}

