def get_docx_first_para_alignment__a04c3ecf(env, config):
    """Extract alignment of first non-empty paragraph from a DOCX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM path) and 'dest' (local filename)

    Returns:
        str: Alignment of first paragraph ('LEFT', 'CENTER', 'RIGHT', 'JUSTIFY', or 'UNKNOWN')
    """
    vm_path = config.get('path', '/home/user/Desktop/View_Person_Organizational_Summary.docx')
    dest = config.get('dest', 'temp.docx')
    file_bytes = env.controller.get_file(vm_path)
    if file_bytes is None:
        return 'UNKNOWN'
    cache_path = os.path.join(env.cache_dir, dest)
    with open(cache_path, 'wb') as f:
        f.write(file_bytes)
    doc = Document(cache_path)
    for paragraph in doc.paragraphs:
        if paragraph.text.strip():
            alignment = paragraph.alignment
            if alignment is None:
                return 'LEFT'
            elif alignment == WD_ALIGN_PARAGRAPH.CENTER:
                return 'CENTER'
            elif alignment == WD_ALIGN_PARAGRAPH.RIGHT:
                return 'RIGHT'
            elif alignment == WD_ALIGN_PARAGRAPH.JUSTIFY:
                return 'JUSTIFY'
            elif alignment == WD_ALIGN_PARAGRAPH.LEFT:
                return 'LEFT'
            else:
                return 'UNKNOWN'
    return 'UNKNOWN'

