def get_odt_large_font_text__3803d9ad(env, config):
    """Extract text with large font size from an ODT file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'min_size' parameters

    Returns:
        list: List of text strings with large font size
    """
    vm_path = config.get('path', '/home/user/Desktop/sample-recruitment-phone-script.odt')
    min_size = config.get('min_size', 14)
    file_bytes = env.controller.get_file(vm_path)
    if not file_bytes:
        return []
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(delete=False, suffix='.odt') as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = load(tmp_path)
        large_font_texts = []
        for span in doc.getElementsByType(text.Span):
            style_name = span.getAttribute('stylename')
            if style_name:
                for auto_style in doc.automaticstyles.getElementsByType(style.Style):
                    if auto_style.getAttribute('name') == style_name:
                        text_props = auto_style.getElementsByType(style.TextProperties)
                        for prop in text_props:
                            font_size = prop.getAttribute('fontsize')
                            if font_size:
                                try:
                                    size_value = float(font_size.replace('pt', '').replace('px', ''))
                                    if size_value >= min_size:
                                        span_text = teletype.extractText(span)
                                        if span_text.strip():
                                            large_font_texts.append(span_text.strip())
                                except:
                                    pass
        return large_font_texts
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

def get_odt_word_underline_status__c07aee31dfd51c934e0b2ff5d2b5bcfd(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract underline formatting status for specific words in ODT file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'target_word'

    Returns:
        Dict with word instances and their underline status
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'instances': [], 'all_underlined': False, 'count': 0}
    with tempfile.NamedTemporaryFile(suffix='.odt', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = load(tmp_path)
        target_word = config.get('target_word', '')
        word_instances = []

        def check_underline_in_style(style_name):
            """Check if a style has underline formatting."""
            if not style_name:
                return False
            if hasattr(doc, 'automaticstyles') and doc.automaticstyles:
                for automatic_style in doc.automaticstyles.childNodes:
                    if automatic_style.getAttribute('name') == style_name:
                        for property in automatic_style.childNodes:
                            text_underline_style = property.getAttribute('textunderlinestyle')
                            text_underline_type = property.getAttribute('textunderlinetype')
                            text_underline_width = property.getAttribute('textunderlinewidth')
                            if text_underline_style and text_underline_style != 'none':
                                return True
                            if text_underline_type and text_underline_type != 'none':
                                return True
                            if text_underline_width:
                                return True
            if hasattr(doc, 'styles') and doc.styles:
                for named_style in doc.styles.childNodes:
                    if named_style.getAttribute('name') == style_name:
                        for property in named_style.childNodes:
                            text_underline_style = property.getAttribute('textunderlinestyle')
                            text_underline_type = property.getAttribute('textunderlinetype')
                            text_underline_width = property.getAttribute('textunderlinewidth')
                            if text_underline_style and text_underline_style != 'none':
                                return True
                            if text_underline_type and text_underline_type != 'none':
                                return True
                            if text_underline_width:
                                return True
            return False
        for para in doc.getElementsByType(P):
            para_text = teletype.extractText(para)
            spans = para.getElementsByType(Span)
            for span in spans:
                text = teletype.extractText(span)
                if target_word.lower() in text.lower():
                    style_name = span.getAttribute('stylename')
                    is_underlined = check_underline_in_style(style_name)
                    word_instances.append({'text': text, 'is_underlined': is_underlined})
            if target_word.lower() in para_text.lower():
                found_in_span = any((target_word.lower() in teletype.extractText(span).lower() for span in spans))
                if not found_in_span:
                    para_style_name = para.getAttribute('stylename')
                    is_underlined = check_underline_in_style(para_style_name)
                    word_instances.append({'text': para_text.strip(), 'is_underlined': is_underlined})
        all_underlined = len(word_instances) > 0 and all((inst['is_underlined'] for inst in word_instances))
        return {'instances': word_instances, 'all_underlined': all_underlined, 'count': len(word_instances), 'underlined_count': sum((1 for inst in word_instances if inst['is_underlined']))}
    finally:
        os.unlink(tmp_path)

def get_docx_line_spacing__989968b8(env, config: dict) -> Dict[str, Any]:
    """Get line spacing, font size, and content of the document.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'dest' keys

    Returns:
        Dict with 'line_spacing', 'font_size', 'content', and 'content_length' keys
    """
    import os
    from docx import Document
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'line_spacing': None, 'font_size': None, 'content': '', 'content_length': 0}
    temp_path = f"/tmp/{config['dest']}"
    with open(temp_path, 'wb') as f:
        f.write(file_bytes)
    try:
        doc = Document(temp_path)
        if len(doc.paragraphs) == 0:
            return {'line_spacing': None, 'font_size': None, 'content': '', 'content_length': 0}
        content = '\n'.join([para.text for para in doc.paragraphs])
        content_length = len(content.strip())
        line_spacings = []
        for para in doc.paragraphs:
            if para.paragraph_format.line_spacing is not None:
                line_spacings.append(para.paragraph_format.line_spacing)
        line_spacing = line_spacings[0] if line_spacings else None
        font_sizes = []
        for para in doc.paragraphs:
            for run in para.runs:
                if run.font.size:
                    font_sizes.append(run.font.size.pt)
        font_size = font_sizes[0] if font_sizes else None
        return {'line_spacing': line_spacing, 'font_size': font_size, 'content': content, 'content_length': content_length}
    finally:
        if os.path.exists(temp_path):
            os.remove(temp_path)

def get_docx_paragraph_bold__45d88ae6(env, config):
    """Check if a specific paragraph is bold.

    Args:
        env: DesktopEnv instance
        config: Config with 'path', 'dest', and 'para_idx'

    Returns:
        dict: {"para_idx": int, "is_bold": bool}
    """
    file_path = config.get('path', '')
    para_idx = config.get('para_idx', 0)
    file_bytes = env.controller.get_file(file_path)
    if file_bytes is None:
        return {'para_idx': para_idx, 'is_bold': False}
    doc = Document(io.BytesIO(file_bytes))
    if para_idx >= len(doc.paragraphs):
        return {'para_idx': para_idx, 'is_bold': False}
    para = doc.paragraphs[para_idx]
    if not para.runs:
        return {'para_idx': para_idx, 'is_bold': False}
    bold_runs = sum((1 for run in para.runs if run.bold))
    total_runs = len(para.runs)
    is_bold = bold_runs / total_runs >= 0.8
    return {'para_idx': para_idx, 'is_bold': is_bold}

def get_docx_last_para__7cf3d1b3(env, config: dict) -> Optional[str]:
    """Get the last paragraph text from a DOCX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path'

    Returns:
        Text of the last paragraph, or None if not found
    """
    file_path = config.get('path')
    if not file_path:
        return None
    try:
        doc = Document(file_path)
        if len(doc.paragraphs) > 0:
            for para in reversed(doc.paragraphs):
                if para.text.strip():
                    return para.text
            return None
        return None
    except Exception as e:
        return None

def get_docx_title_format__c9be3f87(env, config):
    """Get formatting properties of the document title (first non-empty paragraph).

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: Title formatting properties (bold, italic, font_size, alignment)
    """
    file_path = config.get('path')
    if not file_path:
        logger.error('No file path provided in config')
        return {}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        logger.error(f'Failed to get file from VM: {file_path}')
        return {}
    import tempfile
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        title_para = None
        for para in doc.paragraphs:
            if para.text.strip():
                title_para = para
                break
        if not title_para:
            logger.error('No non-empty paragraph found')
            return {}
        if not title_para.runs:
            logger.warning('No runs in title paragraph')
            return {'alignment': str(title_para.alignment)}
        first_run = title_para.runs[0]
        result = {'text': title_para.text.strip(), 'bold': first_run.bold or False, 'italic': first_run.italic or False, 'font_size': first_run.font.size.pt if first_run.font.size else None, 'alignment': str(title_para.alignment)}
        logger.info(f'Title format: {result}')
        return result
    except Exception as e:
        logger.error(f'Error reading document: {e}')
        return {}
    finally:
        import os
        os.unlink(tmp_path)

