def get_vim_autoindent_check__97dca5c9ec1ede83fef195245d742c77(env, config: dict):
    """
    Check if .vimrc file contains an active (non-commented) 'set autoindent' configuration.

    Args:
        env: DesktopEnv instance
        config: Configuration dict

    Returns:
        String output from the check script
    """
    script = '\nif [ -f ~/.vimrc ]; then\n    if grep -E "^[[:space:]]*set[[:space:]]+autoindent" ~/.vimrc > /dev/null 2>&1; then\n        echo "The File Has Set Autoindent!"\n    else\n        echo "The File Does Not Have Set Autoindent!"\n    fi\nelse\n    echo "The .vimrc File Does Not Exist!"\nfi\n'
    result = env.controller.run_bash_script(script, timeout=10)
    output = result.get('output', '').strip()
    logger.info(f'Vim autoindent check result: {output}')
    return output

