def get_docx_para_font_size__25696b96(env, config):
    """Check font size of a specific paragraph.

    Args:
        env: DesktopEnv instance
        config: Config with 'path', 'dest', and 'para_idx'

    Returns:
        dict: {"para_idx": int, "font_size": float}
    """
    file_path = config.get('path', '')
    para_idx = config.get('para_idx', 0)
    file_bytes = env.controller.get_file(file_path)
    if file_bytes is None:
        return {'para_idx': para_idx, 'font_size': 0}
    doc = Document(io.BytesIO(file_bytes))
    if para_idx >= len(doc.paragraphs):
        return {'para_idx': para_idx, 'font_size': 0}
    para = doc.paragraphs[para_idx]
    if not para.runs:
        return {'para_idx': para_idx, 'font_size': 0}
    font_sizes = []
    for run in para.runs:
        if run.font.size:
            font_sizes.append(run.font.size.pt)
    if font_sizes:
        avg_size = sum(font_sizes) / len(font_sizes)
        return {'para_idx': para_idx, 'font_size': avg_size}
    return {'para_idx': para_idx, 'font_size': 0}

