def get_most_expensive_item__e5d6042fcfd6dbfad741bc78ecf0d884(env, config: dict) -> Optional[Tuple[str, float]]:
    """Find the most expensive item in the invoice.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Tuple of (item_name, price) or None if not found
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return None
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        max_price = 0
        max_item = None
        for row in ws.iter_rows(min_row=2, max_row=ws.max_row):
            item_name = row[0].value
            if item_name is None:
                continue
            if str(item_name).strip().lower() == 'total':
                break
            unit_price = row[2].value
            if unit_price is not None:
                price_float = float(unit_price)
                if price_float > max_price:
                    max_price = price_float
                    max_item = str(item_name)
        if max_item is None:
            return None
        return (max_item, max_price)
    finally:
        os.unlink(tmp_path)

