def get_docx_alignment__5bd1682ca1197bda0efb4e4e8c8337ce(env, config):
    """Extract alignment information for specific paragraphs.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: Mapping of paragraph indices to alignment values
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        alignments = {}
        content_idx = 0
        for (para_idx, para) in enumerate(doc.paragraphs):
            if para.text.strip():
                content_idx += 1
                alignment = para.alignment
                if alignment == WD_ALIGN_PARAGRAPH.CENTER:
                    alignments[content_idx] = 'center'
                elif alignment == WD_ALIGN_PARAGRAPH.RIGHT:
                    alignments[content_idx] = 'right'
                elif alignment == WD_ALIGN_PARAGRAPH.JUSTIFY:
                    alignments[content_idx] = 'justify'
                elif alignment == WD_ALIGN_PARAGRAPH.LEFT:
                    alignments[content_idx] = 'left'
                elif alignment is None:
                    alignments[content_idx] = 'left'
                else:
                    alignments[content_idx] = str(alignment)
        return alignments
    finally:
        os.unlink(tmp_path)

