def get_docx_para_alignment__a6405441(env, config: dict) -> Optional[str]:
    """Get the alignment of a paragraph.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'paragraph_index'

    Returns:
        Alignment as string ('left', 'center', 'right', 'justify'), or None
    """
    file_path = config.get('path')
    paragraph_index = config.get('paragraph_index', 0)
    if not file_path:
        return None
    try:
        doc = Document(file_path)
        if paragraph_index >= len(doc.paragraphs):
            return None
        para = doc.paragraphs[paragraph_index]
        alignment = para.alignment
        if alignment == WD_PARAGRAPH_ALIGNMENT.CENTER:
            return 'center'
        elif alignment == WD_PARAGRAPH_ALIGNMENT.RIGHT:
            return 'right'
        elif alignment == WD_PARAGRAPH_ALIGNMENT.JUSTIFY:
            return 'justify'
        else:
            return 'left'
    except Exception as e:
        return None

