def get_grf_filtered_years__da9c79d4(env, config: Dict[str, Any]) -> List[Dict[str, Any]]:
    """Extract years data from Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        List of dicts with year data: [{"Year": 2020, "#Applied": 179, ...}, ...]
    """
    file_path = config.get('path', '')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return []
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(mode='wb', delete=False, suffix='.xlsx') as f:
        f.write(file_bytes)
        temp_path = f.name
    try:
        wb = openpyxl.load_workbook(temp_path, data_only=True)
        ws = wb.active
        data = []
        for row_idx in range(2, ws.max_row + 1):
            year_cell = ws.cell(row=row_idx, column=1)
            applied_cell = ws.cell(row=row_idx, column=2)
            supported_cell = ws.cell(row=row_idx, column=3)
            rate_cell = ws.cell(row=row_idx, column=4)
            if year_cell.value is None:
                break
            data.append({'Year': int(year_cell.value) if year_cell.value else 0, '#Applied': int(applied_cell.value) if applied_cell.value else 0, '#Supported': int(supported_cell.value) if supported_cell.value else 0, 'Success Rate': float(rate_cell.value) if rate_cell.value else 0.0})
        wb.close()
        return data
    finally:
        if os.path.exists(temp_path):
            os.unlink(temp_path)

def get_snake_growth_test__d11f63aa7d5a1892ea3712caeaf33ff6(env, config: dict):
    """Test snake grows properly when grow() is called.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with parameters
            - path: List of file paths on VM
            - dest: List of destination filenames
            - multi: Boolean indicating multiple files

    Returns:
        dict: Test result with 'passed' boolean
    """
    paths = config.get('path', [])
    dests = config.get('dest', [])
    if not paths or not dests:
        return {'passed': False, 'error': 'Missing file paths'}
    with tempfile.TemporaryDirectory() as tmpdir:
        for (vm_path, dest) in zip(paths, dests):
            file_bytes = env.controller.get_file(vm_path)
            if not file_bytes:
                return {'passed': False, 'error': f'Failed to get {vm_path}'}
            temp_path = os.path.join(tmpdir, dest)
            with open(temp_path, 'wb') as f:
                f.write(file_bytes)
        sys.path.insert(0, tmpdir)
        try:
            import pygame
            pygame.init()
            from snake import Snake
            snake = Snake()
            initial_length = len(snake.positions)
            for i in range(5):
                snake.grow()
                expected_length = initial_length + i + 1
                current_length = len(snake.positions)
                if current_length != expected_length:
                    return {'passed': False, 'error': f'After {i + 1} grow() calls, expected length {expected_length} but got {current_length}', 'expected': expected_length, 'actual': current_length}
            return {'passed': True, 'initial_length': initial_length, 'final_length': len(snake.positions)}
        except Exception as e:
            return {'passed': False, 'error': str(e)}
        finally:
            sys.path.remove(tmpdir)
            for module in ['food', 'snake', 'main', 'settings']:
                if module in sys.modules:
                    del sys.modules[module]

def get_docx_word_count__773aefc65353b4ce6548d62ffb35b09d(env, config):
    """Count references in the References section of a Word document.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: Reference count and word count information
    """
    file_path = config.get('path', '')
    if not file_path:
        return {'reference_count': 0, 'word_count': 0}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'reference_count': 0, 'word_count': 0}
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        total_words = 0
        for para in doc.paragraphs:
            text = para.text.strip()
            if text:
                words = text.split()
                total_words += len(words)
        reference_count = 0
        in_references = False
        for (i, para) in enumerate(doc.paragraphs):
            text = para.text.strip()
            if re.match('^(References?|Bibliography|Works?\\s+Cited|Citations?)\\s*$', text, re.IGNORECASE):
                in_references = True
                continue
            if in_references and text and (para.style.name.startswith('Heading') or (len(text) < 100 and text.isupper())):
                break
            if in_references and text:
                if re.match('^(\\d+[\\.\\)]\\s*|\\[\\d+\\]\\s*)', text):
                    reference_count += 1
                elif re.match('^[A-Z][a-z]+,\\s+[A-Z]\\..*\\(\\d{4}\\)', text):
                    reference_count += 1
                elif re.match('^[A-Z][a-z]+', text) and re.search('\\(\\d{4}\\)', text):
                    reference_count += 1
        return {'reference_count': reference_count, 'word_count': total_words}
    finally:
        os.unlink(tmp_path)

