def get_transactions_and_net_change__0acc7400(env, config: dict):
    """Get transaction data and net change value from Excel file.

    Returns a dict with:
    - transaction_count: number of data rows in the spreadsheet
    - transaction_amounts: list of amounts found in the amount column
    - net_change: value from the net change cell (D19)
    """
    import openpyxl
    import io
    vm_path = config.get('path', '/home/user/Desktop/my_bookkeeping.xlsx')
    sheet_idx = config.get('sheet', 0)
    net_change_cell = config.get('net_change_cell', 'D19')
    file_bytes = env.controller.get_file(vm_path)
    if not file_bytes:
        return None
    wb = openpyxl.load_workbook(io.BytesIO(file_bytes), data_only=True)
    ws = wb.worksheets[sheet_idx] if isinstance(sheet_idx, int) else wb[sheet_idx]
    net_change = ws[net_change_cell].value
    transaction_amounts = []
    transaction_count = 0
    for row in range(2, 100):
        amount = None
        for col in ['C', 'D', 'E']:
            cell_val = ws[f'{col}{row}'].value
            if cell_val is not None and isinstance(cell_val, (int, float)):
                amount = abs(float(cell_val))
                break
        if amount is not None and amount > 0:
            transaction_amounts.append(amount)
            transaction_count += 1
    wb.close()
    return {'transaction_count': transaction_count, 'transaction_amounts': transaction_amounts, 'net_change': net_change}

