def get_user_details__565fa1c24eb22fa66726cab9f4123d31(env, config):
    """Get detailed user information including existence, home directory, group membership, and password validity.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'username' and 'password' keys

    Returns:
        dict: Dictionary with user details:
            - exists (bool): Whether user exists
            - home_dir (str|None): Home directory path
            - groups (list): List of groups user belongs to
            - has_sudo_access (bool): Whether user has sudo access
            - password_valid (bool): Whether the provided password is correct
    """
    username = config.get('username', '')
    password = config.get('password', '')
    import requests
    vm_ip = env.vm_ip
    port = env.server_port
    result = {'exists': False, 'home_dir': None, 'groups': [], 'has_sudo_access': False, 'password_valid': False}
    command = f'getent passwd {username}'
    response = requests.post(f'http://{vm_ip}:{port}/execute', json={'command': command, 'shell': True})
    if response.status_code == 200:
        output = response.json()['output'].strip()
        if output:
            result['exists'] = True
            fields = output.split(':')
            if len(fields) >= 6:
                result['home_dir'] = fields[5]
        else:
            logger.info(f'User {username} does not exist')
            return result
    else:
        logger.error('Failed to check user existence. Status code: %d', response.status_code)
        return result
    command = f"groups {username} 2>/dev/null | cut -d':' -f2 | xargs"
    response = requests.post(f'http://{vm_ip}:{port}/execute', json={'command': command, 'shell': True})
    if response.status_code == 200:
        output = response.json()['output'].strip()
        if output:
            result['groups'] = output.split()
    else:
        logger.error('Failed to get user groups. Status code: %d', response.status_code)
    result['has_sudo_access'] = 'sudo' in result['groups']
    if password:
        escaped_password = password.replace("'", "'\\''")
        command = f"echo '{escaped_password}' | su - {username} -c 'whoami' 2>/dev/null"
        response = requests.post(f'http://{vm_ip}:{port}/execute', json={'command': command, 'shell': True})
        if response.status_code == 200:
            output = response.json()['output'].strip()
            if output == username:
                result['password_valid'] = True
                logger.info(f'Password verification succeeded for user {username}')
            else:
                logger.info(f'Password verification failed for user {username} - output: {output}')
        else:
            logger.error('Failed to verify password. Status code: %d', response.status_code)
    logger.info(f'User details for {username}: {result}')
    return result

