def get_docx_para_bold_font__0f7f9b1491c7b565930c6c34711d694d(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract bold status and font name from a specific paragraph in a .docx file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM file path) and 'para_index' (0-based paragraph index)

    Returns:
        Dict with keys:
        - 'all_bold': bool - whether all runs in the paragraph are bold
        - 'font_name': str - the font name if all runs use the same font, or None if fonts are inconsistent or paragraph is empty
        - 'error': str - error message if any
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'all_bold': False, 'font_name': None, 'error': 'File not found'}
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        para_index = config.get('para_index', 0)
        if para_index >= len(doc.paragraphs):
            return {'all_bold': False, 'font_name': None, 'error': f'Paragraph index {para_index} out of range'}
        para = doc.paragraphs[para_index]
        runs = [r for r in para.runs if r.text.strip()]
        if not runs:
            return {'all_bold': False, 'font_name': None, 'error': 'No text runs in paragraph'}
        all_bold = all((r.bold for r in runs))
        font_name = runs[0].font.name if runs else None
        all_same_font = all((r.font.name == font_name for r in runs))
        if not all_same_font:
            unique_fonts = list(set((r.font.name for r in runs if r.font.name)))
            font_name = None
        return {'all_bold': all_bold, 'font_name': font_name, 'error': None}
    except Exception as e:
        return {'all_bold': False, 'font_name': None, 'error': str(e)}
    finally:
        os.unlink(tmp_path)

def get_sales_column_max_highlighted__678003f6(env, config: dict):
    """Get information about Sales column values and which cells have background highlighting.

    This function extracts all numeric values from the Sales column (column F),
    finds the maximum value, and checks which cells have background colors.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the Excel file

    Returns:
        dict: {
            'sales_values': {cell_coordinate: numeric_value},
            'max_value': float,
            'max_cell': str,
            'highlighted_cells': [list of cell coordinates with background color],
            'max_cell_has_color': bool
        }
    """
    file_path = config.get('path', '/home/user/Name_Order_Id_move_column.xlsx')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'sales_values': {}, 'max_value': None, 'max_cell': None, 'highlighted_cells': [], 'max_cell_has_color': False}
    wb = openpyxl.load_workbook(BytesIO(file_bytes), data_only=True)
    sheet = wb.active
    sales_values = {}
    max_value = None
    max_cell = None
    for row in range(2, sheet.max_row + 1):
        cell = sheet[f'F{row}']
        if cell.value is not None:
            try:
                numeric_value = float(cell.value)
                sales_values[f'F{row}'] = numeric_value
                if max_value is None or numeric_value > max_value:
                    max_value = numeric_value
                    max_cell = f'F{row}'
            except (ValueError, TypeError):
                pass
    highlighted_cells = []
    for row in range(2, sheet.max_row + 1):
        cell = sheet[f'F{row}']
        if cell.fill and cell.fill.start_color:
            color_index = cell.fill.start_color.index
            if color_index is None:
                continue
            if color_index not in ['00000000', 'FFFFFFFF', 'FFFFFF', '00FFFFFF']:
                highlighted_cells.append(f'F{row}')
    max_cell_has_color = max_cell in highlighted_cells if max_cell else False
    return {'sales_values': sales_values, 'max_value': max_value, 'max_cell': max_cell, 'highlighted_cells': highlighted_cells, 'max_cell_has_color': max_cell_has_color}

