def get_docx_para_count__b29db31b(env, config):
    """Count non-empty paragraphs in docx.

    Args:
        env: DesktopEnv instance
        config: Configuration dict

    Returns:
        int: Number of non-empty paragraphs
    """
    import os
    from docx import Document
    path = config['path']
    dest = config.get('dest', os.path.basename(path))
    cache_path = os.path.join(env.cache_dir, dest)
    file_bytes = env.controller.get_file(path)
    if not file_bytes:
        return 0
    with open(cache_path, 'wb') as f:
        f.write(file_bytes)
    doc = Document(cache_path)
    para_count = sum((1 for p in doc.paragraphs if p.text.strip()))
    return para_count

