def get_docx_para_format__ebc7426b(env, config: Dict[str, Any]) -> dict:
    """Get formatting information for a specific paragraph.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'paragraph_index'

    Returns:
        dict: Formatting info including bold, italic, font_size
    """
    file_path = config.get('path', '')
    paragraph_index = config.get('paragraph_index', 0)
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    import tempfile
    with tempfile.NamedTemporaryFile(delete=False, suffix='.docx') as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        if 0 <= paragraph_index < len(doc.paragraphs):
            para = doc.paragraphs[paragraph_index]
            has_bold = any((run.bold for run in para.runs if run.bold))
            has_italic = any((run.italic for run in para.runs if run.italic))
            font_sizes = [run.font.size.pt for run in para.runs if run.font.size]
            avg_font_size = sum(font_sizes) / len(font_sizes) if font_sizes else None
            return {'bold': has_bold, 'italic': has_italic, 'font_size': avg_font_size, 'text': para.text.strip()}
        return {}
    finally:
        import os
        os.unlink(tmp_path)

