def get_docx_font_color_first_para__1df7be4ccd1b1ba68ca616ee1ecc65bd(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract font color information from the first paragraph of a DOCX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the DOCX file

    Returns:
        Dict with 'has_color' boolean and 'color' tuple (r, g, b) or None
    """
    file_path = config.get('path', '')
    if not file_path:
        logger.error('No file path provided in config')
        return {'has_color': False, 'color': None}
    try:
        file_bytes = env.controller.get_file(file_path)
        if not file_bytes:
            logger.error(f'Failed to retrieve file: {file_path}')
            return {'has_color': False, 'color': None}
        with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        try:
            doc = Document(tmp_path)
            first_para = None
            for para in doc.paragraphs:
                if para.text.strip():
                    first_para = para
                    break
            if not first_para or not first_para.runs:
                logger.warning('No non-empty paragraph with runs found')
                return {'has_color': False, 'color': None}
            colors = []
            for run in first_para.runs:
                if run.text.strip() and run.font.color and run.font.color.rgb:
                    rgb = run.font.color.rgb
                    colors.append((rgb[0], rgb[1], rgb[2]))
            if not colors:
                logger.info('No colored text found in first paragraph')
                return {'has_color': False, 'color': None}
            if len(set(colors)) == 1:
                color = colors[0]
            else:
                color = max(set(colors), key=colors.count)
            logger.info(f'First paragraph color: RGB{color}')
            return {'has_color': True, 'color': color}
        finally:
            os.unlink(tmp_path)
    except Exception as e:
        logger.error(f'Error processing DOCX file: {e}')
        return {'has_color': False, 'color': None}

def get_docx_para_italic_status__3b03efdc409765dfc8747c41555b4710(env, config: Dict[str, Any]) -> List[bool]:
    """Get italic status for specified paragraphs.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'num_paragraphs' keys

    Returns:
        List[bool]: List of boolean values indicating italic status for each paragraph
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return []
    num_paragraphs = config.get('num_paragraphs', 5)
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        italic_status = []
        for i in range(min(num_paragraphs, len(doc.paragraphs))):
            para = doc.paragraphs[i]
            if not para.text.strip():
                italic_status.append(False)
                continue
            if len(para.runs) == 0:
                italic_status.append(False)
                continue
            all_italic = all((run.italic for run in para.runs if run.text.strip()))
            italic_status.append(all_italic)
        return italic_status
    except Exception as e:
        print(f'Error reading docx: {e}')
        return []
    finally:
        os.unlink(tmp_path)

