def get_writer_first_para_alignment__5eb444f7b3fe448e4ecbe3f1f3e38211(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract alignment information from the first paragraph of a DOCX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the DOCX file

    Returns:
        Dict with alignment information
    """
    try:
        file_bytes = env.controller.get_file(config['path'])
        if not file_bytes:
            logger.error(f"Failed to get file: {config['path']}")
            return {'alignment': None}
        with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        try:
            doc = Document(tmp_path)
            first_para = None
            for para in doc.paragraphs:
                if para.text.strip():
                    first_para = para
                    break
            if first_para is None:
                logger.warning('No non-empty paragraphs found')
                return {'alignment': None}
            alignment = first_para.paragraph_format.alignment
            alignment_str = None
            if alignment == WD_PARAGRAPH_ALIGNMENT.CENTER:
                alignment_str = 'center'
            elif alignment == WD_PARAGRAPH_ALIGNMENT.LEFT:
                alignment_str = 'left'
            elif alignment == WD_PARAGRAPH_ALIGNMENT.RIGHT:
                alignment_str = 'right'
            elif alignment == WD_PARAGRAPH_ALIGNMENT.JUSTIFY:
                alignment_str = 'justify'
            return {'alignment': alignment_str, 'text': first_para.text[:50]}
        finally:
            os.unlink(tmp_path)
    except Exception as e:
        logger.error(f'Error extracting alignment: {e}')
        return {'alignment': None}

