def get_docx_underline_check__1cf7c4d1(env, config: dict):
    """Check if document contains underlined text.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'dest' parameters

    Returns:
        dict: Contains has_underline and underline_count
    """
    try:
        file_bytes = env.controller.get_file(config['path'])
        if not file_bytes:
            return None
        import os
        cache_path = os.path.join(env.cache_dir, config['dest'])
        os.makedirs(os.path.dirname(cache_path), exist_ok=True)
        with open(cache_path, 'wb') as f:
            f.write(file_bytes)
        doc = Document(cache_path)
        underline_count = 0
        for para in doc.paragraphs:
            for run in para.runs:
                if run.underline and run.text.strip():
                    underline_count += 1
        result = {'has_underline': underline_count > 0, 'underline_count': underline_count}
        logger.info(f'Underline check: {result}')
        return result
    except Exception as e:
        logger.error(f'Error checking underline: {e}')
        return None

