def get_docx_last_line__d3067cd7(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Get comprehensive content information from a DOCX file.
    Extracts all paragraphs and returns structured data for validation.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: Contains 'all_text', 'paragraphs', 'paragraph_count', 'first_line', 'last_line'
    """
    from docx import Document
    from io import BytesIO
    path = config['path']
    file_bytes = env.controller.get_file(path)
    if not file_bytes:
        logger.error(f'Could not retrieve file: {path}')
        return {'all_text': '', 'paragraphs': [], 'paragraph_count': 0, 'first_line': '', 'last_line': ''}
    try:
        doc = Document(BytesIO(file_bytes))
        non_empty = [p.text.strip() for p in doc.paragraphs if p.text.strip()]
        all_text = '\n'.join(non_empty)
        result = {'all_text': all_text, 'paragraphs': non_empty, 'paragraph_count': len(non_empty), 'first_line': non_empty[0] if non_empty else '', 'last_line': non_empty[-1] if non_empty else ''}
        logger.info(f'Extracted {len(non_empty)} paragraphs from DOCX')
        logger.info(f"First line: {result['first_line'][:100]}")
        logger.info(f"Last line: {result['last_line'][:100]}")
        return result
    except Exception as e:
        logger.error(f'Error reading DOCX file: {e}')
        return {'all_text': '', 'paragraphs': [], 'paragraph_count': 0, 'first_line': '', 'last_line': ''}

