def get_section_headings_bold__b56847aa6ab8f1235134caeb96ab1293(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract section headings and check if they are bold.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict with 'total_sections' and 'bold_sections' keys
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'total_sections': 0, 'bold_sections': 0}
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        section_headings = []
        for para in doc.paragraphs:
            text = para.text.strip()
            if not text:
                continue
            if para.style.name.startswith('Heading'):
                section_headings.append(para)
        total_sections = len(section_headings)
        bold_sections = 0
        for heading in section_headings:
            if heading.runs:
                text_runs = [run for run in heading.runs if run.text.strip()]
                if text_runs:
                    if all((run.bold is not False for run in text_runs)):
                        bold_sections += 1
        result = {'total_sections': total_sections, 'bold_sections': bold_sections}
        return result
    finally:
        os.unlink(tmp_path)

