def get_docx_time_range__748cbe71(env, config):
    """Count records within a specific time range.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'start_hour', 'end_hour' keys

    Returns:
        int: Count of records in time range
    """
    file_path = config.get('path')
    start_hour = config.get('start_hour', 0)
    end_hour = config.get('end_hour', 24)
    if not file_path:
        logger.error('No file path provided in config')
        return 0
    try:
        file_bytes = env.controller.get_file(file_path)
        if not file_bytes:
            logger.error(f'Could not retrieve file from VM: {file_path}')
            return 0
        import tempfile
        with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        doc = Document(tmp_path)
        count = 0
        for para in doc.paragraphs:
            text = para.text.strip()
            if text:
                parts = text.split(',')
                if len(parts) >= 1:
                    time_str = parts[0].strip()
                    if ':' not in time_str:
                        continue
                    try:
                        time_parts = time_str.split(':')
                        if len(time_parts) < 2:
                            continue
                        hour = int(time_parts[0])
                        if start_hour <= hour < end_hour:
                            count += 1
                    except (ValueError, IndexError):
                        logger.warning(f'Skipping malformed time string: {time_str}')
                        continue
        import os
        os.unlink(tmp_path)
        return count
    except Exception as e:
        logger.error(f'Error counting time range: {e}')
        return 0

