def get_docx_paragraph_count__e89d7f00(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Get comprehensive content statistics from a DOCX file including paragraph count,
    word count, character count, and text content for verification.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: Dictionary containing:
            - paragraph_count: Number of non-empty paragraphs
            - word_count: Total word count
            - char_count: Total character count (excluding whitespace)
            - full_text: Complete text content (lowercased for comparison)
    """
    from docx import Document
    path = config['path']
    file_bytes = env.controller.get_file(path)
    if not file_bytes:
        logger.error(f'Could not retrieve file: {path}')
        return {'paragraph_count': 0, 'word_count': 0, 'char_count': 0, 'full_text': ''}
    try:
        from io import BytesIO
        doc = Document(BytesIO(file_bytes))
        paragraphs = [p.text.strip() for p in doc.paragraphs if p.text.strip()]
        paragraph_count = len(paragraphs)
        full_text = ' '.join(paragraphs)
        full_text_lower = full_text.lower()
        word_count = len(full_text.split())
        char_count = len(full_text.replace(' ', ''))
        logger.info(f'DOCX stats - Paragraphs: {paragraph_count}, Words: {word_count}, Chars: {char_count}')
        return {'paragraph_count': paragraph_count, 'word_count': word_count, 'char_count': char_count, 'full_text': full_text_lower}
    except Exception as e:
        logger.error(f'Error reading DOCX file: {e}')
        return {'paragraph_count': 0, 'word_count': 0, 'char_count': 0, 'full_text': ''}

def get_docx_paragraph_alignment__d12918f2(env, config):
    """Check paragraph alignment.

    Args:
        env: DesktopEnv instance
        config: Config with 'path', 'dest', and 'para_idx'

    Returns:
        dict: {"para_idx": int, "alignment": str}
    """
    file_path = config.get('path', '')
    para_idx = config.get('para_idx', 0)
    file_bytes = env.controller.get_file(file_path)
    if file_bytes is None:
        return {'para_idx': para_idx, 'alignment': 'left'}
    doc = Document(io.BytesIO(file_bytes))
    if para_idx >= len(doc.paragraphs):
        return {'para_idx': para_idx, 'alignment': 'left'}
    para = doc.paragraphs[para_idx]
    alignment_map = {WD_ALIGN_PARAGRAPH.LEFT: 'left', WD_ALIGN_PARAGRAPH.CENTER: 'center', WD_ALIGN_PARAGRAPH.RIGHT: 'right', WD_ALIGN_PARAGRAPH.JUSTIFY: 'justify', None: 'left'}
    alignment_str = alignment_map.get(para.alignment, 'left')
    return {'para_idx': para_idx, 'alignment': alignment_str}

