def get_default_text_editor__2fa36c5bda9265f2408df6cb5be11ed6(env, config: dict):
    """Gets the default application for text file types on Linux.

    Args:
        env: DesktopEnv instance
        config: Configuration dict

    Returns:
        str: The most common default text editor application name
    """
    from desktop_env.evaluators.getters.general import get_vm_command_line
    os_type = env.vm_platform
    if os_type == 'Linux':
        extensions = ['plain', 'x-c', 'x-c++', 'x-python', 'x-shellscript', 'x-java', 'x-makefile', 'xml', 'html', 'css', 'javascript', 'x-sh']
        apps = []
        for ext in extensions:
            app = get_vm_command_line(env, {'command': ['xdg-mime', 'query', 'default', f'text/{ext}']})
            if app:
                apps.append(app)
        if len(apps) == 0:
            return 'unknown'
        else:
            return Counter(apps).most_common(1)[0][0]
    elif os_type == 'Darwin':
        raise Exception('Unsupported operating system', os_type)
    elif os_type == 'Windows':
        raise Exception('Unsupported operating system', os_type)
    else:
        raise Exception('Unsupported operating system', os_type)

