def get_multi_step_verification__de59967047914828e21a9fc9ad62546c(env, config):
    """Perform multi-step verification for all task requirements.

    Args:
        env: DesktopEnv instance
        config: Configuration dict

    Returns:
        dict: {
            'csv_exists': bool,
            'python_code_exists': bool,
            'python_has_logic': bool,
            'result_value': float or None
        }
    """
    result = {'csv_exists': False, 'python_code_exists': False, 'python_has_logic': False, 'result_value': None}
