def get_docx_para_italic__a2e97584(env, config: dict) -> Optional[bool]:
    """Check if a paragraph's text is italicized.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'paragraph_index'

    Returns:
        True if all runs in paragraph are italic, False otherwise
    """
    file_path = config.get('path')
    paragraph_index = config.get('paragraph_index', 0)
    if not file_path:
        return None
    try:
        doc = Document(file_path)
        if paragraph_index >= len(doc.paragraphs):
            return None
        para = doc.paragraphs[paragraph_index]
        if not para.runs:
            return False
        has_text = False
        for run in para.runs:
            if run.text.strip():
                has_text = True
                if not run.italic:
                    return False
        return has_text
    except Exception as e:
        return None

def get_docx_alignment__e884bd7a(env, config: dict):
    """Extract which paragraphs are center-aligned.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key for VM file path

    Returns:
        List of paragraph indices that are center-aligned
    """
    vm_path = config.get('path')
    if not vm_path:
        return []
    try:
        file_data = env.controller.get_file(vm_path)
        if file_data is None:
            return []
        cache_path = os.path.join(env.cache_dir, os.path.basename(vm_path))
        os.makedirs(env.cache_dir, exist_ok=True)
        with open(cache_path, 'wb') as f:
            f.write(file_data)
        doc = Document(cache_path)
        centered_paragraphs = []
        for (i, para) in enumerate(doc.paragraphs):
            if not para.text.strip():
                continue
            if para.alignment == WD_PARAGRAPH_ALIGNMENT.CENTER:
                centered_paragraphs.append(i)
        return centered_paragraphs
    except Exception:
        return []

