def get_original_sizes__1eaa327b(env, config):
    """Get original font sizes from the cache PPTX file."""
    original_path = '/home/user/Desktop/38_1.pptx'
    from desktop_env.evaluators.getters.file import get_vm_file
    local_path = get_vm_file(env, {'path': original_path, 'dest': '38_1_original.pptx'})
    prs = Presentation(local_path)
    sizes = {}
    size_checks = config.get('size_increase_checks', [])
    for (idx, check) in enumerate(size_checks):
        slide_idx = check['slide_idx']
        shape_idx = check['shape_idx']
        group_shape_idx = check.get('group_shape_idx', None)
        if slide_idx >= len(prs.slides):
            continue
        slide = prs.slides[slide_idx]
        if shape_idx >= len(slide.shapes):
            continue
        shape = slide.shapes[shape_idx]
        if group_shape_idx is not None:
            if hasattr(shape, 'shapes') and group_shape_idx < len(shape.shapes):
                shape = shape.shapes[group_shape_idx]
            else:
                continue
        if hasattr(shape, 'text_frame') and shape.text_frame.paragraphs:
            para = shape.text_frame.paragraphs[0]
            if para.runs:
                run = para.runs[0]
                sizes[idx] = run.font.size
    return sizes

