def get_backup_doc_count__0193d6ff(env, config):
    """Count .doc files in backup directory.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'directory' parameter

    Returns:
        int: Count of .doc files in backup directory
    """
    directory = config.get('directory', '/home/user/Desktop/backup')
    command = f"ls -1 {directory}/*.doc 2>/dev/null | grep -v '\\.docx$' | wc -l"
    result = env.controller.run_bash_script(command, timeout=10)
    output = result.get('output', '0')
    try:
        return int(output.strip())
    except ValueError:
        return 0

def get_docx_text_lowercase__9415df6b82b4620e3e7305c55b67f50e(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract text from document and check if all text is lowercase.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the docx file on VM

    Returns:
        Dict with 'all_lowercase' boolean and 'sample_text' for debugging
    """
    file_path = config.get('path', '')
    if not file_path:
        return {'all_lowercase': False, 'sample_text': '', 'error': 'No path provided'}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'all_lowercase': False, 'sample_text': '', 'error': 'Failed to get file'}
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        all_text_parts = []
        for para in doc.paragraphs:
            text = para.text.strip()
            if text:
                all_text_parts.append(text)
        combined_text = ' '.join(all_text_parts)
        alphabetic_chars = [c for c in combined_text if c.isalpha()]
        if not alphabetic_chars:
            return {'all_lowercase': True, 'sample_text': combined_text[:200]}
        all_lowercase = all((c.islower() for c in alphabetic_chars))
        return {'all_lowercase': all_lowercase, 'sample_text': combined_text[:200]}
    finally:
        os.unlink(tmp_path)

def get_ext_manifest__6cc108f05c91be7e91c5c6203cef4c24(env, config: Dict[str, str]):
    """Get extension manifest information by path.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict with manifest info including version
    """
    os_type = env.vm_platform
    if os_type == 'Windows':
        preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('LOCALAPPDATA'),\n                                            'Google\\Chrome\\User Data\\Default\\Preferences'))")['output'].strip()
    elif os_type == 'Darwin':
        preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), 'Library/Application Support/Google/Chrome/Default/Preferences'))")['output'].strip()
    elif os_type == 'Linux':
        if 'arm' in platform.machine():
            preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), 'snap/chromium/common/chromium/Default/Preferences'))")['output'].strip()
        else:
            preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), '.config/google-chrome/Default/Preferences'))")['output'].strip()
    else:
        raise Exception('Unsupported operating system')
    try:
        content = env.controller.get_file(preference_file_path)
        data = json.loads(content)
        all_extensions = data.get('extensions', {}).get('settings', {})
        target_path = config.get('path', '')
        for ext_id in all_extensions.keys():
            ext_info = all_extensions[ext_id]
            if ext_info.get('path', '') == target_path:
                manifest = ext_info.get('manifest', {})
                return {'path': ext_info.get('path', ''), 'manifest_version': manifest.get('manifest_version', 0), 'name': manifest.get('name', ''), 'version': manifest.get('version', '')}
        return {'path': '', 'manifest_version': 0, 'name': '', 'version': ''}
    except Exception as e:
        logger.error(f'Error reading Chrome Preferences file: {e}')
        return {'path': '', 'manifest_version': 0, 'name': '', 'version': ''}

