def get_principles_list__537740a4(env, config):
    """Extract list of principles from a docx file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        list: List of principles found in the document
    """
    path = config.get('path', '/home/user/Desktop/principles.docx')
    file_bytes = env.controller.get_file(path)
    if not file_bytes:
        return []
    import os
    cache_path = os.path.join(env.cache_dir, 'principles.docx')
    with open(cache_path, 'wb') as f:
        f.write(file_bytes)
    try:
        doc = Document(cache_path)
        principles = []
        for p in doc.paragraphs:
            text = p.text.strip()
            if text and text not in ['Principles', 'ChatGPT Principles']:
                principles.append(text)
        return principles
    except Exception as e:
        return []

def get_docx_page_break_count__7a37573a929500afdc2d26b15140a2d7(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Check if a page break exists after the paragraph 'Navigating to Your Schedule'.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict with:
            - has_page_break_after_target: bool indicating if page break exists after target paragraph
            - target_paragraph_found: bool indicating if target paragraph was found
            - target_paragraph_index: int index of target paragraph (-1 if not found)
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'has_page_break_after_target': False, 'target_paragraph_found': False, 'target_paragraph_index': -1}
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        target_text = 'Navigating to Your Schedule'
        target_paragraph_index = -1
        for (idx, para) in enumerate(doc.paragraphs):
            if target_text in para.text:
                target_paragraph_index = idx
                break
        if target_paragraph_index == -1:
            return {'has_page_break_after_target': False, 'target_paragraph_found': False, 'target_paragraph_index': -1}
        has_page_break = False
        target_para = doc.paragraphs[target_paragraph_index]
        for run in target_para.runs:
            for br in run._element.findall(qn('w:br')):
                br_type = br.get(qn('w:type'))
                if br_type == 'page':
                    has_page_break = True
                    break
            if has_page_break:
                break
        if not has_page_break and target_paragraph_index + 1 < len(doc.paragraphs):
            next_para = doc.paragraphs[target_paragraph_index + 1]
            if len(next_para.runs) > 0:
                first_run = next_para.runs[0]
                for br in first_run._element.findall(qn('w:br')):
                    br_type = br.get(qn('w:type'))
                    if br_type == 'page':
                        has_page_break = True
                        break
        return {'has_page_break_after_target': has_page_break, 'target_paragraph_found': True, 'target_paragraph_index': target_paragraph_index}
    except Exception as e:
        print(f'Error reading docx: {e}')
        return {'has_page_break_after_target': False, 'target_paragraph_found': False, 'target_paragraph_index': -1}
    finally:
        os.unlink(tmp_path)

def get_docx_abstract_count__067c2a2a(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Get information about abstract entries in a docx file, including count and quality metrics.

    Args:
        env: Environment object
        config: Configuration dict with 'path' key pointing to the docx file

    Returns:
        dict: {
            'count': int - Number of valid abstract entries,
            'entries': list - List of abstract entry details,
            'valid_count': int - Number of entries with valid content and format
        }
    """
    path = config['path']
    file_path = get_vm_file(env, {'path': path, 'dest': os.path.basename(path)})
    if not file_path:
        logger.error(f'Failed to get file from VM: {path}')
        return {'count': 0, 'entries': [], 'valid_count': 0}
    try:
        doc = Document(file_path)
    except Exception as e:
        logger.error(f'Error loading docx file {file_path}: {e}')
        return {'count': 0, 'entries': [], 'valid_count': 0}
    paragraphs = [p.text.strip() for p in doc.paragraphs if p.text.strip()]
    abstract_entries = []
    i = 0
    while i < len(paragraphs):
        text = paragraphs[i]
        if text.startswith('Abstract:'):
            abstract_content = text[len('Abstract:'):].strip()
            paper_title = ''
            authors = ''
            date_info = ''
            for j in range(max(0, i - 3), i):
                prev_text = paragraphs[j]
                if any((month in prev_text.lower() for month in ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december'])):
                    date_info = prev_text
                elif not paper_title and len(prev_text) > 10 and (not prev_text.startswith('Abstract:')):
                    paper_title = prev_text
            has_content = len(abstract_content) >= 50
            has_metadata = bool(paper_title)
            entry = {'line_num': i, 'abstract_content': abstract_content, 'content_length': len(abstract_content), 'has_meaningful_content': has_content, 'paper_title': paper_title, 'has_metadata': has_metadata, 'date_info': date_info, 'is_valid': has_content and has_metadata}
            abstract_entries.append(entry)
        i += 1
    abstract_count = len(abstract_entries)
    valid_count = sum((1 for entry in abstract_entries if entry['is_valid']))
    logger.info(f'Found {abstract_count} abstracts ({valid_count} valid) in {file_path}')
    return {'count': abstract_count, 'entries': abstract_entries, 'valid_count': valid_count}

def get_odt_first_para_format__052ec137(env, config):
    """Get formatting information of the first paragraph.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' parameter

    Returns:
        dict: Formatting information including text, bold status, and case
    """
    vm_path = config.get('path', '/home/user/Desktop/sample-recruitment-phone-script.odt')
    file_bytes = env.controller.get_file(vm_path)
    if not file_bytes:
        return {}
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(delete=False, suffix='.odt') as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = load(tmp_path)
        all_paras = doc.getElementsByType(text.P)
        if not all_paras:
            return {}
        first_para = all_paras[0]
        para_text = teletype.extractText(first_para)
        result = {'text': para_text.strip(), 'is_bold': False, 'is_uppercase': para_text.strip().isupper()}
        for span in first_para.getElementsByType(text.Span):
            style_name = span.getAttribute('stylename')
            if style_name:
                for auto_style in doc.automaticstyles.getElementsByType(style.Style):
                    if auto_style.getAttribute('name') == style_name:
                        text_props = auto_style.getElementsByType(style.TextProperties)
                        for prop in text_props:
                            font_weight = prop.getAttribute('fontweight')
                            if font_weight == 'bold':
                                result['is_bold'] = True
                                break
        return result
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

