def get_font_size_info__ed1a97dae9ec3a584c26acbc45279859(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Extract font size information for paragraphs in the document.
    Checks ALL runs in each paragraph to ensure entire paragraphs have consistent font size.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the docx file

    Returns:
        Dict containing:
        - paragraph_font_sizes: list of font sizes for each paragraph (None if inconsistent or no size)
        - first_n_font_sizes: list of font sizes for first N paragraphs
    """
    file_path = config.get('path', '')
    if not file_path:
        return {'paragraph_font_sizes': [], 'first_n_font_sizes': []}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'paragraph_font_sizes': [], 'first_n_font_sizes': []}
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        para_sizes = []
        for para in doc.paragraphs:
            if para.text.strip() and para.runs:
                run_sizes = []
                for run in para.runs:
                    if run.text.strip():
                        if run.font.size:
                            run_sizes.append(run.font.size.pt)
                        else:
                            run_sizes.append(None)
                if not run_sizes:
                    para_sizes.append(None)
                else:
                    unique_sizes = set(run_sizes)
                    if len(unique_sizes) == 1:
                        para_sizes.append(run_sizes[0])
                    else:
                        para_sizes.append(None)
        return {'paragraph_font_sizes': para_sizes, 'first_n_font_sizes': para_sizes[:10] if para_sizes else []}
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

