def get_rtf_exists__7ea2a7f9(env, config: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """
    Check if an RTF file exists on the VM and verify it contains valid RTF content.

    Args:
        env: Environment object with controller to access VM
        config: Configuration dict with 'path' key pointing to RTF file on VM

    Returns:
        dict: {
            'exists': bool indicating if file exists,
            'is_valid_rtf': bool indicating if content is valid RTF,
            'is_non_empty': bool indicating if file has content
        }
        Returns None if there's an error accessing the file
    """
    rtf_path_on_vm = config['path']
    try:
        file_content = env.controller.get_file(rtf_path_on_vm)
        if file_content is None:
            return {'exists': False, 'is_valid_rtf': False, 'is_non_empty': False}
        is_non_empty = len(file_content) > 0
        is_valid_rtf = False
        if is_non_empty:
            content_str = file_content.decode('utf-8', errors='ignore') if isinstance(file_content, bytes) else file_content
            content_str = content_str.strip()
            is_valid_rtf = content_str.startswith('{\\rtf')
        return {'exists': True, 'is_valid_rtf': is_valid_rtf, 'is_non_empty': is_non_empty}
    except Exception as e:
        return None

def get_docx_paragraph_count__60c33ff2(env, config):
    """Get paragraph information from a docx file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: Dictionary with paragraph_count, total_words, and avg_words_per_paragraph
    """
    file_path = config.get('path')
    if not file_path:
        return {'paragraph_count': 0, 'total_words': 0, 'avg_words_per_paragraph': 0}
    try:
        file_bytes = env.controller.get_file(file_path)
        if not file_bytes:
            return {'paragraph_count': 0, 'total_words': 0, 'avg_words_per_paragraph': 0}
        import tempfile
        import os
        with tempfile.NamedTemporaryFile(delete=False, suffix='.docx') as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        try:
            doc = Document(tmp_path)
            para_count = 0
            total_words = 0
            for paragraph in doc.paragraphs:
                text = paragraph.text.strip()
                if text:
                    para_count += 1
                    words = len(text.split())
                    total_words += words
            avg_words = total_words / para_count if para_count > 0 else 0
            return {'paragraph_count': para_count, 'total_words': total_words, 'avg_words_per_paragraph': avg_words}
        finally:
            os.unlink(tmp_path)
    except Exception as e:
        print(f'Error counting paragraphs: {e}')
        return {'paragraph_count': 0, 'total_words': 0, 'avg_words_per_paragraph': 0}

def get_docx_text_color__53673b0f(env, config: dict):
    """Extract text colors of paragraphs.

    Args:
        env: DesktopEnv instance
        config: Configuration dict

    Returns:
        Dict mapping paragraph index to RGB color dict
    """
    file_path = config.get('path') if isinstance(config, dict) else None
    if not file_path:
        return {}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    try:
        from io import BytesIO
        doc = Document(BytesIO(file_bytes))
        paragraph_colors = {}
        for (i, para) in enumerate(doc.paragraphs):
            if not para.text.strip():
                continue
            for run in para.runs:
                if run.text.strip() and run.font.color and run.font.color.rgb:
                    rgb = run.font.color.rgb
                    paragraph_colors[i] = {'r': rgb[0], 'g': rgb[1], 'b': rgb[2]}
                    break
        return paragraph_colors
    except Exception:
        return {}

def get_docx_structure__a53ef9d4(env, config: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Extract document structure information from a docx file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict with paragraph_count, word_count, has_content, and text_content keys, or None if error
    """
    file_path = config.get('path')
    if not file_path:
        return None
    try:
        file_bytes = env.controller.get_file(file_path)
        if not file_bytes:
            return None
        import tempfile
        with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        doc = Document(tmp_path)
        non_empty_paragraphs = [p for p in doc.paragraphs if p.text.strip()]
        full_text = ' '.join((p.text for p in non_empty_paragraphs)).lower()
        structure = {'paragraph_count': len(non_empty_paragraphs), 'word_count': sum((len(p.text.split()) for p in non_empty_paragraphs)), 'has_content': len(non_empty_paragraphs) > 0, 'text_content': full_text}
        import os
        os.unlink(tmp_path)
        return structure
    except Exception as e:
        return None

def get_odt_exists__303cb7aa1b1ed14335a6a678e0ebd7d0(env, config: Dict[str, Any]) -> Optional[str]:
    """Check if an ODT file exists at the specified path and return the path if it exists.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the ODT file on VM

    Returns:
        str: The local cache path if file exists and is a valid ODT, None otherwise
    """
    vm_path = config.get('path')
    if not vm_path:
        logger.warning('No path specified in config')
        return None
    file_bytes = env.controller.get_file(vm_path)
    if not file_bytes:
        logger.warning(f'File not found at {vm_path}')
        return None
    cache_path = os.path.join(env.cache_dir, config.get('dest', 'output.odt'))
    os.makedirs(os.path.dirname(cache_path) if os.path.dirname(cache_path) else env.cache_dir, exist_ok=True)
    with open(cache_path, 'wb') as f:
        f.write(file_bytes)
    try:
        with zipfile.ZipFile(cache_path, 'r') as z:
            required_files = ['mimetype', 'content.xml']
            file_list = z.namelist()
            if not all((req in file_list for req in required_files)):
                logger.warning(f'File at {vm_path} is not a valid ODT (missing required files)')
                return None
            mimetype = z.read('mimetype').decode('utf-8').strip()
            if mimetype != 'application/vnd.oasis.opendocument.text':
                logger.warning(f'File at {vm_path} has incorrect mimetype: {mimetype}')
                return None
    except zipfile.BadZipFile:
        logger.warning(f'File at {vm_path} is not a valid ZIP/ODT file')
        return None
    except Exception as e:
        logger.warning(f'Error validating ODT file: {e}')
        return None
    logger.info(f'ODT file saved to {cache_path} ({len(file_bytes)} bytes)')
    return cache_path

