def get_bib_entry_count__0ebd8389(env, config: dict):
    """Extract detailed information about bibtex entries from a .bib file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' parameter

    Returns:
        dict: Contains 'entries' (list of entry dicts), 'count' (int),
              'has_blank_line_separation' (bool), and 'raw_content' (str)
    """
    import re
    path = config.get('path', '/home/user/Desktop/references.bib')
    file_content = env.controller.get_file(path)
    if not file_content:
        return {'count': 0, 'entries': [], 'has_blank_line_separation': False, 'raw_content': ''}
    content = file_content.decode('utf-8', errors='ignore')
    entry_pattern = '(@\\w+\\s*\\{[^@]*?\\n\\})'
    raw_entries = re.findall(entry_pattern, content, re.DOTALL)
    entries = []
    for raw_entry in raw_entries:
        key_match = re.search('@\\w+\\s*\\{\\s*([^,\\s]+)', raw_entry)
        citation_key = key_match.group(1) if key_match else ''
        title_match = re.search('title\\s*=\\s*["{]([^"}]+)["}]', raw_entry, re.IGNORECASE)
        title = title_match.group(1) if title_match else ''
        author_match = re.search('author\\s*=\\s*["{]([^"}]+)["}]', raw_entry, re.IGNORECASE)
        author = author_match.group(1) if author_match else ''
        has_dblp_url = bool(re.search('(url|biburl|bibsource)\\s*=\\s*["{][^"{}]*dblp[^"{}]*["}]', raw_entry, re.IGNORECASE))
        has_arxiv = bool(re.search('(arxiv|arXiv)', raw_entry))
        entries.append({'citation_key': citation_key, 'title': title, 'author': author, 'has_dblp_url': has_dblp_url, 'has_arxiv': has_arxiv, 'raw_entry': raw_entry})
    has_blank_line_separation = bool(re.search('\\}\\s*\\n\\s*\\n\\s*@', content))
    return {'count': len(entries), 'entries': entries, 'has_blank_line_separation': has_blank_line_separation, 'raw_content': content}

def get_docx_text_formatting__8051bbbf8bb6e492bd4dea258f9abe99(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Extract text content and formatting from a DOCX file.
    
    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key
        
    Returns:
        Dict containing paragraphs with text and formatting info
    """
    file_path = config.get('path', '')
    if not file_path:
        return {'paragraphs': []}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'paragraphs': []}
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        paragraphs_data = []
        for (para_idx, para) in enumerate(doc.paragraphs):
            para_text = para.text
            if not para_text.strip():
                paragraphs_data.append({'text': '', 'runs': []})
                continue
            runs_data = []
            for run in para.runs:
                run_info = {'text': run.text, 'bold': run.bold if run.bold is not None else False, 'italic': run.italic if run.italic is not None else False, 'underline': run.underline if run.underline is not None else False}
                if run.font.highlight_color is not None:
                    run_info['highlight'] = str(run.font.highlight_color)
                else:
                    run_info['highlight'] = None
                runs_data.append(run_info)
            paragraphs_data.append({'text': para_text, 'runs': runs_data})
        return {'paragraphs': paragraphs_data}
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

def get_ext_names__3898ddf1f9c99b582b59db314361e457(env, config: Dict[str, str]):
    """Get all installed extension names from Chrome preferences.

    Args:
        env: DesktopEnv instance
        config: Configuration dict

    Returns:
        List of extension names
    """
    os_type = env.vm_platform
    if os_type == 'Windows':
        preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('LOCALAPPDATA'),\n                                            'Google\\Chrome\\User Data\\Default\\Preferences'))")['output'].strip()
    elif os_type == 'Darwin':
        preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), 'Library/Application Support/Google/Chrome/Default/Preferences'))")['output'].strip()
    elif os_type == 'Linux':
        if 'arm' in platform.machine():
            preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), 'snap/chromium/common/chromium/Default/Preferences'))")['output'].strip()
        else:
            preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), '.config/google-chrome/Default/Preferences'))")['output'].strip()
    else:
        raise Exception('Unsupported operating system')
    try:
        content = env.controller.get_file(preference_file_path)
        data = json.loads(content)
        all_extensions_names = []
        all_extensions = data.get('extensions', {}).get('settings', {})
        for ext_id in all_extensions.keys():
            manifest = all_extensions[ext_id].get('manifest', {})
            name = manifest.get('name', '')
            if name:
                all_extensions_names.append(name)
        return all_extensions_names
    except Exception as e:
        logger.error(f'Error reading Chrome Preferences file: {e}')
        return []

def get_word_formatting__c28febf33450404ef9b2d9584375d57a(env, config: Dict[str, Any]) -> Dict[str, List[bool]]:
    """
    Extract formatting (italic status) for specific words.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key and 'target_word' to check

    Returns:
        Dict mapping target word to list of italic status for each occurrence
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    target_word = config.get('target_word', 'BLCUP')
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        word_italics = []
        for para in doc.paragraphs:
            for run in para.runs:
                if target_word in run.text:
                    is_italic = run.font.italic is True
                    count = run.text.count(target_word)
                    word_italics.extend([is_italic] * count)
        return {target_word: word_italics}
    finally:
        os.unlink(tmp_path)

def get_process_running__2cd7e46e(env, config: Dict[str, Any]) -> bool:
    """Check if a process is running.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'process_name' key

    Returns:
        bool: True if process is running, False otherwise
    """
    process_name = config.get('process_name', '')
    result = env.controller.run_bash_script(f'pgrep -f "{process_name}" > /dev/null && echo "running" || echo "not_running"', timeout=10)
    if result.get('status') == 'success' and 'running' in result.get('output', ''):
        return True
    return False

