    script = '\nif [ -f ~/.vimrc ]; then\n    if grep -q "syntax on" ~/.vimrc; then\n        echo "The File Has Set Syntax On!"\n    else\n        echo "The File Does Not Have Set Syntax On!"\n    fi\nelse\n    echo "The .vimrc File Does Not Exist!"\nfi\n'
