    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'paragraphs': []}
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        paragraphs_data = []
        for (para_idx, para) in enumerate(doc.paragraphs):
            para_text = para.text
            if not para_text.strip():
                paragraphs_data.append({'text': '', 'runs': []})
                continue
            runs_data = []
            for run in para.runs:
                run_info = {'text': run.text, 'bold': run.bold if run.bold is not None else False, 'italic': run.italic if run.italic is not None else False, 'underline': run.underline if run.underline is not None else False}
                if run.font.highlight_color is not None:
                    run_info['highlight'] = str(run.font.highlight_color)
                else:
                    run_info['highlight'] = None
                runs_data.append(run_info)
            paragraphs_data.append({'text': para_text, 'runs': runs_data})
        return {'paragraphs': paragraphs_data}
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

