def get_docx_exclude_platform__156bbecf8094c096edc4b32f7b6fd25b(env, config: Dict[str, Any]) -> List[str]:
    """
    Extract all train records from a docx file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the VM file

    Returns:
        List of train record lines (each line is a string)
    """
    file_path = config.get('path')
    if not file_path:
        logger.error('No file path provided in config')
        return []
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        logger.error(f'Failed to get file from VM: {file_path}')
        return []
    try:
        with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        doc = Document(tmp_path)
        records = []
        for para in doc.paragraphs:
            line = para.text.strip()
            if line and ',' in line:
                parts = line.split(',')
                if len(parts) == 4:
                    records.append(line)
        return records
    except Exception as e:
        logger.error(f'Error reading docx file: {e}')
        return []
    finally:
        if 'tmp_path' in locals():
            try:
                os.unlink(tmp_path)
            except Exception:
                pass

