def get_odt_word_color__5a87841c3b225c3a02d238e24f612f46(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract text color for specific words in ODT file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'target_word'

    Returns:
        Dict with word instances and their color
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'instances': [], 'all_match_color': False}
    with tempfile.NamedTemporaryFile(suffix='.odt', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = load(tmp_path)
        target_word = config.get('target_word', '')
        expected_color = config.get('expected_color', '#ff0000').lower()
        word_instances = []
        for para in doc.getElementsByType(P):
            for span in para.getElementsByType(Span):
                text = teletype.extractText(span)
                if target_word.lower() in text.lower():
                    style_name = span.getAttribute('stylename')
                    text_color = None
                    if style_name:
                        for automatic_style in doc.automaticstyles.childNodes:
                            if automatic_style.getAttribute('name') == style_name:
                                for property in automatic_style.childNodes:
                                    color = property.getAttribute('color')
                                    if color:
                                        text_color = color.lower()
                                        break
                    word_instances.append({'text': text, 'color': text_color, 'matches': text_color == expected_color if text_color else False})
        all_match = len(word_instances) > 0 and all((inst['matches'] for inst in word_instances))
        return {'instances': word_instances, 'all_match_color': all_match, 'count': len(word_instances)}
    finally:
        os.unlink(tmp_path)

def get_bibtex_entry_count__158776f670e179a0f46e13d333164963(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract BibTeX entries and verify against referenced papers in references.docx.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key (VM file path for .bib file)

    Returns:
        Dict with:
            - 'count': Number of BibTeX entries found
            - 'entries': List of BibTeX entry data (title, authors, type)
            - 'referenced_papers': List of paper titles from references.docx
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'count': 0, 'entries': [], 'referenced_papers': []}
    try:
        content = file_bytes.decode('utf-8')
    except:
        return {'count': 0, 'entries': [], 'referenced_papers': []}
    entries = []
    entry_pattern = '@(\\w+)\\s*\\{([^}]+)\\}'
    for match in re.finditer('@(\\w+)\\s*\\{([^,]+),([^}]*)\\}', content, re.DOTALL):
        entry_type = match.group(1)
        entry_key = match.group(2).strip()
        entry_fields = match.group(3)
        title_match = re.search('title\\s*=\\s*[{"]\\s*([^"}]+)\\s*["}]', entry_fields, re.IGNORECASE)
        title = title_match.group(1).strip() if title_match else ''
        author_match = re.search('author\\s*=\\s*[{"]\\s*([^"}]+)\\s*["}]', entry_fields, re.IGNORECASE)
        authors = author_match.group(1).strip() if author_match else ''
        entries.append({'type': entry_type, 'key': entry_key, 'title': title.lower(), 'authors': authors.lower()})
    docx_path = config.get('docx_path', '/home/user/Desktop/references.docx')
    referenced_papers = []
    docx_bytes = env.controller.get_file(docx_path)
    if docx_bytes:
        try:
            import docx
            tmp_file = tempfile.NamedTemporaryFile(suffix='.docx', delete=False)
            try:
                tmp_file.write(docx_bytes)
                tmp_file.close()
                doc = docx.Document(tmp_file.name)
                full_text = '\n'.join([para.text for para in doc.paragraphs])
                known_papers = ['spider', 'sparc', 'cosql', 'attention is all you need', 'bert', 'gpt-3', 'language models are few-shot learners']
                for paper in known_papers:
                    if paper in full_text.lower():
                        referenced_papers.append(paper)
            finally:
                os.unlink(tmp_file.name)
        except ImportError:
            referenced_papers = ['spider', 'sparc', 'cosql', 'attention is all you need', 'bert', 'language models are few-shot learners']
        except:
            referenced_papers = ['spider', 'sparc', 'cosql', 'attention is all you need', 'bert', 'language models are few-shot learners']
    else:
        referenced_papers = ['spider', 'sparc', 'cosql', 'attention is all you need', 'bert', 'language models are few-shot learners']
    return {'count': len(entries), 'entries': entries, 'referenced_papers': referenced_papers}

