def get_bib_authors__7d0fecc9(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Extract author information from BibTeX entries.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict[str, Any]: Dictionary containing:
            - 'authors': List of unique author names
            - 'has_truncation': Boolean indicating if 'et al.' found
            - 'entry_count': Number of BibTeX entries
    """
    file_path = config.get('path', '/home/user/Desktop/references.bib')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'authors': [], 'has_truncation': False, 'entry_count': 0}
    content = file_bytes.decode('utf-8', errors='ignore')
    has_truncation = bool(re.search('et\\s+al\\.?', content, re.IGNORECASE))
    entry_count = len(re.findall('@\\w+\\s*\\{', content))
    author_pattern = 'author\\s*=\\s*\\{([^}]+)\\}'
    author_blocks = re.findall(author_pattern, content, re.IGNORECASE | re.DOTALL)
    all_authors = []
    for block in author_blocks:
        authors_in_block = block.split(' and ')
        for author in authors_in_block:
            clean_author = ' '.join(author.split())
            if clean_author:
                all_authors.append(clean_author.strip())
    return {'authors': list(set(all_authors)), 'has_truncation': has_truncation, 'entry_count': entry_count}

def get_safe_browsing_enabled__3160f23c(env, config: Dict[str, str]):
    """Check if Safe Browsing is enabled in Chrome settings."""
    os_type = env.vm_platform
    if os_type == 'Windows':
        preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('LOCALAPPDATA'),\n                                            'Google\\Chrome\\User Data\\Default\\Preferences'))")['output'].strip()
    elif os_type == 'Darwin':
        preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), 'Library/Application Support/Google/Chrome/Default/Preferences'))")['output'].strip()
    elif os_type == 'Linux':
        if 'arm' in platform.machine():
            preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), 'snap/chromium/common/chromium/Default/Preferences'))")['output'].strip()
        else:
            preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), '.config/google-chrome/Default/Preferences'))")['output'].strip()
    else:
        raise Exception('Unsupported operating system')
    try:
        content = env.controller.get_file(preference_file_path)
        data = json.loads(content)
        safebrowsing = data.get('safebrowsing', {})
        is_enabled = bool(safebrowsing.get('enabled', False))
        is_enhanced = bool(safebrowsing.get('enhanced', False))
        return 'true' if is_enabled or is_enhanced else 'false'
    except Exception as e:
        logger.error(f'Error: {e}')
        return 'false'

