def get_tetris_rotate_ast__ee2759accd5923c49a3a2cfba9a8ccf8(env, config: dict) -> Dict[str, Any]:
    """Extract AST information from the rotate method in tetris.py.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to tetris.py

    Returns:
        Dict containing AST analysis of the rotate method:
        - has_collision_check: bool - whether intersect() is called after rotation
        - has_state_restore: bool - whether old state is saved and restored
        - method_body: list - list of statement types in the method
        - valid_syntax: bool - whether the file has valid Python syntax
    """
    file_path = config.get('path', '/home/user/Desktop/tetris/tetris.py')
    try:
        file_bytes = env.controller.get_file(file_path)
        if not file_bytes:
            return {'has_collision_check': False, 'has_state_restore': False, 'method_body': [], 'valid_syntax': False, 'error': 'File not found or empty'}
        code = file_bytes.decode('utf-8')
        try:
            tree = ast.parse(code)
        except SyntaxError as e:
            return {'has_collision_check': False, 'has_state_restore': False, 'method_body': [], 'valid_syntax': False, 'error': f'Syntax error: {str(e)}'}
        rotate_method = None
        for node in ast.walk(tree):
            if isinstance(node, ast.ClassDef) and node.name == 'Tetris':
                for item in node.body:
                    if isinstance(item, ast.FunctionDef) and item.name == 'rotate':
                        rotate_method = item
                        break
        if not rotate_method:
            return {'has_collision_check': False, 'has_state_restore': False, 'method_body': [], 'valid_syntax': True, 'error': 'rotate method not found in Tetris class'}
        has_collision_check = False
        has_state_restore = False
        method_body = []
        has_old_rotation = False
        for stmt in rotate_method.body:
            stmt_type = type(stmt).__name__
            method_body.append(stmt_type)
            for node in ast.walk(stmt):
                if isinstance(node, ast.Call):
                    if isinstance(node.func, ast.Attribute):
                        if isinstance(node.func.value, ast.Name) and node.func.value.id == 'self' and (node.func.attr == 'intersect'):
                            has_collision_check = True
            if isinstance(stmt, ast.Assign):
                for target in stmt.targets:
                    if isinstance(target, ast.Name):
                        if target.id in ('old_rotation', 'prev_rotation', 'saved_rotation'):
                            has_old_rotation = True
            if isinstance(stmt, ast.Assign):
                if isinstance(stmt.value, ast.Name):
                    if stmt.value.id in ('old_rotation', 'prev_rotation', 'saved_rotation') and any((isinstance(t, ast.Attribute) and t.attr == 'rotation' for t in stmt.targets)):
                        has_state_restore = True
        has_state_restore = has_old_rotation and has_state_restore
        return {'has_collision_check': has_collision_check, 'has_state_restore': has_state_restore, 'method_body': method_body, 'valid_syntax': True, 'error': None}
    except Exception as e:
        return {'has_collision_check': False, 'has_state_restore': False, 'method_body': [], 'valid_syntax': False, 'error': f'Unexpected error: {str(e)}'}

def get_docx_paragraph_bold__b2783ee01453e505cdb722c94db4f891(env, config):
    """Extract bold formatting status from paragraphs in a docx file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key specifying VM file path

    Returns:
        Dict mapping paragraph index to boolean indicating if all text is bold
    """
    file_path = config.get('path')
    if not file_path:
        return {}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    try:
        with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        doc = Document(tmp_path)
        paragraph_bold_status = {}
        for (idx, para) in enumerate(doc.paragraphs):
            if not para.runs or not para.text.strip():
                paragraph_bold_status[idx] = None
                continue
            has_text = False
            all_bold = True
            for run in para.runs:
                if run.text.strip():
                    has_text = True
                    if not run.bold:
                        all_bold = False
                        break
            if has_text:
                paragraph_bold_status[idx] = all_bold
            else:
                paragraph_bold_status[idx] = None
        return paragraph_bold_status
    except Exception as e:
        print(f'Error reading docx file: {e}')
        return {}
    finally:
        if 'tmp_path' in locals():
            try:
                os.unlink(tmp_path)
            except:
                pass

