    font_sizes = []
    for run in title_para.runs:
        if run.font.size is not None:
            font_sizes.append(run.font.size)
    if not font_sizes:
        return {'size': None}
    first_size = font_sizes[0]
    if all((size == first_size for size in font_sizes)):
        return {'size': first_size}
    return {'size': None}

