def get_docx_completeness__baf7d55e(env, config):
    """Check if all papers have complete 4-field structure.

    Args:
        env: DesktopEnv instance
        config: Configuration dict

    Returns:
        dict: Counts of each field type
    """
    import os
    from docx import Document
    path = config['path']
    dest = config.get('dest', os.path.basename(path))
    cache_path = os.path.join(env.cache_dir, dest)
    file_bytes = env.controller.get_file(path)
    if not file_bytes:
        return {'titles': 0, 'authors': 0, 'abstracts': 0, 'arxiv': 0}
    with open(cache_path, 'wb') as f:
        f.write(file_bytes)
    doc = Document(cache_path)
    paragraphs = [p.text.strip() for p in doc.paragraphs if p.text.strip()]
    return {'titles': sum((1 for p in paragraphs if p.startswith('Title:'))), 'authors': sum((1 for p in paragraphs if p.startswith('Authors:'))), 'abstracts': sum((1 for p in paragraphs if p.startswith('Abstract:'))), 'arxiv': sum((1 for p in paragraphs if p.startswith('Arxiv PDF:')))}

