def get_invoice_total__90311779cc768ba3848a75a5d93dc4d5(env, config: dict) -> Optional[Dict[str, Any]]:
    """Extract total amount from invoice Excel file and verify file existence.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict with 'file_exists' and 'total' keys, or None if file doesn't exist
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'file_exists': False, 'total': None}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        total_value = None
        for row in ws.iter_rows(min_row=1, max_row=ws.max_row):
            if row[0].value and str(row[0].value).strip().lower() == 'total':
                total_value = row[1].value
                if total_value is not None:
                    total_value = float(total_value)
                break
        return {'file_exists': True, 'total': total_value}
    finally:
        os.unlink(tmp_path)

