def get_docx_underlined_text__7ef1ac80(env, config):
    """Extract underlined text from a DOCX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM path) and 'dest' (local filename)

    Returns:
        list: List of underlined text strings
    """
    vm_path = config.get('path', '/home/user/Desktop/View_Person_Organizational_Summary.docx')
    dest = config.get('dest', 'temp.docx')
    file_bytes = env.controller.get_file(vm_path)
    if file_bytes is None:
        return []
    cache_path = os.path.join(env.cache_dir, dest)
    with open(cache_path, 'wb') as f:
        f.write(file_bytes)
    doc = Document(cache_path)
    underlined_texts = []
    for paragraph in doc.paragraphs:
        for run in paragraph.runs:
            if run.underline and run.text.strip():
                underlined_texts.append(run.text.strip())
    for table in doc.tables:
        for row in table.rows:
            for cell in row.cells:
                for paragraph in cell.paragraphs:
                    for run in paragraph.runs:
                        if run.underline and run.text.strip():
                            underlined_texts.append(run.text.strip())
    return underlined_texts

def get_recreation_page_title__f88125582538c20ef428c4af5979c4e3(env, config: Dict[str, Any]):
    """
    Get page title from recreation.gov to verify successful navigation.
    """
    logger.info(f'[RECREATION_TITLE] Starting recreation.gov title check')
    logger.debug(f'[RECREATION_TITLE] Config: {config}')
    host = env.vm_ip
    port = env.chromium_port
    server_port = env.server_port
    use_proxy = env.current_use_proxy
    remote_debugging_url = f'http://{host}:{port}'
    backend_url = f'http://{host}:{server_port}'
    max_retries = 2
    timeout_ms = 30000
    for attempt in range(max_retries):
        try:
            logger.info(f'[RECREATION_TITLE] Attempt {attempt + 1}/{max_retries}')
            with sync_playwright() as p:
                try:
                    browser = p.chromium.connect_over_cdp(remote_debugging_url)
                    logger.info(f'[RECREATION_TITLE] Connected to Chrome')
                except Exception as e:
                    logger.warning(f'[RECREATION_TITLE] Failed to connect: {e}')
                    app = 'chromium' if 'arm' in platform.machine() else 'google-chrome'
                    command = [app, '--remote-debugging-port=1337']
                    if use_proxy:
                        command.append(f'--proxy-server=127.0.0.1:18888')
                    payload = json.dumps({'command': command, 'shell': False})
                    headers = {'Content-Type': 'application/json'}
                    requests.post(backend_url + '/setup/launch', headers=headers, data=payload)
                    time.sleep(5)
                    browser = p.chromium.connect_over_cdp(remote_debugging_url)
                page = browser.contexts[0].pages[0] if browser.contexts[0].pages else browser.contexts[0].new_page()
                current_url = page.url
                logger.info(f'[RECREATION_TITLE] Current URL: {current_url}')
                page.wait_for_load_state('networkidle', timeout=timeout_ms)
                title = page.title()
                logger.info(f'[RECREATION_TITLE] Page title: {title}')
                return {'title': title, 'url': current_url}
        except Exception as e:
            logger.error(f'[RECREATION_TITLE] Attempt {attempt + 1} failed: {e}')
            if attempt == max_retries - 1:
                logger.error(f'[RECREATION_TITLE] All attempts failed')
                return {}
            time.sleep(2)
    return {}

