    if not file_bytes:
        return []
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(delete=False, suffix='.odt') as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = load(tmp_path)
        strikethrough_texts = []
        for span in doc.getElementsByType(text.Span):
            style_name = span.getAttribute('stylename')
            if style_name:
                for auto_style in doc.automaticstyles.getElementsByType(style.Style):
                    if auto_style.getAttribute('name') == style_name:
                        text_props = auto_style.getElementsByType(style.TextProperties)
                        for prop in text_props:
                            strike_style = prop.getAttribute('textlinethroughstyle')
                            if strike_style and strike_style != 'none':
                                span_text = teletype.extractText(span)
                                if span_text.strip():
                                    strikethrough_texts.append(span_text.strip())
        return strikethrough_texts
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

