def get_docx_spacing__9c612fede8141550419e9174fb604127(env, config):
    """Extract line spacing and font size information from a DOCX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: Dictionary with paragraph index as key and dict of spacing/font info as value
            Example: {0: {'line_spacing': 1.0, 'font_size': 12.0}, 1: {'line_spacing': 1.5, 'font_size': 12.0}}
    """
    import tempfile
    import os
    from docx import Document
    from docx.shared import Pt
    file_path = config.get('path', '')
    if not file_path:
        return {}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        paragraph_info = {}
        para_index = 0
        for para in doc.paragraphs:
            if para.text.strip():
                line_spacing = para.paragraph_format.line_spacing
                if line_spacing is None:
                    line_spacing_value = 1.0
                elif isinstance(line_spacing, (int, float)):
                    line_spacing_value = float(line_spacing)
                else:
                    try:
                        line_spacing_value = float(line_spacing)
                    except:
                        line_spacing_value = 1.0
                font_size = None
                if para.runs:
                    for run in para.runs:
                        if run.font.size is not None:
                            font_size = run.font.size.pt
                            break
                if font_size is None:
                    font_size = 12.0
                paragraph_info[para_index] = {'line_spacing': line_spacing_value, 'font_size': float(font_size)}
                para_index += 1
        return paragraph_info
    finally:
        os.unlink(tmp_path)

