def get_bib_venue_info__1829c383(env, config: dict):
    """Extract paper information including venue, title, authors, and year from bibtex.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' parameter

    Returns:
        dict: Dictionary with 'venues', 'titles', 'authors', and 'years' lists
    """
    import re
    path = config.get('path', '/home/user/Desktop/references.bib')
    file_content = env.controller.get_file(path)
    if not file_content:
        return {'venues': [], 'titles': [], 'authors': [], 'years': []}
    content = file_content.decode('utf-8', errors='ignore')
    result = {'venues': [], 'titles': [], 'authors': [], 'years': []}
    booktitles = re.findall('booktitle\\s*=\\s*\\{([^}]+)\\}', content, re.IGNORECASE | re.MULTILINE | re.DOTALL)
    result['venues'].extend([' '.join(bt.split()) for bt in booktitles])
    journals = re.findall('journal\\s*=\\s*\\{([^}]+)\\}', content, re.IGNORECASE | re.MULTILINE)
    result['venues'].extend([' '.join(j.split()) for j in journals])
    titles = re.findall('title\\s*=\\s*\\{([^}]+)\\}', content, re.IGNORECASE | re.MULTILINE | re.DOTALL)
    result['titles'].extend([' '.join(t.split()) for t in titles])
    authors = re.findall('author\\s*=\\s*\\{([^}]+)\\}', content, re.IGNORECASE | re.MULTILINE | re.DOTALL)
    result['authors'].extend([' '.join(a.split()) for a in authors])
    years = re.findall('year\\s*=\\s*\\{?(\\d{4})\\}?', content, re.IGNORECASE | re.MULTILINE)
    result['years'].extend(years)
    return result

def get_bibtex_fields__15eb2c700df4ed2a0e8732ed92c43b5f(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract BibTeX entries and check which required fields they contain.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key (VM file path)

    Returns:
        Dict with 'entry_count' and 'entries_with_required_fields' count
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'entry_count': 0, 'entries_with_required_fields': 0}
    try:
        content = file_bytes.decode('utf-8')
    except:
        return {'entry_count': 0, 'entries_with_required_fields': 0}
    entry_pattern = '@(\\w+)\\s*\\{\\s*([^,\\s]+)\\s*,'
    matches = re.finditer(entry_pattern, content)
    valid_entries = []
    for match in matches:
        entry_type = match.group(1).lower()
        citation_key = match.group(2)
        start_pos = match.start()
        brace_count = 1
        i = match.end()
        while i < len(content) and brace_count > 0:
            if content[i] == '{':
                brace_count += 1
            elif content[i] == '}':
                brace_count -= 1
            i += 1
        if brace_count == 0:
            entry_content = content[match.end():i - 1]
            if entry_type not in ['comment', 'preamble', 'string']:
                valid_entries.append({'type': entry_type, 'key': citation_key, 'content': entry_content})
    entry_count = len(valid_entries)
    valid_count = 0
    required_fields = ['author', 'title', 'year']
    for entry in valid_entries:
        has_all_fields = True
        for field in required_fields:
            pattern = f'{field}\\s*=\\s*[{{"]'
            if not re.search(pattern, entry['content'], re.IGNORECASE):
                has_all_fields = False
                break
        if has_all_fields:
            valid_count += 1
    return {'entry_count': entry_count, 'entries_with_required_fields': valid_count}

