def get_odt_underlined_words__a0593874(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Extract all underlined words from the document and count total occurrences of words.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict with:
        - 'underlined_words': list of underlined words
        - 'all_words': list of all words in document (for counting occurrences)
    """
    file_path = config.get('path')
    if not file_path:
        logger.error('No file path provided')
        return {'underlined_words': [], 'all_words': []}
    try:
        file_bytes = env.controller.get_file(file_path)
        if not file_bytes:
            logger.error(f'Could not read file: {file_path}')
            return {'underlined_words': [], 'all_words': []}
        import tempfile
        import os
        with tempfile.NamedTemporaryFile(suffix='.odt', delete=False) as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        try:
            with zipfile.ZipFile(tmp_path, 'r') as z:
                content_xml = z.read('content.xml').decode('utf-8')
            root = ET.fromstring(content_xml)
            namespaces = {'office': 'urn:oasis:names:tc:opendocument:xmlns:office:1.0', 'text': 'urn:oasis:names:tc:opendocument:xmlns:text:1.0', 'style': 'urn:oasis:names:tc:opendocument:xmlns:style:1.0', 'fo': 'urn:oasis:names:tc:opendocument:xmlns:xsl-fo-compatible:1.0'}
            underlined_words = []
            all_words = []
            body = root.find('.//office:body', namespaces)
            if body is None:
                return {'underlined_words': [], 'all_words': []}
            text_elem = body.find('.//office:text', namespaces)
            if text_elem is None:
                return {'underlined_words': [], 'all_words': []}
            auto_styles = root.find('.//office:automatic-styles', namespaces)
            if auto_styles is None:
                auto_styles = None
            all_paras = text_elem.findall('.//text:p', namespaces)
            for para in all_paras:
                para_text = ''.join(para.itertext())
                words_in_para = para_text.split()
                all_words.extend(words_in_para)
                spans = para.findall('.//text:span', namespaces)
                for span in spans:
                    span_style = span.get('{urn:oasis:names:tc:opendocument:xmlns:text:1.0}style-name')
                    if span_style and auto_styles is not None:
                        style_elem = auto_styles.find(f'.//style:style[@style:name="{span_style}"]', namespaces)
                        if style_elem is not None:
                            text_props = style_elem.find('.//style:text-properties', namespaces)
                            if text_props is not None:
                                underline = text_props.get('{urn:oasis:names:tc:opendocument:xmlns:style:1.0}text-underline-style')
                                if underline and underline != 'none':
                                    text_content = ''.join(span.itertext())
                                    words = text_content.split()
                                    underlined_words.extend(words)
            return {'underlined_words': underlined_words, 'all_words': all_words}
        finally:
            if os.path.exists(tmp_path):
                os.unlink(tmp_path)
    except Exception as e:
        logger.error(f'Error checking underlined words: {e}')
        return {'underlined_words': [], 'all_words': []}

def get_docx_para_bold_status__ef2b803b(env, config: dict) -> Optional[bool]:
    """Check if a paragraph's text is bold.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'paragraph_index'

    Returns:
        True if all runs in paragraph are bold, False otherwise
    """
    file_path = config.get('path')
    paragraph_index = config.get('paragraph_index', 0)
    if not file_path:
        return None
    try:
        doc = Document(file_path)
        if paragraph_index >= len(doc.paragraphs):
            return None
        para = doc.paragraphs[paragraph_index]
        if not para.runs:
            return False
        has_text = False
        for run in para.runs:
            if run.text.strip():
                has_text = True
                if not run.bold:
                    return False
        return has_text
    except Exception as e:
        return None

