def get_docx_paper_structure__aa99bafa(env, config: dict):
    """Extract paper structure including count and metadata fields from a docx file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with parameters:
            - path: VM path to the docx file

    Returns:
        dict: Contains:
            - paper_count: Number of papers detected in the document
            - papers_with_title: Number of papers with title field
            - papers_with_authors: Number of papers with authors field
            - papers_with_abstract: Number of papers with abstract field
            - papers_with_arxiv: Number of papers with arxiv link
            - papers_complete: Number of papers with all 4 required fields
    """
    try:
        vm_path = config.get('path', '/home/user/Desktop/paper_reading_2024_03_01.docx')
        file_bytes = env.controller.get_file(vm_path)
        if not file_bytes:
            logger.error(f'Failed to get file from VM: {vm_path}')
            return {'paper_count': 0, 'papers_with_title': 0, 'papers_with_authors': 0, 'papers_with_abstract': 0, 'papers_with_arxiv': 0, 'papers_complete': 0}
        import tempfile
        import os
        with tempfile.NamedTemporaryFile(delete=False, suffix='.docx') as tmp_file:
            tmp_file.write(file_bytes)
            tmp_path = tmp_file.name
        try:
            doc = Document(tmp_path)
            full_text = '\n'.join([para.text for para in doc.paragraphs])
            arxiv_pattern = 'arxiv\\.org/|arXiv:'
            arxiv_matches = re.findall(arxiv_pattern, full_text, re.IGNORECASE)
            arxiv_count = len(arxiv_matches)
            paper_title_pattern = '(?:^|\\n)(?:\\d+\\.|Paper\\s+\\d+|Title:)'
            title_matches = re.findall(paper_title_pattern, full_text, re.MULTILINE | re.IGNORECASE)
            paper_count = max(arxiv_count, len(title_matches))
            title_pattern = '(?:^|\\n)(?:Title|Paper\\s+\\d+):'
            authors_pattern = '(?:^|\\n)Authors?:'
            abstract_pattern = '(?:^|\\n)Abstract:'
            title_fields = len(re.findall(title_pattern, full_text, re.MULTILINE | re.IGNORECASE))
            authors_fields = len(re.findall(authors_pattern, full_text, re.MULTILINE | re.IGNORECASE))
            abstract_fields = len(re.findall(abstract_pattern, full_text, re.MULTILINE | re.IGNORECASE))
            arxiv_fields = arxiv_count
            papers_complete = min(title_fields, authors_fields, abstract_fields, arxiv_fields)
            result = {'paper_count': paper_count, 'papers_with_title': title_fields, 'papers_with_authors': authors_fields, 'papers_with_abstract': abstract_fields, 'papers_with_arxiv': arxiv_fields, 'papers_complete': papers_complete}
            logger.info(f'Paper structure analysis: {result}')
            return result
        finally:
            os.unlink(tmp_path)
    except Exception as e:
        logger.error(f'Error analyzing paper structure in docx: {e}')
        return {'paper_count': 0, 'papers_with_title': 0, 'papers_with_authors': 0, 'papers_with_abstract': 0, 'papers_with_arxiv': 0, 'papers_complete': 0}

def get_docx_para_font_size__37b8a61b36d3883db53cb178c084bb0a(env, config: Dict[str, Any]) -> Dict[int, float]:
    """Extract font sizes from specified paragraphs in a DOCX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - path: VM path to the .docx file
            - paragraph_indices: List of paragraph indices to check

    Returns:
        Dict mapping paragraph index to font size in points (or None if not set)
    """
    file_path = config.get('path')
    if not file_path:
        logger.error('No file path provided in config')
        return {}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        logger.error(f'Failed to get file from VM: {file_path}')
        return {}
    import tempfile
    import os
    try:
        with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        doc = Document(tmp_path)
        paragraph_indices = config.get('paragraph_indices', [])
        result = {}
        for idx in paragraph_indices:
            if idx < len(doc.paragraphs):
                para = doc.paragraphs[idx]
                if para.runs:
                    font_size = para.runs[0].font.size
                    if font_size:
                        result[idx] = font_size.pt
                    else:
                        result[idx] = None
                else:
                    result[idx] = None
            else:
                logger.warning(f'Paragraph index {idx} out of range')
                result[idx] = None
        return result
    except Exception as e:
        logger.error(f'Error processing DOCX file: {e}')
        return {}
    finally:
        if 'tmp_path' in locals() and os.path.exists(tmp_path):
            os.unlink(tmp_path)

def get_docx_highlighted_text__df95acabcc5627cbac9487746bf87230(env, config):
    """Extract yellow-highlighted section headings from a Word document.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: Information about yellow-highlighted section headings
    """
    file_path = config.get('path', '')
    if not file_path:
        return {'yellow_heading_count': 0, 'section_headings': []}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'yellow_heading_count': 0, 'section_headings': []}
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        yellow_highlighted_headings = []
        all_headings = []
        for para in doc.paragraphs:
            is_heading = False
            if para.style.name and 'Heading' in para.style.name:
                is_heading = True
            elif para.runs and any((run.bold for run in para.runs)):
                bold_text = ''.join((run.text for run in para.runs if run.bold))
                total_text = para.text
                if len(bold_text) > len(total_text) * 0.5 and len(total_text) < 100:
                    is_heading = True
            if is_heading and para.text.strip():
                all_headings.append(para.text.strip())
                has_yellow_highlight = False
                for run in para.runs:
                    if run.font.highlight_color == WD_COLOR_INDEX.YELLOW:
                        has_yellow_highlight = True
                        break
                if has_yellow_highlight:
                    yellow_highlighted_headings.append({'text': para.text.strip(), 'style': para.style.name})
        return {'yellow_heading_count': len(yellow_highlighted_headings), 'section_headings': yellow_highlighted_headings, 'total_headings': len(all_headings), 'all_headings': all_headings}
    finally:
        os.unlink(tmp_path)

def get_remaining_picture_hashes__a362cf87(env, config):
    """Get hashes of remaining pictures in Pictures directory."""
    pictures_dir = config.get('directory', '/home/user/Pictures')
    result = env.controller.run_bash_script(f"find {pictures_dir} -maxdepth 1 -type f \\( -iname '*.jpg' -o -iname '*.jpeg' -o -iname '*.png' \\)", timeout=10)
    if result['returncode'] != 0 or not result['output'].strip():
        return []
    files = result['output'].strip().split('\n')
    hashes = []
    for file_path in files:
        if not file_path or file_path.strip() == '':
            continue
        file_path = file_path.strip()
        file_bytes = env.controller.get_file(file_path)
        if file_bytes:
            try:
                with Image.open(BytesIO(file_bytes)) as img:
                    img_byte_arr = img.tobytes()
                    hash_result = hashlib.sha256(img_byte_arr).hexdigest()
                    hashes.append(hash_result)
            except Exception as e:
                print(f'Error processing {file_path}: {e}')
                continue
    return sorted(hashes)

def get_text_alignment__1857b08997e5057be0ed7e2fe747fd99(env, config):
    """Get the text alignment of a specific shape in a slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'slide_idx', and 'shape_idx' keys

    Returns:
        str: Alignment name (e.g., 'CENTER', 'LEFT', 'RIGHT') or 'NONE'
    """
    import tempfile
    import os
    from pptx import Presentation
    from pptx.enum.text import PP_ALIGN
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return 'NONE'
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide_idx = config.get('slide_idx', 0)
        shape_idx = config.get('shape_idx', 0)
        if slide_idx >= len(prs.slides):
            return 'NONE'
        slide = prs.slides[slide_idx]
        if shape_idx >= len(slide.shapes):
            return 'NONE'
        shape = slide.shapes[shape_idx]
        if not hasattr(shape, 'text_frame'):
            return 'NONE'
        if len(shape.text_frame.paragraphs) == 0:
            return 'NONE'
        para = shape.text_frame.paragraphs[0]
        alignment = para.alignment
        if alignment is None:
            return 'LEFT'
        elif alignment == PP_ALIGN.CENTER:
            return 'CENTER'
        elif alignment == PP_ALIGN.LEFT:
            return 'LEFT'
        elif alignment == PP_ALIGN.RIGHT:
            return 'RIGHT'
        elif alignment == PP_ALIGN.JUSTIFY:
            return 'JUSTIFY'
        else:
            return str(alignment)
    finally:
        os.unlink(tmp_path)

def get_docx_bold_paragraphs__d895ea7cc00dbacda337968d433a03d2(env, config: Dict[str, Any]) -> Any:
    """Extract which paragraphs have bold formatting.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key for file path on VM

    Returns:
        Dict with paragraph indices and whether they are fully bold
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        bold_info = {}
        for (idx, paragraph) in enumerate(doc.paragraphs):
            if not paragraph.text.strip():
                continue
            has_text = False
            all_bold = True
            for run in paragraph.runs:
                if run.text.strip():
                    has_text = True
                    if not run.font.bold:
                        all_bold = False
                        break
            if has_text:
                bold_info[idx] = all_bold
        return bold_info
    finally:
        os.unlink(tmp_path)

