def get_docx_para_count__647a34f44ae6bb0086ca88f5ee821f1a(env, config):
    """Extract document structure including paragraph count and section headings.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: Document structure information with paragraph count and headings
    """
    file_path = config.get('path', '')
    if not file_path:
        return {'count': 0, 'headings': [], 'sections': {}}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'count': 0, 'headings': [], 'sections': {}}
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        non_empty_count = sum((1 for p in doc.paragraphs if p.text.strip()))
        headings = []
        sections = {}
        section_pattern = re.compile('^([IVX]+)\\.\\s+(.+)', re.IGNORECASE)
        for para in doc.paragraphs:
            text = para.text.strip()
            if not text:
                continue
            match = section_pattern.match(text)
            if match:
                section_num = match.group(1).upper()
                section_title = match.group(2).strip()
                headings.append(text)
                sections[section_num] = section_title
            elif text.lower() in ['conclusion', 'conclusions']:
                headings.append(text)
                sections['V'] = text
        return {'count': non_empty_count, 'total': len(doc.paragraphs), 'headings': headings, 'sections': sections}
    finally:
        os.unlink(tmp_path)

