def get_docx_text_count__7dc05d2e(env, config):
    """Count occurrences of a specific text in a DOCX file.
    Extracts text from all document elements including paragraphs, tables,
    headers, footers, and counts both the search text and its replacement.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'search_text' keys

    Returns:
        dict: Contains 'european_count', 'eu_count', and 'was_saved' status
    """
    vm_path = config.get('path', '')
    search_text = config.get('search_text', '')
    docx_bytes = env.controller.get_file(vm_path)
    if not docx_bytes:
        return {'european_count': -1, 'eu_count': -1, 'was_saved': False}
    cache_path = os.path.join(env.cache_dir, 'temp_check.docx')
    with open(cache_path, 'wb') as f:
        f.write(docx_bytes)
    try:
        doc = Document(cache_path)
        all_text_parts = []
        for para in doc.paragraphs:
            all_text_parts.append(para.text)
        for table in doc.tables:
            for row in table.rows:
                for cell in row.cells:
                    all_text_parts.append(cell.text)
        for section in doc.sections:
            if section.header:
                for para in section.header.paragraphs:
                    all_text_parts.append(para.text)
                for table in section.header.tables:
                    for row in table.rows:
                        for cell in row.cells:
                            all_text_parts.append(cell.text)
            if section.footer:
                for para in section.footer.paragraphs:
                    all_text_parts.append(para.text)
                for table in section.footer.tables:
                    for row in table.rows:
                        for cell in row.cells:
                            all_text_parts.append(cell.text)
        total_text = ' '.join(all_text_parts)
        european_count = total_text.lower().count(search_text.lower())
        eu_count = total_text.lower().count('eu')
        was_saved = len(docx_bytes) > 0
        return {'european_count': european_count, 'eu_count': eu_count, 'was_saved': was_saved}
    except Exception as e:
        print(f'Error reading DOCX: {e}')
        return {'european_count': -1, 'eu_count': -1, 'was_saved': False}

def get_bib_multiple_papers__e34a4fae(env, config: dict):
    """Check if bibtex contains multiple specific papers with comprehensive validation.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'title_keywords' (list)

    Returns:
        dict: {
            'found': [list of found keywords],
            'count': int,
            'entries': [list of entry dicts with validation info],
            'has_blank_line_separation': bool,
            'all_from_dblp': bool,
            'all_published': bool
        }
    """
    import re
    path = config.get('path', '/home/user/Desktop/references.bib')
    title_keywords = config.get('title_keywords', [])
    file_content = env.controller.get_file(path)
    if not file_content:
        return {'found': [], 'count': 0, 'entries': [], 'has_blank_line_separation': False, 'all_from_dblp': False, 'all_published': True}
    content = file_content.decode('utf-8', errors='ignore')
    entry_pattern = '@\\w+\\s*\\{[^@]*'
    entries = re.findall(entry_pattern, content, re.MULTILINE | re.DOTALL)
    found_keywords = []
    entry_infos = []
    has_blank_separation = bool(re.search('\\n\\s*\\n\\s*@', content))
    all_from_dblp = True
    all_published = True
    for entry in entries:
        title_match = re.search('title\\s*=\\s*\\{([^}]+)\\}', entry, re.IGNORECASE | re.MULTILINE | re.DOTALL)
        if not title_match:
            continue
        title = title_match.group(1)
        has_dblp_marker = bool(re.search('biburl\\s*=\\s*\\{[^}]*dblp\\.org[^}]*\\}', entry, re.IGNORECASE)) or bool(re.search('bibsource\\s*=\\s*\\{[^}]*dblp[^}]*\\}', entry, re.IGNORECASE)) or bool(re.search('url\\s*=\\s*\\{[^}]*dblp\\.org[^}]*\\}', entry, re.IGNORECASE))
        has_arxiv = bool(re.search('journal\\s*=\\s*\\{[^}]*arxiv[^}]*\\}', entry, re.IGNORECASE)) or bool(re.search('booktitle\\s*=\\s*\\{[^}]*arxiv[^}]*\\}', entry, re.IGNORECASE)) or bool(re.search('venue\\s*=\\s*\\{[^}]*arxiv[^}]*\\}', entry, re.IGNORECASE)) or bool(re.search('url\\s*=\\s*\\{[^}]*arxiv\\.org[^}]*\\}', entry, re.IGNORECASE)) or bool(re.search('@article\\s*\\{[^,]*arxiv', entry, re.IGNORECASE))
        is_published = not has_arxiv
        has_author = bool(re.search('author\\s*=\\s*\\{', entry, re.IGNORECASE))
        has_year = bool(re.search('year\\s*=\\s*\\{', entry, re.IGNORECASE))
        entry_info = {'title': title, 'has_dblp_marker': has_dblp_marker, 'is_published': is_published, 'has_required_fields': has_author and has_year, 'matched_keyword': None}
        for keyword in title_keywords:
            if keyword.lower() == 'attention':
                if 'attention is all' in title.lower():
                    if keyword not in found_keywords:
                        found_keywords.append(keyword)
                        entry_info['matched_keyword'] = keyword
            elif keyword.lower() == 'bert':
                if re.search('\\bbert\\b', title.lower()):
                    if keyword not in found_keywords:
                        found_keywords.append(keyword)
                        entry_info['matched_keyword'] = keyword
            elif keyword.lower() in title.lower():
                if keyword not in found_keywords:
                    found_keywords.append(keyword)
                    entry_info['matched_keyword'] = keyword
        if entry_info['matched_keyword']:
            entry_infos.append(entry_info)
            if not has_dblp_marker:
                all_from_dblp = False
            if not is_published:
                all_published = False
    return {'found': found_keywords, 'count': len(found_keywords), 'entries': entry_infos, 'has_blank_line_separation': has_blank_separation, 'all_from_dblp': all_from_dblp, 'all_published': all_published}

def get_docx_font_size__b88bed88(env, config):
    """Extract font sizes of specific paragraphs.

    Args:
        env: DesktopEnv instance
        config: Either a string (file path) or dict with 'path' key

    Returns:
        Dict mapping paragraph index to dict with 'font_size' and 'text' keys
    """
    file_path = config if isinstance(config, str) else config.get('path')
    if not file_path:
        return {}
    try:
        with open(file_path, 'rb') as f:
            doc = Document(f)
        paragraph_sizes = {}
        for (i, para) in enumerate(doc.paragraphs):
            text = para.text.strip()
            if not text:
                paragraph_sizes[i] = {'font_size': None, 'text': ''}
                continue
            sizes = []
            for run in para.runs:
                if run.text.strip() and run.font.size:
                    sizes.append(run.font.size.pt)
            if sizes:
                font_size = max(set(sizes), key=sizes.count)
            else:
                font_size = None
            paragraph_sizes[i] = {'font_size': font_size, 'text': text}
        return paragraph_sizes
    except Exception:
        return {}

def get_ext_count__2cf92b2479d096498965f5b9ffc3704c(env, config: Dict[str, str]):
    """Get information about Chrome extensions matching specified criteria.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with optional keys:
            - 'name_pattern': regex pattern to match extension name
            - 'path_contains': string that must be in extension path

    Returns:
        dict: Dictionary with extension info including:
            - 'found': bool, whether a matching extension was found
            - 'path': str or None, the path to the extension if found
            - 'name': str or None, the name of the extension if found
            - 'enabled': bool or None, whether the extension is enabled
    """
    os_type = env.vm_platform
    if os_type == 'Windows':
        preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('LOCALAPPDATA'),\n                                            'Google\\Chrome\\User Data\\Default\\Preferences'))")['output'].strip()
    elif os_type == 'Darwin':
        preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), 'Library/Application Support/Google/Chrome/Default/Preferences'))")['output'].strip()
    elif os_type == 'Linux':
        if 'arm' in platform.machine():
            preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), 'snap/chromium/common/chromium/Default/Preferences'))")['output'].strip()
        else:
            preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), '.config/google-chrome/Default/Preferences'))")['output'].strip()
    else:
        raise Exception('Unsupported operating system')
    name_pattern = config.get('name_pattern', 'hello.*extension')
    path_contains = config.get('path_contains', 'Desktop/helloExtension')
    try:
        content = env.controller.get_file(preference_file_path)
        data = json.loads(content)
        all_extensions = data.get('extensions', {}).get('settings', {})
        for (ext_id, ext_data) in all_extensions.items():
            path = ext_data.get('path', '')
            manifest = ext_data.get('manifest', {})
            name = manifest.get('name', '')
            path_match = path_contains in path if path_contains else True
            name_match = False
            if name_pattern and name:
                try:
                    if re.search(name_pattern, name, re.IGNORECASE):
                        name_match = True
                except re.error:
                    if name_pattern.lower() in name.lower():
                        name_match = True
            if path_match and name_match:
                return {'found': True, 'path': path, 'name': name, 'enabled': ext_data.get('state', 0) == 1}
        return {'found': False, 'path': None, 'name': None, 'enabled': None}
    except Exception as e:
        logger.error(f'Error reading Chrome Preferences file: {e}')
        return {'found': False, 'path': None, 'name': None, 'enabled': None}

def get_odt_italic_text__2012319433f38531dcd28d87c90e4213(env, config: dict) -> Dict[str, Any]:
    """
    Extract all text instances and count specific word occurrences in italic vs total.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the ODT file

    Returns:
        Dict with total word count and italic word count for case-insensitive whole-word matching
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'total_text': '', 'italic_texts': []}
    with tempfile.NamedTemporaryFile(suffix='.odt', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        with zipfile.ZipFile(tmp_path, 'r') as z:
            content_xml = z.read('content.xml')
        root = ET.fromstring(content_xml)
        ns = {'text': 'urn:oasis:names:tc:opendocument:xmlns:text:1.0', 'style': 'urn:oasis:names:tc:opendocument:xmlns:style:1.0', 'office': 'urn:oasis:names:tc:opendocument:xmlns:office:1.0', 'fo': 'urn:oasis:names:tc:opendocument:xmlns:xsl-fo-compatible:1.0'}
        italic_style_names = set()
        auto_styles = root.find('.//office:automatic-styles', ns)
        if auto_styles:
            for style in auto_styles.findall('.//style:style', ns):
                text_props = style.find('.//style:text-properties', ns)
                if text_props is not None:
                    font_style = text_props.get('{urn:oasis:names:tc:opendocument:xmlns:xsl-fo-compatible:1.0}font-style')
                    if font_style == 'italic':
                        style_name = style.get('{urn:oasis:names:tc:opendocument:xmlns:style:1.0}name')
                        if style_name:
                            italic_style_names.add(style_name)
        total_text = ''
        body = root.find('.//office:body', ns)
        if body:
            text_body = body.find('.//office:text', ns)
            if text_body:
                total_text = ''.join(text_body.itertext())
        italic_texts = []
        if body:
            text_body = body.find('.//office:text', ns)
            if text_body:
                for span in text_body.findall('.//text:span', ns):
                    style_name = span.get('{urn:oasis:names:tc:opendocument:xmlns:text:1.0}style-name')
                    if style_name in italic_style_names:
                        text_content = ''.join(span.itertext())
                        if text_content.strip():
                            italic_texts.append(text_content)
        return {'total_text': total_text, 'italic_texts': italic_texts}
    finally:
        os.unlink(tmp_path)

