def get_combine_results(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Combine results from multiple getters into a single dictionary.

    Args:
        env: Environment object
        config: Configuration dict with 'results' key containing a dict of getter configs
               e.g., {
                   "results": {
                       "key1": {"type": "getter_type1", ...},
                       "key2": {"type": "getter_type2", ...}
                   }
               }

    Returns:
        Dict[str, Any]: Dictionary with keys from config["results"] and values from each getter
    """
    import importlib
    import sys
    results = {}
    getter_configs = config.get('results', {})
    for (key, getter_config) in getter_configs.items():
        getter_type = getter_config.get('type')
        if not getter_type:
            logger.error(f"No 'type' specified for getter '{key}'")
            results[key] = None
            continue
        getter_func_name = f'get_{getter_type}'
        try:
            from desktop_env.evaluators import getters
            getter_func = getattr(getters, getter_func_name)
        except (ImportError, AttributeError):
            try:
                getter_func = globals().get(getter_func_name)
                if getter_func is None:
                    raise AttributeError(f'Function {getter_func_name} not found')
            except Exception as e:
                logger.error(f"Getter function '{getter_func_name}' not found: {e}")
                results[key] = None
                continue
        try:
            result = getter_func(env, getter_config)
            results[key] = result
            logger.info(f"Combined getter '{key}': {result}")
        except Exception as e:
            logger.error(f"Error calling getter '{getter_func_name}': {e}")
            import traceback
            logger.error(traceback.format_exc())
            results[key] = None
    return results

