def get_docx_number__1e606a9dcc5b7bbdaeb7738dbdba2d84(env, config: Dict[str, Any]) -> int:
    """Extract a numeric value from a DOCX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to DOCX file on VM

    Returns:
        int: First integer found in the text, or -1 if no number found
    """
    file_path = config.get('path', '')
    if not file_path:
        return -1
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return -1
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        text = '\n'.join([para.text for para in doc.paragraphs])
        numbers = re.findall('\\d+', text)
        if numbers:
            return int(numbers[0])
        return -1
    except Exception as e:
        print(f'Error reading DOCX: {e}')
        return -1
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

