def get_task_completion_status__f139e9cae3dbb4ae7f27c43ef7e2c357(env, config: dict):
    """Verify all task steps: PDF download, row addition, and average calculation.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'spreadsheet_path' and 'pdf_path' keys

    Returns:
        dict: Completion status with keys:
            - pdf_exists: bool - Whether PDF was saved to correct location
            - row_added: bool - Whether new row was added
            - december_data_correct: bool - Whether December entry has correct data
            - average: float - Calculated AWS average
            - total_aws_rows: int - Total number of AWS entries
    """
    result = {'pdf_exists': False, 'row_added': False, 'december_data_correct': False, 'average': 0.0, 'total_aws_rows': 0}
    pdf_path = config.get('pdf_path', '/home/user/Documents/Finance/receipts/aws-invoice-2312.pdf')
    try:
        pdf_bytes = env.controller.get_file(pdf_path)
        result['pdf_exists'] = pdf_bytes is not None and len(pdf_bytes) > 0
    except:
        result['pdf_exists'] = False
    spreadsheet_path = config.get('spreadsheet_path', '/home/user/Documents/Finance/tally_book.xlsx')
    file_bytes = env.controller.get_file(spreadsheet_path)
    if not file_bytes:
        return result
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        aws_entries = []
        for (row_idx, row) in enumerate(ws.iter_rows(min_row=2, values_only=True), start=2):
            if row[0] == 'AWS' and row[2] is not None:
                aws_entries.append({'row_num': row_idx, 'service': row[0], 'month': row[1], 'amount': float(row[2])})
        result['total_aws_rows'] = len(aws_entries)
        if result['total_aws_rows'] >= 5:
            result['row_added'] = True
            december_found = False
            for entry in aws_entries:
                month = entry['month']
                amount = entry['amount']
                if month and ('december' in str(month).lower() or 'dec' in str(month).lower()):
                    if abs(amount - 10.02) < 0.01:
                        december_found = True
                        break
            result['december_data_correct'] = december_found
        if aws_entries:
            total = sum((entry['amount'] for entry in aws_entries))
            result['average'] = round(total / len(aws_entries), 2)
    finally:
        os.unlink(tmp_path)
    return result

def get_docx_blank_lines__98894ee1(env, config: dict):
    """Extract which paragraphs have blank lines after them.

    Args:
        env: DesktopEnv instance
        config: Configuration dict

    Returns:
        List of paragraph indices that have blank lines after them
    """
    file_path = config.get('path') if isinstance(config, dict) else None
    if not file_path:
        return []
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return []
    try:
        from io import BytesIO
        doc = Document(BytesIO(file_bytes))
        blank_after = []
        paragraphs = doc.paragraphs
        for i in range(len(paragraphs) - 1):
            if not paragraphs[i + 1].text.strip():
                blank_after.append(i)
        return blank_after
    except Exception:
        return []

def get_docx_heading_color__c069c1cc(env, config):
    """
    Extract heading text and their font colors from a .docx file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and optional 'headings' list

    Returns:
        dict: Mapping of heading text to RGB color tuple
    """
    from docx import Document
    import io
    file_path = config['path']
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    doc = Document(io.BytesIO(file_bytes))
    heading_colors = {}
    for para in doc.paragraphs:
        text = para.text.strip()
        is_heading = False
        if para.style.name.startswith('Heading'):
            is_heading = True
        if not is_heading and para.runs:
            if len(text) < 100 and len(text) > 0:
                is_heading = True
        if is_heading and text:
            color_rgb = None
            for run in para.runs:
                if run.font.color and run.font.color.rgb:
                    rgb = run.font.color.rgb
                    color_rgb = (rgb[0], rgb[1], rgb[2])
                    break
            if color_rgb:
                heading_colors[text] = color_rgb
    return heading_colors

