def get_data_delete_automacally__2c85759ee3c771990524833aa219e88b(env, config: Dict[str, str]):
    """
    Get the automatic data deletion setting status from Chrome Preferences.
    Checks if Chrome is set to automatically delete cookies and site data when closing.

    Args:
        env: DesktopEnv instance with controller and vm_platform
        config: Configuration dict (not used but required by framework)

    Returns:
        str: "true" if auto-delete mode is enabled, "false" otherwise
    """
    os_type = env.vm_platform
    if os_type == 'Windows':
        preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('LOCALAPPDATA'),\n                                            'Google\\Chrome\\User Data\\Default\\Preferences'))")['output'].strip()
    elif os_type == 'Darwin':
        preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), 'Library/Application Support/Google/Chrome/Default/Preferences'))")['output'].strip()
    elif os_type == 'Linux':
        if 'arm' in platform.machine():
            preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), 'snap/chromium/common/chromium/Default/Preferences'))")['output'].strip()
        else:
            preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), '.config/google-chrome/Default/Preferences'))")['output'].strip()
    else:
        raise Exception('Unsupported operating system')
    try:
        content = env.controller.get_file(preference_file_path)
        data = json.loads(content)
        profile = data.get('profile', {})
        exit_type = profile.get('exit_type', None)
        default_content_settings = profile.get('default_content_setting_values', {})
        cookies_setting = default_content_settings.get('cookies', None)
        content_settings = profile.get('content_settings', {})
        pattern_pairs = content_settings.get('pattern_pairs', {})
        is_auto_delete_enabled = cookies_setting == 4 or (exit_type is not None and cookies_setting is not None) or content_settings.get('cookies', {}).get('clear_on_exit', False) or profile.get('clear_lso_data_enabled', False)
        return 'true' if is_auto_delete_enabled else 'false'
    except Exception as e:
        logger.error(f'Error reading Chrome Preferences: {e}')
        return 'false'

def get_docx_title_count__6a1f15a5(env, config):
    """Count number of title entries in a docx file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'dest'

    Returns:
        int: Number of title entries
    """
    import os
    from docx import Document
    path = config['path']
    dest = config.get('dest', os.path.basename(path))
    cache_path = os.path.join(env.cache_dir, dest)
    file_bytes = env.controller.get_file(path)
    if not file_bytes:
        return 0
    with open(cache_path, 'wb') as f:
        f.write(file_bytes)
    doc = Document(cache_path)
    paragraphs = [p.text.strip() for p in doc.paragraphs if p.text.strip()]
    title_count = sum((1 for p in paragraphs if p.startswith('Title:')))
    return title_count

