def get_docx_para_alignment__5ae6936feae497b01b196ec0b8691fdb(env, config: dict):
    """Extract paragraph alignment information from a DOCX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to VM file path

    Returns:
        dict: Maps paragraph index to alignment value (0=left, 1=center, 2=right, 3=justify)
    """
    file_path = config.get('path', '')
    if not file_path:
        logger.error('No file path provided in config')
        return {}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        logger.error(f'Failed to retrieve file from VM: {file_path}')
        return {}
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        alignments = {}
        content_para_idx = 0
        for para in doc.paragraphs:
            if para.text.strip():
                alignment = para.alignment
                if alignment is not None:
                    alignments[content_para_idx] = int(alignment)
                else:
                    alignments[content_para_idx] = 0
                content_para_idx += 1
        logger.info(f'Extracted alignments for {len(alignments)} paragraphs')
        return alignments
    except Exception as e:
        logger.error(f'Error reading DOCX file: {e}')
        return {}
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

