def get_docx_font_size__fbc6e84eff0ecf96430fe0a843a70a75(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract font size information from specific paragraphs in a docx file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - path: VM path to the docx file
            - paragraph_index: Index of paragraph to check (0-based)

    Returns:
        Dict with font_size (in points) or None if no runs found
    """
    try:
        file_bytes = env.controller.get_file(config['path'])
        if not file_bytes:
            logger.error(f"Failed to get file: {config['path']}")
            return {'font_size': None}
        with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        try:
            doc = Document(tmp_path)
            para_index = config.get('paragraph_index', 0)
            if para_index >= len(doc.paragraphs):
                logger.error(f'Paragraph index {para_index} out of range (total: {len(doc.paragraphs)})')
                return {'font_size': None}
            para = doc.paragraphs[para_index]
            if para.runs:
                font_size = para.runs[0].font.size
                if font_size is not None:
                    font_size_pt = font_size.pt if hasattr(font_size, 'pt') else font_size / 12700
                    return {'font_size': font_size_pt}
            return {'font_size': None}
        finally:
            os.unlink(tmp_path)
    except Exception as e:
        logger.error(f'Error reading docx file: {e}')
        return {'font_size': None}

