def get_bib_neurips_papers__15285ffd(env, config: dict):
    """Extract and verify NeurIPS papers in bibtex file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' parameter

    Returns:
        dict: Contains:
            - 'count': Number of NeurIPS papers
            - 'has_attention_paper': Boolean, True if "Attention is All You Need" found
            - 'has_gpt3_paper': Boolean, True if GPT-3/Language Models paper found
            - 'has_blank_line_separation': Boolean, True if entries separated by blank lines
            - 'entries': List of bibtex entry details
    """
    import re
    path = config.get('path', '/home/user/Desktop/references.bib')
    file_content = env.controller.get_file(path)
    if not file_content:
        return {'count': 0, 'has_attention_paper': False, 'has_gpt3_paper': False, 'has_blank_line_separation': False, 'entries': []}
    content = file_content.decode('utf-8', errors='ignore')
    entries = re.findall('(@\\w+\\{[^@]+)', content, re.MULTILINE | re.DOTALL)
    neurips_entries = []
    has_attention_paper = False
    has_gpt3_paper = False
    for entry in entries:
        booktitle_match = re.search('booktitle\\s*=\\s*\\{([^}]+)\\}', entry, re.IGNORECASE)
        if not booktitle_match:
            continue
        booktitle = booktitle_match.group(1)
        if 'neurips' in booktitle.lower() or 'neural information processing' in booktitle.lower():
            title_match = re.search('title\\s*=\\s*\\{([^}]+)\\}', entry, re.IGNORECASE)
            title = title_match.group(1) if title_match else ''
            year_match = re.search('year\\s*=\\s*\\{?(\\d{4})\\}?', entry, re.IGNORECASE)
            year = year_match.group(1) if year_match else ''
            author_match = re.search('author\\s*=\\s*\\{([^}]+)\\}', entry, re.IGNORECASE)
            author = author_match.group(1) if author_match else ''
            neurips_entries.append({'title': title, 'year': year, 'author': author, 'booktitle': booktitle})
            if 'attention' in title.lower() and 'all you need' in title.lower() or ('vaswani' in author.lower() and year == '2017'):
                has_attention_paper = True
            if 'language model' in title.lower() and 'few-shot' in title.lower() or ('gpt' in title.lower() and '3' in title) or ('brown' in author.lower() and year == '2020'):
                has_gpt3_paper = True
    has_blank_line_separation = False
    if len(neurips_entries) >= 2:
        stripped_content = content.strip()
        if re.search('\\}\\s*\\n\\s*\\n\\s*@', stripped_content):
            has_blank_line_separation = True
    elif len(neurips_entries) < 2:
        has_blank_line_separation = True
    return {'count': len(neurips_entries), 'has_attention_paper': has_attention_paper, 'has_gpt3_paper': has_gpt3_paper, 'has_blank_line_separation': has_blank_line_separation, 'entries': neurips_entries}

def get_docx_alignment__70118bff2da8288404e2b55eea6cd381(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Get document content and paragraph alignment.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key for the file path on VM

    Returns:
        Dict with 'content' (str) and 'is_centered' (bool) keys
    """
    file_path = config.get('path', '')
    if not file_path:
        return {'content': '', 'is_centered': False}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'content': '', 'is_centered': False}
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        content = []
        for paragraph in doc.paragraphs:
            content.append(paragraph.text)
        full_text = '\n'.join(content)
        total_paragraphs = 0
        centered_paragraphs = 0
        for paragraph in doc.paragraphs:
            if paragraph.text.strip():
                total_paragraphs += 1
                if paragraph.alignment == WD_PARAGRAPH_ALIGNMENT.CENTER:
                    centered_paragraphs += 1
        is_centered = total_paragraphs > 0 and centered_paragraphs / total_paragraphs >= 0.9
        return {'content': full_text.strip(), 'is_centered': is_centered}
    finally:
        os.unlink(tmp_path)

def get_sort_and_chart__7ae37a60(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Get sorting information and chart details from a LibreOffice Calc xlsx file.

    This getter:
    1. Fetches the xlsx file from the VM
    2. Extracts Product names (from Product column C, index 2) to check sorting
    3. Extracts chart information to verify chart type and data series mappings

    Args:
        env: Environment object
        config: Configuration dict with keys:
            - path (str): absolute path on VM to the xlsx file
            - dest (str): local filename to save as
            - sheet (int): sheet index (0-based)
            - column (int): column index (0-based) to check sorting (Product column, should be 2 for column C)

    Returns:
        Dict with keys:
            - product_names (list): Product names from the specified column
            - charts (list): List of chart information dicts containing:
                - type (str): Chart class name (e.g., 'LineChart')
                - series_data (dict): Data series with:
                    - x_column (int): Column number (1-based) used for X-axis
                    - y_column (int): Column number (1-based) used for Y-axis
                    - x_values (list): Actual X-axis values from cache
                    - y_values (list): Actual Y-axis values from cache
    """
    path = config['path']
    dest = config['dest']
    sheet_idx = config.get('sheet', 0)
    column_idx = config.get('column', 0)
    cache_path = os.path.join(env.cache_dir, dest)
    if not os.path.exists(cache_path):
        try:
            env.controller.get_file(path, cache_path)
        except Exception as e:
            print(f'Error fetching file from VM: {e}')
            return {'product_names': [], 'charts': []}
    try:
        wb = openpyxl.load_workbook(cache_path, data_only=True)
        ws = wb.worksheets[sheet_idx]
        product_names = []
        for row in range(2, ws.max_row + 1):
            cell = ws.cell(row=row, column=column_idx + 1)
            if cell.value is not None:
                product_names.append(str(cell.value))
        charts = []
        for chart in ws._charts:
            chart_type = chart.__class__.__name__
            series_data = {'x_column': None, 'y_column': None, 'x_values': [], 'y_values': []}
            if hasattr(chart, 'series') and chart.series:
                first_series = chart.series[0]
                if hasattr(first_series, 'cat') and first_series.cat:
                    cat_ref = first_series.cat
                    if hasattr(cat_ref, 'strRef') and cat_ref.strRef:
                        ref_formula = cat_ref.strRef.f if hasattr(cat_ref.strRef, 'f') else None
                        if ref_formula:
                            series_data['x_column'] = _parse_column_from_ref(ref_formula)
                        if hasattr(cat_ref.strRef, 'strCache') and cat_ref.strRef.strCache:
                            cache = cat_ref.strRef.strCache
                            if hasattr(cache, 'pt') and cache.pt:
                                series_data['x_values'] = [pt.v for pt in cache.pt if hasattr(pt, 'v')]
                    elif hasattr(cat_ref, 'numRef') and cat_ref.numRef:
                        ref_formula = cat_ref.numRef.f if hasattr(cat_ref.numRef, 'f') else None
                        if ref_formula:
                            series_data['x_column'] = _parse_column_from_ref(ref_formula)
                        if hasattr(cat_ref.numRef, 'numCache') and cat_ref.numRef.numCache:
                            cache = cat_ref.numRef.numCache
                            if hasattr(cache, 'pt') and cache.pt:
                                series_data['x_values'] = [pt.v for pt in cache.pt if hasattr(pt, 'v')]
                if hasattr(first_series, 'val') and first_series.val:
                    val_ref = first_series.val
                    if hasattr(val_ref, 'numRef') and val_ref.numRef:
                        ref_formula = val_ref.numRef.f if hasattr(val_ref.numRef, 'f') else None
                        if ref_formula:
                            series_data['y_column'] = _parse_column_from_ref(ref_formula)
                        if hasattr(val_ref.numRef, 'numCache') and val_ref.numRef.numCache:
                            cache = val_ref.numRef.numCache
                            if hasattr(cache, 'pt') and cache.pt:
                                series_data['y_values'] = [pt.v for pt in cache.pt if hasattr(pt, 'v')]
            chart_info = {'type': chart_type, 'series_data': series_data}
            charts.append(chart_info)
        wb.close()
        return {'product_names': product_names, 'charts': charts}
    except Exception as e:
        print(f'Error processing xlsx file: {e}')
        return {'product_names': [], 'charts': []}

