def get_bib_years__fb0a8c5b(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Extract comprehensive BibTeX validation data.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict containing:
        - years: List of publication years
        - entries: List of parsed BibTeX entries with metadata
        - docx_papers: List of papers mentioned in references.docx
        - all_present: Whether all docx papers are in bib file
    """
    bib_path = config.get('path', '/home/user/Desktop/references.bib')
    docx_path = '/home/user/Desktop/references.docx'
    file_bytes = env.controller.get_file(bib_path)
    if not file_bytes:
        return {'years': [], 'entries': [], 'docx_papers': [], 'all_present': False}
    bib_content = file_bytes.decode('utf-8', errors='ignore')
    entries = []
    entry_pattern = '@(\\w+)\\{([^,]+),\\s*([^}]+)\\}'
    for match in re.finditer(entry_pattern, bib_content, re.DOTALL):
        entry_type = match.group(1).lower()
        cite_key = match.group(2).strip()
        fields_text = match.group(3)
        fields = {}
        field_pattern = '(\\w+)\\s*=\\s*[{"]([^}"]+)[}"]'
        for field_match in re.finditer(field_pattern, fields_text):
            field_name = field_match.group(1).lower()
            field_value = field_match.group(2).strip()
            fields[field_name] = field_value
        entries.append({'type': entry_type, 'cite_key': cite_key, 'fields': fields})
    years = []
    for entry in entries:
        if 'year' in entry['fields']:
            try:
                years.append(int(entry['fields']['year']))
            except (ValueError, TypeError):
                pass
    docx_papers = []
    try:
        docx_bytes = env.controller.get_file(docx_path)
        if docx_bytes:
            doc = Document(io.BytesIO(docx_bytes))
            full_text = '\n'.join([para.text for para in doc.paragraphs])
            title_patterns = ['(?:^|\\n)([A-Z][^.\\n]{10,100})(?:\\s*\\([^)]+\\d{4}[^)]*\\))', '(?:^|\\n)\\[\\d+\\]\\s*([A-Z][^.\\n]{10,100})\\.', '(?:^|\\n)[^.\\n]+\\(\\d{4}\\)\\.\\s*([A-Z][^.\\n]{10,100})\\.']
            extracted_titles = set()
            for pattern in title_patterns:
                matches = re.finditer(pattern, full_text, re.MULTILINE)
                for match in matches:
                    title = match.group(1).strip()
                    title = re.sub('\\s+', ' ', title)
                    if len(title) > 10:
                        extracted_titles.add(title)
            paper_name_pattern = '\\b([A-Z][A-Za-z]*(?:-\\d+)?)\\b'
            potential_names = re.findall(paper_name_pattern, full_text)
            acronym_names = set()
            for name in potential_names:
                if len(name) >= 3 and name.isupper() or re.match('^[A-Z][a-z]*-\\d+$', name):
                    acronym_names.add(name)
            docx_papers = list(extracted_titles.union(acronym_names))
    except Exception:
        docx_papers = []
    all_present = False
    if docx_papers:
        bib_titles_and_keys = []
        for entry in entries:
            if 'title' in entry['fields']:
                bib_titles_and_keys.append(entry['fields']['title'].lower())
            bib_titles_and_keys.append(entry['cite_key'].lower())
        bib_full_text = bib_content.lower()
        found_count = 0
        for paper in docx_papers:
            found = False
            for bib_title in bib_titles_and_keys:
                if paper.lower() == bib_title or paper.lower() in bib_title.split():
                    found = True
                    break
            if not found and paper.lower() in bib_full_text:
                word_pattern = '\\b' + re.escape(paper.lower()) + '\\b'
                if re.search(word_pattern, bib_full_text):
                    found = True
            if found:
                found_count += 1
        all_present = found_count == len(docx_papers) if docx_papers else False
    else:
        all_present = False
    return {'years': years, 'entries': entries, 'docx_papers': docx_papers, 'all_present': all_present}

def get_selective_copy_check__8fa44abc570499496a7a9f0010281a39(env, config: dict):
    """
    Check file existence in all three directories.

    Args:
        env: DesktopEnv instance
        config: Configuration dict (not used but required by framework)

    Returns:
        dict: File existence information for each directory
    """
    check_script = '\n#!/bin/bash\nresult=""\n\n# Check each directory\nfor dir in dir1 dir2 dir3; do\n    if [ -f "$dir/file1" ]; then\n        result="${result}exists_in_${dir}|"\n    fi\ndone\n\necho "$result"\n'
    result = env.controller.run_bash_script(check_script, timeout=10)
    if result['returncode'] != 0:
        return {'dir1': False, 'dir2': False, 'dir3': False}
    output = result['output'].strip()
    return {'dir1': 'exists_in_dir1' in output, 'dir2': 'exists_in_dir2' in output, 'dir3': 'exists_in_dir3' in output}

def get_docx_station_records__5bf12e02(env, config):
    """Extract all records and count total vs SHS station records.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'station_id' keys

    Returns:
        Dict with total_records, shs_records count, and all_records list
    """
    file_path = config.get('path')
    station_id = config.get('station_id')
    if not file_path or not station_id:
        logger.error('Missing path or station_id in config')
        return {'total_records': 0, 'shs_records': 0, 'all_records': []}
    try:
        file_bytes = env.controller.get_file(file_path)
        if not file_bytes:
            logger.error(f'Could not retrieve file from VM: {file_path}')
            return {'total_records': 0, 'shs_records': 0, 'all_records': []}
        import tempfile
        with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        doc = Document(tmp_path)
        all_records = []
        shs_count = 0
        for para in doc.paragraphs:
            text = para.text.strip()
            if text:
                parts = text.split(',')
                if len(parts) >= 3:
                    record_station = parts[2].strip()
                    all_records.append({'text': text, 'station_id': record_station})
                    if record_station == station_id:
                        shs_count += 1
        import os
        os.unlink(tmp_path)
        return {'total_records': len(all_records), 'shs_records': shs_count, 'all_records': all_records}
    except Exception as e:
        logger.error(f'Error extracting station records: {e}')
        return {'total_records': 0, 'shs_records': 0, 'all_records': []}

def get_docx_uniform_font_size__387390ce(env, config: dict) -> Dict[str, Any]:
    """Check if all text has uniform font size and content is merged from source files.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'dest' keys

    Returns:
        Dict with 'is_uniform', 'font_size', 'content_merged', and 'word_count' keys
    """
    import os
    from docx import Document
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'is_uniform': False, 'font_size': None, 'content_merged': False, 'word_count': 0}
    temp_path = f"/tmp/{config['dest']}"
    with open(temp_path, 'wb') as f:
        f.write(file_bytes)
    try:
        doc = Document(temp_path)
        if len(doc.paragraphs) == 0:
            return {'is_uniform': False, 'font_size': None, 'content_merged': False, 'word_count': 0}
        font_sizes = []
        total_text = ''
        for para in doc.paragraphs:
            total_text += para.text + ' '
            for run in para.runs:
                if run.font.size:
                    font_sizes.append(run.font.size.pt)
        if not font_sizes:
            return {'is_uniform': False, 'font_size': None, 'content_merged': False, 'word_count': 0}
        unique_sizes = set(font_sizes)
        is_uniform = len(unique_sizes) == 1
        font_size = font_sizes[0]
        word_count = len(total_text.split())
        content_merged = word_count >= 20
        return {'is_uniform': is_uniform, 'font_size': font_size, 'content_merged': content_merged, 'word_count': word_count}
    finally:
        if os.path.exists(temp_path):
            os.remove(temp_path)

def get_docx_para_spacing__6241af56(env, config: dict) -> Dict[str, Any]:
    """Get spacing information for a specific paragraph.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'para_index' keys

    Returns:
        Dict: Spacing information (before, after, line_spacing)
    """
    file_path = config.get('path', '/home/user/Desktop/CCCH9003_Tutorial_guidelines.docx')
    para_index = config.get('para_index', 0)
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'before': 0, 'after': 0, 'line_spacing': 1.0}
    doc = Document(io.BytesIO(file_bytes))
    if para_index >= len(doc.paragraphs):
        return {'before': 0, 'after': 0, 'line_spacing': 1.0}
    para = doc.paragraphs[para_index]
    fmt = para.paragraph_format
    spacing_info = {'before': fmt.space_before.pt if fmt.space_before else 0, 'after': fmt.space_after.pt if fmt.space_after else 0, 'line_spacing': fmt.line_spacing if fmt.line_spacing else 1.0}
    return spacing_info

def get_draft_count__a4b48c8b(env, config: Dict[str, Any]) -> List[Dict[str, Any]]:
    """
    Get detailed information about draft emails in Thunderbird Drafts folder.
    Parses the mbox file to extract individual draft details (recipient, subject, timestamp).

    Args:
        env: Environment object
        config: Configuration dict with parameters:
            - profile_path: Path to Thunderbird profile on VM
            - account: Account identifier (e.g., "outlook.office365.com")

    Returns:
        List[Dict[str, Any]]: List of draft email dictionaries, each containing:
            - recipient: Email address of the recipient (To field)
            - subject: Subject line of the draft
            - timestamp: Date header from the email
    """
    profile_path = config.get('profile_path', '/home/user/.thunderbird/t5q2a5hp.default-release')
    account = config.get('account', 'outlook.office365.com')
    drafts_file_path = f'{profile_path}/ImapMail/{account}/Drafts'
    result = env.controller.run_bash_script(f"cat '{drafts_file_path}' 2>/dev/null || echo ''", timeout=30)
    if result['returncode'] != 0 or not result['output'].strip():
        logger.warning(f'Failed to read Drafts file or file is empty: {drafts_file_path}')
        return []
    drafts_content = result['output']
    temp_path = '/tmp/thunderbird_drafts_temp.mbox'
    write_result = env.controller.run_bash_script(f"cat > '{temp_path}' << 'EOF'\n{drafts_content}\nEOF", timeout=10)
    if write_result['returncode'] != 0:
        logger.error(f'Failed to write temporary mbox file')
        return []
    read_result = env.controller.run_bash_script(f"cat '{temp_path}'", timeout=10)
    if read_result['returncode'] != 0:
        logger.error(f'Failed to read temporary mbox file')
        return []
    drafts = []
    try:
        messages = re.split('\\nFrom - ', '\n' + drafts_content)
        for msg_text in messages:
            if not msg_text.strip():
                continue
            try:
                if not msg_text.startswith('From - '):
                    msg_text = 'From - \n' + msg_text
                msg = email.message_from_string(msg_text)
                to_field = msg.get('To', '')
                recipient = ''
                if to_field:
                    (_, recipient) = parseaddr(to_field)
                subject = msg.get('Subject', '')
                timestamp = msg.get('Date', '')
                draft_info = {'recipient': recipient, 'subject': subject, 'timestamp': timestamp}
                drafts.append(draft_info)
                logger.info(f'Parsed draft: recipient={recipient}, subject={subject}')
            except Exception as e:
                logger.error(f'Error parsing individual draft message: {e}')
                continue
    except Exception as e:
        logger.error(f'Error parsing mbox file: {e}')
        return []
    logger.info(f'Found {len(drafts)} draft emails in Drafts folder')
    return drafts

def get_writer_default_font_size__55ccef6016ddd62f70d2e0ecf1a283d1(env, config):
    """Get the default font size setting in LibreOffice Writer.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        int or None: Default font size in points, or None if not found
    """
    config_file_path = config.get('path')
    if not config_file_path:
        logger.error('No path provided in config')
        return None
    file_bytes = env.controller.get_file(config_file_path)
    if not file_bytes:
        logger.error(f'Failed to retrieve file: {config_file_path}')
        return None
    try:
        import io
        tree = ET.parse(io.BytesIO(file_bytes))
        root = tree.getroot()
        namespace = {'oor': 'http://openoffice.org/2001/registry'}
        for elem in root.findall('.//item[@oor:path="/org.openoffice.Office.Writer/DefaultFont"]', namespace):
            for prop in elem.findall('.//prop[@oor:name="StandardHeight"]', namespace):
                for value in prop.findall('value', namespace):
                    try:
                        return int(value.text)
                    except (ValueError, TypeError):
                        logger.error(f'Invalid font size value: {value.text}')
                        return None
        logger.warning('Default font size setting not found in config file')
        return None
    except Exception as e:
        logger.error(f'Error parsing config file: {e}')
        return None

