def get_disable_safe_browsing__eefbb2e3e4c8eef9ec6d58df9ab495a3(env, config: Dict[str, str]):
    """
    Get the Safe Browsing disabled status from Chrome Preferences.
    Checks that both 'safebrowsing.enabled' and 'safebrowsing.enhanced' are false.

    Args:
        env: DesktopEnv instance with controller and vm_platform
        config: Configuration dict (not used but required by framework)

    Returns:
        str: "false" if Safe Browsing is completely disabled (both standard and enhanced are off), "true" if any is enabled
    """
    os_type = env.vm_platform
    if os_type == 'Windows':
        preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('LOCALAPPDATA'),\n                                            'Google\\Chrome\\User Data\\Default\\Preferences'))")['output'].strip()
    elif os_type == 'Darwin':
        preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), 'Library/Application Support/Google/Chrome/Default/Preferences'))")['output'].strip()
    elif os_type == 'Linux':
        if 'arm' in platform.machine():
            preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), 'snap/chromium/common/chromium/Default/Preferences'))")['output'].strip()
        else:
            preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), '.config/google-chrome/Default/Preferences'))")['output'].strip()
    else:
        raise Exception('Unsupported operating system')
    try:
        content = env.controller.get_file(preference_file_path)
        data = json.loads(content)
        safebrowsing = data.get('safebrowsing', {})
        is_enhanced = bool(safebrowsing.get('enhanced', False))
        is_enabled = bool(safebrowsing.get('enabled', False))
        return 'false' if not (is_enhanced or is_enabled) else 'true'
    except Exception as e:
        logger.error(f'Error reading Chrome Preferences: {e}')
        return 'true'

def get_func(env, config: dict):
    """Extract which paragraphs have bold formatting.

    Args:
        env: DesktopEnv instance
        config: Configuration dict containing 'path' key with file path on VM

    Returns:
        List[int]: List of paragraph indices that are fully bold
    """
    file_path = config.get('path') if isinstance(config, dict) else None
    if not file_path:
        return []
    file_content = env.controller.get_file(file_path)
    if not file_content:
        return []
    try:
        from io import BytesIO
        doc = Document(BytesIO(file_content))
        bold_paragraphs = []
        for (i, para) in enumerate(doc.paragraphs):
            if not para.text.strip():
                continue
            if para.runs:
                all_bold = all((run.bold for run in para.runs if run.text.strip()))
                if all_bold and any((run.text.strip() for run in para.runs)):
                    bold_paragraphs.append(i)
        return bold_paragraphs
    except Exception:
        return []

def get_docx_paragraph_alignment__5d9128fd5a70ec4fc8c92d771b41e7fc(env, config: Dict[str, Any]) -> Any:
    """Extract alignment information for paragraphs.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key for file path on VM

    Returns:
        Dict mapping paragraph indices to alignment values
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        alignment_info = {}
        for (idx, paragraph) in enumerate(doc.paragraphs):
            if not paragraph.text.strip():
                continue
            alignment = paragraph.paragraph_format.alignment
            if alignment == WD_PARAGRAPH_ALIGNMENT.CENTER:
                alignment_str = 'center'
            elif alignment == WD_PARAGRAPH_ALIGNMENT.LEFT:
                alignment_str = 'left'
            elif alignment == WD_PARAGRAPH_ALIGNMENT.RIGHT:
                alignment_str = 'right'
            elif alignment == WD_PARAGRAPH_ALIGNMENT.JUSTIFY:
                alignment_str = 'justify'
            else:
                alignment_str = 'left'
            alignment_info[idx] = alignment_str
        return alignment_info
    finally:
        os.unlink(tmp_path)

def get_docx_para_italic_font_size__87d1e02876c78bcdda6834edcc9ad68a(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract italic status, font name, and font size from a specific paragraph in a .docx file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM file path) and 'para_index' (0-based paragraph index)

    Returns:
        Dict with keys:
        - 'all_italic': bool - whether all runs in the paragraph are italic
        - 'font_name': str - the font name if all runs have the same font, or None if inconsistent/empty
        - 'font_size': float - the font size in points if all runs have the same size, or None if inconsistent/empty
        - 'error': str - error message if any
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'all_italic': False, 'font_name': None, 'font_size': None, 'error': 'File not found'}
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        para_index = config.get('para_index', 0)
        if para_index >= len(doc.paragraphs):
            return {'all_italic': False, 'font_name': None, 'font_size': None, 'error': f'Paragraph index {para_index} out of range'}
        para = doc.paragraphs[para_index]
        runs = [r for r in para.runs if r.text.strip()]
        if not runs:
            return {'all_italic': False, 'font_name': None, 'font_size': None, 'error': 'No text runs in paragraph'}
        all_italic = all((r.italic for r in runs))
        font_names = [r.font.name for r in runs if r.font.name is not None]
        if not font_names:
            font_name = None
        elif all((fn == font_names[0] for fn in font_names)) and len(font_names) == len(runs):
            font_name = font_names[0]
        else:
            font_name = None
        font_sizes = [r.font.size.pt for r in runs if r.font.size is not None]
        if not font_sizes:
            font_size = None
        elif all((abs(fs - font_sizes[0]) < 0.01 for fs in font_sizes)) and len(font_sizes) == len(runs):
            font_size = font_sizes[0]
        else:
            font_size = None
        return {'all_italic': all_italic, 'font_name': font_name, 'font_size': font_size, 'error': None}
    except Exception as e:
        return {'all_italic': False, 'font_name': None, 'font_size': None, 'error': str(e)}
    finally:
        os.unlink(tmp_path)

def get_docx_char_count__d29c1205(env, config):
    """Get character count from a docx file (excluding spaces).

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        int: Character count in the document, or 0 if file doesn't exist or can't be read
    """
    import tempfile
    import os
    file_path = config.get('path')
    if not file_path:
        return 0
    try:
        check_cmd = f'test -f "{file_path}" && echo "exists" || echo "not_found"'
        result = env.controller.execute(check_cmd)
        if result is None or 'not_found' in str(result):
            print(f'File not found: {file_path}')
            return 0
        file_bytes = env.controller.get_file(file_path)
        if not file_bytes:
            print(f'Could not read file: {file_path}')
            return 0
        with tempfile.NamedTemporaryFile(delete=False, suffix='.docx') as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        try:
            doc = Document(tmp_path)
            char_count = 0
            for paragraph in doc.paragraphs:
                text = paragraph.text
                char_count += len(text.replace(' ', ''))
            return char_count
        finally:
            os.unlink(tmp_path)
    except Exception as e:
        print(f'Error getting character count: {e}')
        return 0

