def get_docx_all_props__36886bf0(env, config: Dict[str, Any]) -> List[Tuple[str, float, float]]:
    """Extract font name, size, and line spacing from each paragraph.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        List of tuples (font_name, font_size, line_spacing) for each paragraph
    """
    file_path = config.get('path')
    if not file_path:
        return []
    try:
        file_bytes = env.controller.get_file(file_path)
        if not file_bytes:
            return []
        import tempfile
        import os
        with tempfile.NamedTemporaryFile(delete=False, suffix='.docx') as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        try:
            doc = Document(tmp_path)
            results = []
            for para in doc.paragraphs:
                if para.text.strip() and para.runs:
                    font_name = 'Unknown'
                    if para.runs[0].font.name:
                        font_name = para.runs[0].font.name
                    if para.runs[0].font.size:
                        size_pt = para.runs[0].font.size.pt
                    else:
                        size_pt = 12.0
                    spacing = para.paragraph_format.line_spacing
                    if spacing is not None:
                        spacing_val = float(spacing)
                    else:
                        spacing_val = 1.0
                    results.append((font_name, size_pt, spacing_val))
            return results
        finally:
            os.unlink(tmp_path)
    except Exception as e:
        return []

def get_docx_line_spacing__7eeaaa9132bab1b11296c7734630991c(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Get document content and line spacing.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key for the file path on VM

    Returns:
        Dict with 'content' (str) and 'line_spacing' (float) keys
    """
    file_path = config.get('path', '')
    if not file_path:
        return {'content': '', 'line_spacing': None}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'content': '', 'line_spacing': None}
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        content = []
        for paragraph in doc.paragraphs:
            content.append(paragraph.text)
        full_text = ''.join(content)
        line_spacing = None
        line_spacing_values = []
        for paragraph in doc.paragraphs:
            if not paragraph.text.strip():
                continue
            if paragraph.paragraph_format.line_spacing is None:
                return {'content': full_text.strip(), 'line_spacing': None}
            line_spacing_values.append(paragraph.paragraph_format.line_spacing)
        if line_spacing_values:
            if all((abs(val - line_spacing_values[0]) < 0.01 for val in line_spacing_values)):
                line_spacing = line_spacing_values[0]
            else:
                line_spacing = None
        return {'content': full_text.strip(), 'line_spacing': line_spacing}
    finally:
        os.unlink(tmp_path)

def get_docx_title_bold__5c2710f8170271063b1753c9deec1b29(env, config: Dict[str, Any]) -> Dict[str, bool]:
    """
    Extract bold formatting status for lines starting with 'Title:' in a DOCX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the VM file path

    Returns:
        dict: Mapping of title text to whether all runs in that paragraph are bold
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        logger.error(f"Failed to get file from VM: {config['path']}")
        return {}
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        title_bold_status = {}
        for para in doc.paragraphs:
            text = para.text.strip()
            if text.startswith('Title:'):
                if para.runs:
                    all_bold = all((run.bold for run in para.runs if run.text.strip()))
                    title_bold_status[text] = all_bold
                else:
                    title_bold_status[text] = False
        logger.info(f'Extracted title bold status: {title_bold_status}')
        return title_bold_status
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

def get_docx_italic_phrases__453e14831283ed6b7f35857149adf349(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract italic formatting info for specific phrases.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key and 'target_phrases' list

    Returns:
        Dict with phrase_italic_status mapping phrase to boolean
    """
    file_path = config.get('path', '')
    target_phrases = config.get('target_phrases', [])
    if not file_path:
        return {'phrase_italic_status': {}, 'error': 'No path provided'}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'phrase_italic_status': {}, 'error': 'Failed to get file'}
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        phrase_status = {}
        for phrase in target_phrases:
            phrase_status[phrase] = False
            for para in doc.paragraphs:
                para_text = para.text
                if phrase in para_text:
                    phrase_pos = para_text.find(phrase)
                    if phrase_pos < 0:
                        continue
                    phrase_end = phrase_pos + len(phrase)
                    current_pos = 0
                    phrase_fully_italic = True
                    phrase_found_in_runs = False
                    for run in para.runs:
                        run_text = run.text
                        run_start = current_pos
                        run_end = current_pos + len(run_text)
                        if run_start < phrase_end and run_end > phrase_pos:
                            phrase_found_in_runs = True
                            if not run.italic:
                                phrase_fully_italic = False
                                break
                        current_pos = run_end
                    if phrase_found_in_runs and phrase_fully_italic:
                        phrase_status[phrase] = True
                    break
        return {'phrase_italic_status': phrase_status}
    finally:
        os.unlink(tmp_path)

def get_bib_formatting__15d8e4fa(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Check BibTeX file formatting and content validation.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict containing:
        - entry_count: Number of BibTeX entries found
        - blank_line_count: Number of blank lines between entries
        - valid_entries: List of entry info (has required fields, title, author, etc.)
        - has_valid_format: Whether entries have proper BibTeX structure
    """
    file_path = config.get('path', '/home/user/Desktop/references.bib')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'blank_line_count': 0, 'entry_count': 0, 'valid_entries': [], 'has_valid_format': False}
    content = file_bytes.decode('utf-8', errors='ignore')
    lines = content.split('\n')
    blank_line_count = sum((1 for line in lines if line.strip() == ''))
    entry_pattern = '@(\\w+)\\s*\\{([^,]+),([^}]+)\\}'
    entries = re.findall(entry_pattern, content, re.DOTALL)
    entry_count = len(entries)
    valid_entries = []
    for (entry_type, entry_key, entry_body) in entries:
        title_match = re.search('title\\s*=\\s*[{""]([^}""}]+)[}""]', entry_body, re.IGNORECASE | re.DOTALL)
        author_match = re.search('author\\s*=\\s*[{""]([^}""}]+)[}""]', entry_body, re.IGNORECASE | re.DOTALL)
        year_match = re.search('year\\s*=\\s*[{""]?(\\d{4})[}""]?', entry_body, re.IGNORECASE)
        venue_match = re.search('(?:journal|booktitle)\\s*=\\s*[{""]([^}""}]+)[}""]', entry_body, re.IGNORECASE | re.DOTALL)
        biburl_match = re.search('biburl\\s*=', entry_body, re.IGNORECASE)
        bibsource_match = re.search('bibsource\\s*=.*dblp', entry_body, re.IGNORECASE)
        is_dblp_format = 'DBLP:' in entry_key or biburl_match is not None or bibsource_match is not None
        title = title_match.group(1).strip() if title_match else ''
        author = author_match.group(1).strip() if author_match else ''
        year = year_match.group(1).strip() if year_match else ''
        venue = venue_match.group(1).strip() if venue_match else ''
        has_author = bool(author)
        has_title = bool(title)
        has_year = bool(year)
        has_venue = bool(venue)
        is_valid = has_author and has_title
        valid_entries.append({'type': entry_type, 'key': entry_key.strip(), 'title': title, 'author': author, 'year': year, 'venue': venue, 'has_author': has_author, 'has_title': has_title, 'has_year': has_year, 'has_venue': has_venue, 'is_valid': is_valid, 'is_dblp_format': is_dblp_format})
    has_valid_format = entry_count > 0 and all((e['is_valid'] for e in valid_entries))
    return {'blank_line_count': blank_line_count, 'entry_count': entry_count, 'valid_entries': valid_entries, 'has_valid_format': has_valid_format}

