def get_docx_last_para_italic__08e39046(env, config: dict) -> Dict[str, Any]:
    """Get the italic status and font size of the last paragraph in a docx file,
    and verify that the document contains merged content from .txt files.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'dest' keys

    Returns:
        Dict with 'is_italic', 'font_size', 'has_content', and 'paragraph_count' keys
    """
    import os
    from docx import Document
    try:
        file_bytes = env.controller.get_file(config['path'])
    except Exception:
        return {'is_italic': False, 'font_size': None, 'has_content': False, 'paragraph_count': 0}
    if not file_bytes:
        return {'is_italic': False, 'font_size': None, 'has_content': False, 'paragraph_count': 0}
    temp_path = f"/tmp/{config['dest']}"
    with open(temp_path, 'wb') as f:
        f.write(file_bytes)
    try:
        doc = Document(temp_path)
        paragraph_count = len(doc.paragraphs)
        if paragraph_count == 0:
            return {'is_italic': False, 'font_size': None, 'has_content': False, 'paragraph_count': 0}
        paragraphs_with_text = sum((1 for p in doc.paragraphs if p.text.strip()))
        has_content = paragraphs_with_text >= 5
        last_para = doc.paragraphs[-1]
        if len(last_para.runs) == 0:
            return {'is_italic': False, 'font_size': None, 'has_content': has_content, 'paragraph_count': paragraph_count}
        all_italic = True
        has_text = False
        font_sizes = []
        for run in last_para.runs:
            if run.text.strip():
                has_text = True
                run_italic = run.italic if run.italic is not None else False
                if not run_italic:
                    all_italic = False
                if run.font.size:
                    font_sizes.append(run.font.size.pt)
        is_italic = all_italic if has_text else False
        font_size = font_sizes[0] if font_sizes else None
        if font_sizes:
            consistent = all((abs(fs - font_sizes[0]) < 0.5 for fs in font_sizes))
            if not consistent:
                font_size = None
        return {'is_italic': is_italic, 'font_size': font_size, 'has_content': has_content, 'paragraph_count': paragraph_count}
    finally:
        if os.path.exists(temp_path):
            os.remove(temp_path)

def get_column_g_values__cca622ef(env, config: dict):
    """Extract header and all values from column G (Tax column).

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'sheet'

    Returns:
        dict: {
            'header': str value from G1,
            'values': List of tuples [(row_num, value), ...] for all data rows
        }
    """
    vm_path = config.get('path', '/home/user/Name_Order_Id_move_column.xlsx')
    sheet_idx = config.get('sheet', 0)
    file_bytes = env.controller.get_file(vm_path)
    if not file_bytes:
        return {'header': None, 'values': []}
    wb = openpyxl.load_workbook(BytesIO(file_bytes), data_only=True)
    if isinstance(sheet_idx, int):
        ws = wb.worksheets[sheet_idx]
    else:
        ws = wb[sheet_idx]
    header = ws.cell(1, 7).value
    column_g_values = []
    for row_idx in range(2, ws.max_row + 1):
        value = ws.cell(row_idx, 7).value
        if value is not None:
            column_g_values.append((row_idx, value))
    return {'header': header, 'values': column_g_values}

