def get_first_paragraph_alignment__aedb860fbdfc0c5dc752dc2d5dc74671(env, config):
    """Get the alignment of the first paragraph.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        str: Alignment type ('CENTER', 'LEFT', 'RIGHT', 'JUSTIFY', or 'UNKNOWN')
    """
    try:
        file_bytes = env.controller.get_file(config['path'])
        if not file_bytes:
            logger.error(f"Failed to get file: {config['path']}")
            return 'UNKNOWN'
        import tempfile
        import os
        with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        try:
            doc = Document(tmp_path)
            for paragraph in doc.paragraphs:
                if paragraph.text.strip():
                    alignment = paragraph.paragraph_format.alignment
                    if alignment == WD_PARAGRAPH_ALIGNMENT.CENTER:
                        return 'CENTER'
                    elif alignment == WD_PARAGRAPH_ALIGNMENT.LEFT:
                        return 'LEFT'
                    elif alignment == WD_PARAGRAPH_ALIGNMENT.RIGHT:
                        return 'RIGHT'
                    elif alignment == WD_PARAGRAPH_ALIGNMENT.JUSTIFY:
                        return 'JUSTIFY'
                    elif alignment is None:
                        return 'LEFT'
                    else:
                        return 'UNKNOWN'
            return 'UNKNOWN'
        finally:
            os.unlink(tmp_path)
    except Exception as e:
        logger.error(f'Error checking first paragraph alignment: {e}')
        return 'UNKNOWN'

