def get_docx_contains_all__b0201acf(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Check if all specified texts are present in the document and verify comprehensive extraction.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'texts' keys

    Returns:
        Dict with 'text_presence' (list of bools), 'char_count' (int), and 'word_count' (int)
    """
    from docx import Document
    from io import BytesIO
    path = config['path']
    texts_to_check = config.get('texts', [])
    file_bytes = env.controller.get_file(path)
    if not file_bytes:
        logger.error(f'Could not retrieve file: {path}')
        return {'text_presence': [False] * len(texts_to_check), 'char_count': 0, 'word_count': 0}
    try:
        doc = Document(BytesIO(file_bytes))
        full_text = ' '.join((p.text for p in doc.paragraphs))
        results = [text.lower() in full_text.lower() for text in texts_to_check]
        char_count = len(full_text.strip())
        word_count = len(full_text.split())
        logger.info(f'Found {sum(results)}/{len(texts_to_check)} required texts, {word_count} words, {char_count} characters')
        return {'text_presence': results, 'char_count': char_count, 'word_count': word_count}
    except Exception as e:
        logger.error(f'Error reading DOCX file: {e}')
        return {'text_presence': [False] * len(texts_to_check), 'char_count': 0, 'word_count': 0}

