def get_docx_title_format__19c013d2(env, config: dict):
    """Extract title and content formatting information from a docx file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'dest' parameters

    Returns:
        dict: Contains title and content paragraph information
    """
    try:
        file_bytes = env.controller.get_file(config['path'])
        if not file_bytes:
            logger.error(f"Failed to get file from path: {config['path']}")
            return None
        import os
        cache_path = os.path.join(env.cache_dir, config['dest'])
        os.makedirs(os.path.dirname(cache_path), exist_ok=True)
        with open(cache_path, 'wb') as f:
            f.write(file_bytes)
        doc = Document(cache_path)
        if not doc.paragraphs:
            logger.error('Document has no paragraphs')
            return None
        first_para = doc.paragraphs[0]
        from docx.enum.text import WD_PARAGRAPH_ALIGNMENT
        is_centered = first_para.paragraph_format.alignment == WD_PARAGRAPH_ALIGNMENT.CENTER
        is_bold = all((run.bold for run in first_para.runs if run.text.strip())) if first_para.runs else False
        title_text = first_para.text.strip()
        content_paragraphs = []
        for i in range(1, len(doc.paragraphs)):
            para_text = doc.paragraphs[i].text.strip()
            if para_text:
                content_paragraphs.append(para_text)
        content_text = ' '.join(content_paragraphs)
        content_word_count = len(content_text.split()) if content_text else 0
        result = {'title': {'text': title_text, 'is_centered': is_centered, 'is_bold': is_bold}, 'content': {'text': content_text, 'word_count': content_word_count}, 'total_paragraphs': len(doc.paragraphs)}
        logger.info(f"Document structure extracted: title='{title_text}', content_words={content_word_count}, paragraphs={len(doc.paragraphs)}")
        return result
    except Exception as e:
        logger.error(f'Error extracting document structure: {e}')
        return None

