def get_docx_para_underline__a64a879e(env, config):
    """Check if a specific paragraph is underlined.

    Args:
        env: DesktopEnv instance
        config: Config with 'path', 'dest', and 'para_idx'

    Returns:
        dict: {"para_idx": int, "is_underlined": bool}
    """
    file_path = config.get('path', '')
    para_idx = config.get('para_idx', 0)
    file_bytes = env.controller.get_file(file_path)
    if file_bytes is None:
        return {'para_idx': para_idx, 'is_underlined': False}
    doc = Document(io.BytesIO(file_bytes))
    if para_idx >= len(doc.paragraphs):
        return {'para_idx': para_idx, 'is_underlined': False}
    para = doc.paragraphs[para_idx]
    if not para.runs:
        return {'para_idx': para_idx, 'is_underlined': False}
    underlined_runs = sum((1 for run in para.runs if run.underline))
    total_runs = len(para.runs)
    is_underlined = underlined_runs / total_runs >= 0.8
    return {'para_idx': para_idx, 'is_underlined': is_underlined}

def get_docx_time_filtered__5496b77f(env, config):
    """Get lines for a specific time period from a DOCX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'start_hour', 'end_hour' parameters

    Returns:
        int: Number of lines in the specified time range
    """
    vm_path = config.get('path', '/home/user/Desktop/HK_train_record.docx')
    start_hour = config.get('start_hour', 6)
    end_hour = config.get('end_hour', 10)
    file_bytes = env.controller.get_file(vm_path)
    if not file_bytes:
        return 0
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(delete=False, suffix='.docx') as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        count = 0
        for p in doc.paragraphs:
            text = p.text.strip()
            if text and ',' in text:
                parts = text.split(',')
                if len(parts) >= 1:
                    time_str = parts[0].strip()
                    try:
                        hour = int(time_str.split(':')[0])
                        if start_hour <= hour < end_hour:
                            count += 1
                    except (ValueError, IndexError):
                        pass
        return count
    finally:
        os.unlink(tmp_path)

