def get_docx_second_para_alignment__77753678(env, config: dict):
    """Extract second paragraph alignment from DOCX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with file path

    Returns:
        str: Alignment type ('LEFT', 'CENTER', 'RIGHT', 'JUSTIFY', or 'NONE')
    """
    file_path = config.get('path', '')
    if not file_path:
        return 'NONE'
    try:
        file_bytes = env.controller.get_file(file_path)
        if not file_bytes:
            return 'NONE'
        from io import BytesIO
        doc = Document(BytesIO(file_bytes))
        non_empty_paras = [p for p in doc.paragraphs if p.text.strip()]
        if len(non_empty_paras) < 2:
            return 'NONE'
        second_para = non_empty_paras[1]
        alignment = second_para.paragraph_format.alignment
        if alignment == WD_PARAGRAPH_ALIGNMENT.LEFT:
            return 'LEFT'
        elif alignment == WD_PARAGRAPH_ALIGNMENT.CENTER:
            return 'CENTER'
        elif alignment == WD_PARAGRAPH_ALIGNMENT.RIGHT:
            return 'RIGHT'
        elif alignment == WD_PARAGRAPH_ALIGNMENT.JUSTIFY:
            return 'JUSTIFY'
        else:
            return 'LEFT'
    except Exception as e:
        print(f'Error reading DOCX alignment: {e}')
        return 'NONE'

def get_text_position__68e0eaa1c0be88d7d26c920a571b88e0(env, config):
    """
    Extract the rightmost position of the text from an exported image.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the VM file

    Returns:
        int: X-coordinate of the rightmost text pixel
    """
    file_path = config.get('path')
    if not file_path:
        return None
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return None
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(suffix='.png', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        image = Image.open(tmp_path)
        gray_image = image.convert('L')
        (width, height) = image.size
        right_most = 0
        for y in range(height):
            for x in range(width - 1, -1, -1):
                if gray_image.getpixel((x, y)) < 128:
                    right_most = max(right_most, x)
                    break
        return right_most
    finally:
        os.unlink(tmp_path)

def get_metrics_reporting_disabled__526bed5f(env, config: Dict[str, str]):
    """Check if usage statistics reporting is disabled in Chrome settings."""
    os_type = env.vm_platform
    if os_type == 'Windows':
        preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('LOCALAPPDATA'),\n                                            'Google\\Chrome\\User Data\\Default\\Preferences'))")['output'].strip()
    elif os_type == 'Darwin':
        preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), 'Library/Application Support/Google/Chrome/Default/Preferences'))")['output'].strip()
    elif os_type == 'Linux':
        if 'arm' in platform.machine():
            preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), 'snap/chromium/common/chromium/Default/Preferences'))")['output'].strip()
        else:
            preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), '.config/google-chrome/Default/Preferences'))")['output'].strip()
    else:
        raise Exception('Unsupported operating system')
    try:
        content = env.controller.get_file(preference_file_path)
        data = json.loads(content)
        metrics_enabled = data.get('user_experience_metrics', {}).get('reporting_enabled', True)
        return 'true' if not metrics_enabled else 'false'
    except Exception as e:
        logger.error(f'Error: {e}')
        return 'false'

def get_docx_word_count__f3c1df34(env, config):
    """Get the word count of a DOCX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key for DOCX file path on VM

    Returns:
        int: Number of words in the document, or 0 if file doesn't exist
    """
    vm_path = config.get('path', '')
    docx_bytes = env.controller.get_file(vm_path)
    if not docx_bytes:
        return 0
    cache_path = os.path.join(env.cache_dir, 'temp_check.docx')
    with open(cache_path, 'wb') as f:
        f.write(docx_bytes)
    try:
        doc = Document(cache_path)
        total_text = ' '.join([para.text for para in doc.paragraphs])
        word_count = len(total_text.split())
        return word_count
    except Exception as e:
        print(f'Error reading DOCX: {e}')
        return 0

def get_docx_first_line_font_props__ea7f5195(env, config: dict):
    """Extract first paragraph font properties from DOCX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with file path

    Returns:
        dict: Font properties (name, size, bold, italic, underline)
    """
    file_path = config.get('path', '')
    if not file_path:
        return {}
    try:
        file_bytes = env.controller.get_file(file_path)
        if not file_bytes:
            return {}
        from io import BytesIO
        doc = Document(BytesIO(file_bytes))
        if not doc.paragraphs or not doc.paragraphs[0].runs:
            return {}
        first_para = doc.paragraphs[0]
        first_run = first_para.runs[0]
        font_size = None
        if first_run.font.size:
            font_size = first_run.font.size.pt
        return {'name': first_run.font.name, 'size': font_size, 'bold': first_run.font.bold, 'italic': first_run.font.italic, 'underline': first_run.font.underline}
    except Exception as e:
        print(f'Error reading DOCX font properties: {e}')
        return {}

def get_cs_yoy_changes__5e1999a036977fffea3dd7100423b920(env, config):
    """Extract year-over-year changes and application counts from CS-GRF-YoY.xlsx

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: {
            'applications': {year: count} for years 2019-2023,
            'changes': {year: change} for years 2020-2023
        }
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return None
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        applications = {}
        changes = {}
        for row in ws.iter_rows(min_row=2, max_col=3, values_only=True):
            if row[0] is not None:
                try:
                    year = int(row[0])
                    if row[1] is not None:
                        app_count = int(row[1]) if isinstance(row[1], (int, float)) else None
                        if app_count is not None and 2019 <= year <= 2023:
                            applications[year] = app_count
                    if row[2] is not None and 2020 <= year <= 2023:
                        change = int(row[2]) if isinstance(row[2], (int, float)) else None
                        if change is not None:
                            changes[year] = change
                except (ValueError, TypeError):
                    continue
        result = {'applications': applications, 'changes': changes}
        return result if len(applications) > 0 or len(changes) > 0 else None
    finally:
        os.unlink(tmp_path)

def get_odt_italic_text_bold_status__46a9e50dce81f96c5ffd94c5cc9f331b(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract formatting status for all italic text in ODT file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path'

    Returns:
        Dict with italic text instances and whether they are also bold
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'instances': [], 'all_bold_and_italic': False}
    with tempfile.NamedTemporaryFile(suffix='.odt', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = load(tmp_path)
        italic_instances = []
        for para in doc.getElementsByType(P):
            for span in para.getElementsByType(Span):
                text = teletype.extractText(span)
                if not text.strip():
                    continue
                style_name = span.getAttribute('stylename')
                is_italic = False
                is_bold = False
                if style_name:
                    for automatic_style in doc.automaticstyles.childNodes:
                        if automatic_style.getAttribute('name') == style_name:
                            for property in automatic_style.childNodes:
                                font_style = property.getAttribute('fontstyle')
                                font_weight = property.getAttribute('fontweight')
                                if font_style == 'italic':
                                    is_italic = True
                                if font_weight == 'bold':
                                    is_bold = True
                if is_italic:
                    italic_instances.append({'text': text.strip()[:50], 'is_bold': is_bold, 'is_italic': True})
        all_bold = len(italic_instances) > 0 and all((inst['is_bold'] for inst in italic_instances))
        return {'instances': italic_instances, 'all_bold_and_italic': all_bold, 'count': len(italic_instances)}
    finally:
        os.unlink(tmp_path)

def get_odt_underlined_text__bd7d36c3(env, config):
    """Extract all underlined text from an ODT file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' parameter

    Returns:
        list: List of underlined text strings found in the document
    """
    vm_path = config.get('path', '/home/user/Desktop/sample-recruitment-phone-script.odt')
    file_bytes = env.controller.get_file(vm_path)
    if not file_bytes:
        return []
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(delete=False, suffix='.odt') as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = load(tmp_path)
        underlined_texts = []
        for span in doc.getElementsByType(text.Span):
            style_name = span.getAttribute('stylename')
            if style_name:
                for auto_style in doc.automaticstyles.getElementsByType(style.Style):
                    if auto_style.getAttribute('name') == style_name:
                        text_props = auto_style.getElementsByType(style.TextProperties)
                        for prop in text_props:
                            underline_style = prop.getAttribute('textunderlinestyle')
                            if underline_style and underline_style != 'none':
                                span_text = teletype.extractText(span)
                                if span_text.strip():
                                    underlined_texts.append(span_text.strip())
        return underlined_texts
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

def get_docx_italic_last_para__657863969c9d89eaf7f064809b0043fc(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract italic formatting information from the last paragraph of a DOCX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the DOCX file

    Returns:
        Dict with 'all_italic' boolean indicating if all runs in last paragraph are italic
    """
    file_path = config.get('path', '')
    if not file_path:
        logger.error('No file path provided in config')
        return {'all_italic': False}
    try:
        file_bytes = env.controller.get_file(file_path)
        if not file_bytes:
            logger.error(f'Failed to retrieve file: {file_path}')
            return {'all_italic': False}
        with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        try:
            doc = Document(tmp_path)
            last_para = None
            for para in reversed(doc.paragraphs):
                if para.text.strip():
                    last_para = para
                    break
            if not last_para or not last_para.runs:
                logger.warning('No non-empty paragraph with runs found')
                return {'all_italic': False}
            all_italic = all((run.italic for run in last_para.runs if run.text.strip()))
            logger.info(f'Last paragraph italic check: {all_italic}')
            return {'all_italic': all_italic}
        finally:
            os.unlink(tmp_path)
    except Exception as e:
        logger.error(f'Error processing DOCX file: {e}')
        return {'all_italic': False}

def get_docx_station_filter__237db233bbdb3a0cc4ac31a2e872f7e8(env, config: Dict[str, Any]) -> List[str]:
    """
    Extract all train records from a docx file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the VM file

    Returns:
        List of train record lines (each line is a string)
    """
    file_path = config.get('path')
    if not file_path:
        logger.error('No file path provided in config')
        return []
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        logger.error(f'Failed to get file from VM: {file_path}')
        return []
    try:
        with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        doc = Document(tmp_path)
        records = []
        for para in doc.paragraphs:
            line = para.text.strip()
            if line and ',' in line:
                parts = line.split(',')
                if len(parts) == 4:
                    records.append(line)
        return records
    except Exception as e:
        logger.error(f'Error reading docx file: {e}')
        return []
    finally:
        if 'tmp_path' in locals():
            try:
                os.unlink(tmp_path)
            except Exception:
                pass

