def get_docx_train_station_combo__42322197(env, config):
    """Get lines matching both train ID and station from a DOCX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'train_id', 'station' parameters

    Returns:
        int: Number of lines matching both filters
    """
    vm_path = config.get('path', '/home/user/Desktop/HK_train_record.docx')
    filter_train = config.get('train_id', 'E201')
    filter_station = config.get('station', 'FAN')
    file_bytes = env.controller.get_file(vm_path)
    if not file_bytes:
        return 0
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(delete=False, suffix='.docx') as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        count = 0
        for p in doc.paragraphs:
            text = p.text.strip()
            if text and ',' in text:
                parts = text.split(',')
                if len(parts) >= 3:
                    train_id = parts[1].strip()
                    station = parts[2].strip()
                    if train_id == filter_train and station == filter_station:
                        count += 1
        return count
    finally:
        os.unlink(tmp_path)

def get_docx_alignment__214fb6bb44096aff2eeecab353a09db1(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract paragraph alignment from a docx file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - path: VM path to the docx file
            - paragraph_index: Index of paragraph to check (0-based)

    Returns:
        Dict with alignment value (0=LEFT, 1=CENTER, 2=RIGHT, 3=JUSTIFY)
    """
    try:
        file_bytes = env.controller.get_file(config['path'])
        if not file_bytes:
            logger.error(f"Failed to get file: {config['path']}")
            return {'alignment': None}
        with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        try:
            doc = Document(tmp_path)
            para_index = config.get('paragraph_index', 0)
            if para_index >= len(doc.paragraphs):
                logger.error(f'Paragraph index {para_index} out of range (total: {len(doc.paragraphs)})')
                return {'alignment': None}
            para = doc.paragraphs[para_index]
            alignment = para.paragraph_format.alignment
            if alignment is None:
                alignment_value = 0
            else:
                alignment_value = int(alignment)
            return {'alignment': alignment_value}
        finally:
            os.unlink(tmp_path)
    except Exception as e:
        logger.error(f'Error reading docx file: {e}')
        return {'alignment': None}

def get_docx_underline__80d6bc51(env, config: dict):
    """Extract which paragraphs are underlined.

    Args:
        env: DesktopEnv instance
        config: Configuration dict containing 'path' key

    Returns:
        List of paragraph indices that are underlined
    """
    file_path = config.get('path') if isinstance(config, dict) else None
    if not file_path:
        return []
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return []
    try:
        doc = Document(BytesIO(file_bytes))
        underlined_paragraphs = []
        for (i, para) in enumerate(doc.paragraphs):
            if not para.text.strip():
                continue
            if para.runs:
                text_runs = [run for run in para.runs if run.text.strip()]
                if text_runs:
                    all_underlined = all((run.underline for run in text_runs))
                    if all_underlined:
                        underlined_paragraphs.append(i)
        return underlined_paragraphs
    except Exception:
        return []

def get_writer_multiple_settings__b2a56b55(env, config: Dict[str, Any]):
    """Extract multiple default font settings for LibreOffice Writer.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' to registrymodifications.xcu file

    Returns:
        dict: Dict with standard font name and size
    """
    from desktop_env.evaluators.getters.file import get_vm_file
    config_file_path = get_vm_file(env, config)
    if not config_file_path:
        logger.error('Failed to get config file')
        return None
    try:
        tree = ET.parse(config_file_path)
        root = tree.getroot()
        namespace = {'oor': 'http://openoffice.org/2001/registry'}
        result = {'font': None, 'size': None}
        for elem in root.findall('.//item[@oor:path="/org.openoffice.Office.Writer/DefaultFont"]', namespace):
            for prop in elem.findall('.//prop[@oor:name="Standard"]', namespace):
                for value in prop.findall('value', namespace):
                    result['font'] = value.text
            for prop in elem.findall('.//prop[@oor:name="StandardHeight"]', namespace):
                for value in prop.findall('value', namespace):
                    result['size'] = value.text
        if result['font'] is None or result['size'] is None:
            logger.warning('Default font settings not found in config')
            return None
        return result
    except Exception as e:
        logger.error(f'Error parsing config file: {e}')
        return None

def get_nba_filter_state(env, config: Dict[str, Any]):
    """
    Get NBA store filter state by checking both HTML class elements and URL parameters.

    This function properly handles URL encoding for price filters (e.g., "under $50" vs "under%20%2450").

    Args:
        env: Environment object
        config: Configuration dict with:
            - class_multiObject_search_exist: Dict mapping class names to list of expected filter texts
            - url_include_expected: List of expected strings in URL
            - url_include_expected_multichoice: Dict mapping URL-encoded variants to canonical filter names
              Uses OR logic: if ANY variant matches, returns True for the canonical name

    Returns:
        dict: Mapping of filter names to boolean values indicating presence
    """
    from desktop_env.evaluators.getters.chrome import get_active_url_from_accessTree
    active_tab_url = get_active_url_from_accessTree(env, config)
    logger.info(f'[NBA_FILTER] Active tab URL: {active_tab_url}')
    if not isinstance(active_tab_url, str):
        logger.error(f'[NBA_FILTER] active_tab_url is not a string, got {type(active_tab_url)}: {active_tab_url}')
        return None
    host = env.vm_ip
    port = env.chromium_port
    server_port = env.server_port
    remote_debugging_url = f'http://{host}:{port}'
    logger.info(f'[NBA_FILTER] get_nba_filter_state called with config: {config}')
    from playwright.sync_api import sync_playwright
    import json
    import requests
    import platform
    with sync_playwright() as p:
        try:
            browser = p.chromium.connect_over_cdp(remote_debugging_url)
            logger.info(f'[NBA_FILTER] Successfully connected to Chrome instance')
        except Exception as e:
            logger.warning(f'[NBA_FILTER] Failed to connect, starting new instance: {e}')
            if 'arm' in platform.machine():
                payload = json.dumps({'command': ['chromium', '--remote-debugging-port=1337'], 'shell': False})
            else:
                payload = json.dumps({'command': ['google-chrome', '--remote-debugging-port=1337'], 'shell': False})
            headers = {'Content-Type': 'application/json'}
            requests.post('http://' + host + ':' + str(server_port) + '/setup' + '/launch', headers=headers, data=payload)
            time.sleep(5)
            browser = p.chromium.connect_over_cdp(remote_debugging_url)
        target_page = None
        for context in browser.contexts:
            for page in context.pages:
                try:
                    page.wait_for_load_state('networkidle', timeout=60000)
                    if page.is_closed():
                        continue

                    def normalize_url(url):
                        return unquote(url).rstrip('/')
                    try:
                        page_url = page.url
                    except Exception:
                        continue
                    if normalize_url(page_url) == normalize_url(active_tab_url):
                        target_page = page
                        logger.info(f'[NBA_FILTER] Found target page: {target_page.url}')
                        break
                except Exception as page_error:
                    logger.debug(f'[NBA_FILTER] Error processing page: {page_error}')
                    continue
        if target_page is None:
            logger.error('[NBA_FILTER] Could not find target tab matching URL')
            browser.close()
            return {}
        return_json = {}

        def safely_get_text_content(selector):
            try:
                if target_page.is_closed():
                    logger.warning(f'[NBA_FILTER] Target page is closed')
                    return []
                elements = target_page.query_selector_all(selector)
                return [element.text_content().strip() for element in elements if element]
            except Exception as e:
                logger.warning(f"[NBA_FILTER] Error getting text content for selector '{selector}': {e}")
                return []
        class_multiObject_search_exist = config.get('class_multiObject_search_exist', {})
        for (class_name, object_list) in class_multiObject_search_exist.items():
            elements_texts = safely_get_text_content('.' + class_name)
            logger.info(f"[NBA_FILTER] Found elements with class '{class_name}': {elements_texts}")
            logger.info(f"[NBA_FILTER] Expected elements: {[obj for obj in object_list if obj != 'is_other_exist']}")
            for each_object in object_list:
                if each_object == 'is_other_exist':
                    continue
                if any((each_object.lower() == text.lower() for text in elements_texts)):
                    return_json[each_object] = True
                else:
                    return_json[each_object] = False
            if 'is_other_exist' in object_list:
                extra_elements = []
                for each_element in elements_texts:
                    if not any((each_element.lower() == obj.lower() for obj in object_list if obj != 'is_other_exist')):
                        extra_elements.append(each_element)
                        return_json['is_other_exist'] = True
                if extra_elements:
                    logger.warning(f'[NBA_FILTER] Found unexpected elements: {extra_elements}')
                else:
                    logger.info(f'[NBA_FILTER] No unexpected elements found')
                if 'is_other_exist' not in return_json:
                    return_json['is_other_exist'] = False
        url_include_expected = config.get('url_include_expected', [])
        try:
            page_url = target_page.url.lower()
            logger.info(f'[NBA_FILTER] Checking URL: {page_url}')
            for key in url_include_expected:
                if key.lower() in page_url:
                    if key.lower() not in return_json:
                        return_json[key.lower()] = True
                        logger.info(f"[NBA_FILTER] Found '{key}' in URL")
                elif key.lower() not in return_json:
                    return_json[key.lower()] = False
                    logger.info(f"[NBA_FILTER] Did not find '{key}' in URL")
        except Exception as e:
            logger.error(f'[NBA_FILTER] Error checking URL: {e}')
        url_include_expected_multichoice = config.get('url_include_expected_multichoice', {})
        canonical_to_variants = {}
        for (variant, canonical) in url_include_expected_multichoice.items():
            if canonical not in canonical_to_variants:
                canonical_to_variants[canonical] = []
            canonical_to_variants[canonical].append(variant)
        logger.info(f'[NBA_FILTER] Checking multichoice URL patterns: {canonical_to_variants}')
        try:
            page_url = target_page.url.lower()
            for (canonical, variants) in canonical_to_variants.items():
                found = False
                for variant in variants:
                    if variant.lower() in page_url:
                        found = True
                        logger.info(f"[NBA_FILTER] Found variant '{variant}' in URL for canonical '{canonical}'")
                        break
                if canonical.lower() not in return_json:
                    return_json[canonical.lower()] = found
                    if found:
                        logger.info(f"[NBA_FILTER] Set '{canonical}' to True (matched)")
                    else:
                        logger.info(f"[NBA_FILTER] Set '{canonical}' to False (no match)")
                else:
                    return_json[canonical.lower()] = return_json[canonical.lower()] or found
                    if found:
                        logger.info(f"[NBA_FILTER] Updated '{canonical}' to True (OR logic)")
        except Exception as e:
            logger.error(f'[NBA_FILTER] Error checking multichoice URL: {e}')
        browser.close()
        logger.info(f'[NBA_FILTER] Final result: {return_json}')
        return return_json

def get_ext_name_list__91053ece(env, config):
    """Get list of all installed Chrome extension names.

    Args:
        env: DesktopEnv instance
        config: Configuration dict (unused but required by framework)

    Returns:
        List of extension names
    """
    os_type = env.vm_platform
