def get_column_range_highlights__c221760b(env, config: dict):
    """
    Extract highlighting info for cells in a column range.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'dest', 'sheet', 'column', 'start_row', 'end_row'

    Returns:
        list of dicts with cell ref and highlighting status
    """
    file_bytes = env.controller.get_file(config['path'])
    if file_bytes is None:
        return None
    cache_path = os.path.join(env.cache_dir, config['dest'])
    os.makedirs(env.cache_dir, exist_ok=True)
    with open(cache_path, 'wb') as f:
        f.write(file_bytes)
    wb = openpyxl.load_workbook(cache_path)
    sheet_idx = config.get('sheet', 0)
    if isinstance(sheet_idx, int):
        ws = wb.worksheets[sheet_idx]
    else:
        ws = wb[sheet_idx]
    column = config['column']
    start_row = config['start_row']
    end_row = config['end_row']
    cells_info = []
    for row in range(start_row, end_row + 1):
        cell_ref = f'{column}{row}'
        cell = ws[cell_ref]
        fill = cell.fill
        has_fill = fill is not None and fill.fill_type == 'solid' and (fill.fgColor is not None)
        cells_info.append({'cell': cell_ref, 'value': cell.value, 'has_fill': has_fill})
    return cells_info

def get_text_position_comparison__0fe6ee6f(env, config):
    """
    Get both the initial and final text positions for comparison.

    This getter exports the initial XCF file to PNG, finds the leftmost dark pixel
    to determine the starting position, and also retrieves the final PNG to compare.

    Args:
        env: Environment object
        config: Configuration dict with:
            - 'xcf_path': Path to the original XCF file
            - 'final_png_path': Path to the final exported PNG file

    Returns:
        dict: Dictionary with 'initial' and 'final' keys
            - initial: dict with 'x' position and 'width'
            - final: str path to the final PNG file
    """
    try:
        xcf_path = config.get('xcf_path', '/home/user/Desktop/orange_background.xcf')
        final_png_path = config.get('final_png_path', '/home/user/Desktop/movedleft_textbox.png')
        temp_png = '/tmp/initial_text_position.png'
        export_cmd = f'''\nimport subprocess\nimport os\n\n# Export XCF to PNG using gimp-console\ncmd = [\n    'gimp-console',\n    '-i',\n    '-b',\n    f'(let* ((image (car (gimp-file-load RUN-NONINTERACTIVE "{xcf_path}" "{xcf_path}"))) '\n    f'(drawable (car (gimp-image-merge-visible-layers image CLIP-TO-IMAGE)))) '\n    f'(file-png-save RUN-NONINTERACTIVE image drawable "{temp_png}" "{temp_png}" 0 9 0 0 0 0 0) '\n    f'(gimp-image-delete image))',\n    '-b',\n    '(gimp-quit 0)'\n]\nsubprocess.run(cmd, capture_output=True, timeout=30)\n'''
        result = env.controller.execute_python_command(export_cmd)
        png_content = env.controller.get_file(temp_png)
        if not png_content:
            return None
        local_initial_path = os.path.join(env.cache_dir, 'initial_text_position.png')
        with open(local_initial_path, 'wb') as f:
            f.write(png_content)
        source_image = Image.open(local_initial_path)
        gray_image = source_image.convert('L')
        (width, height) = source_image.size
        left_most_dark_pixel = width
        for y in range(height):
            for x in range(width):
                if gray_image.getpixel((x, y)) < 128:
                    left_most_dark_pixel = min(left_most_dark_pixel, x)
                    break
        final_png_content = env.controller.get_file(final_png_path)
        if not final_png_content:
            return None
        local_final_path = os.path.join(env.cache_dir, 'movedleft_textbox.png')
        with open(local_final_path, 'wb') as f:
            f.write(final_png_content)
        return {'initial': {'x': left_most_dark_pixel, 'width': width}, 'final': local_final_path}
    except Exception as e:
        import logging
        logging.error(f'Error getting text position comparison: {e}')
        import traceback
        logging.error(traceback.format_exc())
        return None

