def get_grammar_test_answer_details__b1578d294f483f13e4e751bc2459e330(env, config: Dict[str, Any]) -> Dict[str, Dict[str, Any]]:
    """Extract grammar test answer details from Answer.docx file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the docx file

    Returns:
        Dict with test sections as keys and dict of answer properties as values
        (e.g., {'Grammar test 1:': {'answer': 'bbbad', 'length': 5}})
    """
    try:
        file_bytes = env.controller.get_file(config['path'])
        if not file_bytes:
            logger.error(f"Failed to get file from VM: {config['path']}")
            return {}
        with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        try:
            doc = Document(tmp_path)
            test_details = {}
            current_section = None
            for para in doc.paragraphs:
                text = para.text.strip()
                if text.startswith('Grammar test'):
                    current_section = text
                    test_details[current_section] = {'answer': '', 'length': 0}
                elif current_section and text:
                    test_details[current_section]['answer'] = text
                    cleaned_answer = text.replace(' ', '').replace('\t', '')
                    test_details[current_section]['length'] = len(cleaned_answer)
            logger.info(f'Extracted test details: {test_details}')
            return test_details
        finally:
            os.unlink(tmp_path)
    except Exception as e:
        logger.error(f'Error extracting grammar test answer details: {e}')
        return {}

