def get_docx_sorted_trains__310a5e82(env, config):
    """Extract content added at the end of the document.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict with:
            - 'added_list': List of train IDs extracted from the end of the document
            - 'list_exists': Boolean indicating if a sorted list was found at the end
    """
    file_path = config.get('path')
    if not file_path:
        logger.error('No file path provided in config')
        return {'added_list': [], 'list_exists': False}
    try:
        file_bytes = env.controller.get_file(file_path)
        if not file_bytes:
            logger.error(f'Could not retrieve file from VM: {file_path}')
            return {'added_list': [], 'list_exists': False}
        import tempfile
        with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        doc = Document(tmp_path)
        original_record_count = 0
        last_original_index = -1
        for (idx, para) in enumerate(doc.paragraphs):
            text = para.text.strip()
            if text:
                parts = text.split(',')
                if len(parts) == 4:
                    original_record_count += 1
                    last_original_index = idx
        added_content = []
        if last_original_index >= 0 and last_original_index < len(doc.paragraphs) - 1:
            for idx in range(last_original_index + 1, len(doc.paragraphs)):
                text = doc.paragraphs[idx].text.strip()
                if text:
                    added_content.append(text)
        added_train_ids = []
        list_exists = False
        if added_content:
            list_exists = True
            for line in added_content:
                line_stripped = line.strip()
                if line_stripped and len(line_stripped) >= 4:
                    import re
                    match = re.search('E\\d{3}', line_stripped)
                    if match:
                        added_train_ids.append(match.group())
        import os
        os.unlink(tmp_path)
        return {'added_list': added_train_ids, 'list_exists': list_exists}
    except Exception as e:
        logger.error(f'Error extracting sorted trains: {e}')
        return {'added_list': [], 'list_exists': False}

