def get_popup_blocker_enabled__980fd38b(env, config: Dict[str, str]):
    """Check if popup blocker is enabled in Chrome preferences."""
    os_type = env.vm_platform
    if os_type == 'Windows':
        preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('LOCALAPPDATA'),\n                                            'Google\\Chrome\\User Data\\Default\\Preferences'))")['output'].strip()
    elif os_type == 'Darwin':
        preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), 'Library/Application Support/Google/Chrome/Default/Preferences'))")['output'].strip()
    elif os_type == 'Linux':
        if 'arm' in platform.machine():
            preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), 'snap/chromium/common/chromium/Default/Preferences'))")['output'].strip()
        else:
            preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), '.config/google-chrome/Default/Preferences'))")['output'].strip()
    else:
        raise Exception('Unsupported operating system')
    try:
        content = env.controller.get_file(preference_file_path)
        data = json.loads(content)
        profile = data.get('profile', {})
        default_content_settings = profile.get('default_content_settings', {})
        popups = default_content_settings.get('popups', 1)
        return 'true' if popups == 2 else 'false'
    except Exception as e:
        logger.error(f'Error: {e}')
        return 'false'

def get_fastapi_dev_setup(env, config):
    """
    Get FastAPI development environment setup status.

    Args:
        env: Environment object
        config: Configuration dict

    Returns:
        dict: Status of repository, installation, and import with structure:
        {
            'repo_exists': bool,  # /home/user/fastapi/.git exists
            'is_editable_install': bool,  # pip list shows editable install
            'import_succeeds': bool,  # fastapi can be imported
            'import_error': str  # error message if import fails
        }
    """
    result = {'repo_exists': False, 'is_editable_install': False, 'import_succeeds': False, 'import_error': ''}
    repo_check_cmd = "test -d /home/user/fastapi/.git && echo 'exists' || echo 'not_exists'"
    repo_response = env.controller.run_bash_script(repo_check_cmd, timeout=10)
    if repo_response and repo_response.get('stdout'):
        repo_output = repo_response['stdout']
        if 'exists' in repo_output.lower():
            result['repo_exists'] = True
    pip_list_cmd = 'pip list -e 2>&1'
    pip_response = env.controller.run_bash_script(pip_list_cmd, timeout=10)
    if pip_response and pip_response.get('stdout'):
        pip_output = pip_response['stdout']
        if 'fastapi' in pip_output.lower() and '/home/user/fastapi' in pip_output:
            result['is_editable_install'] = True
    if not result['is_editable_install']:
        pip_show_cmd = 'pip show fastapi 2>&1'
        pip_show_response = env.controller.run_bash_script(pip_show_cmd, timeout=10)
        if pip_show_response and pip_show_response.get('stdout'):
            pip_show_output = pip_show_response['stdout']
            if 'Location:' in pip_show_output and '/home/user/fastapi' in pip_show_output:
                if 'Editable project location:' in pip_show_output or '/home/user/fastapi' in pip_show_output:
                    result['is_editable_install'] = True
    import_cmd = "python3 -c 'from fastapi import FastAPI' 2>&1"
    import_response = env.controller.run_bash_script(import_cmd, timeout=10)
    if import_response:
        import_output = import_response.get('stdout', '')
        import_error = import_response.get('stderr', '')
        returncode = import_response.get('returncode', -1)
        if returncode == 0:
            result['import_succeeds'] = True
        else:
            result['import_error'] = import_error if import_error else import_output
    return result

def get_srt_subtitle_count__35657f3b1f9ec8ec5c2fa020b95bd99b(env, config: dict):
    """
    Extract and validate SRT subtitle file information.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the SRT file

    Returns:
        dict: Contains 'count', 'file_size', 'has_valid_format', 'sample_content', 'full_text'
    """
    path = config.get('path', '/home/user/subtitles.srt')
    file_bytes = env.controller.get_file(path)
    if file_bytes is None:
        return {'count': 0, 'file_size': 0, 'has_valid_format': False, 'sample_content': '', 'full_text': ''}
    file_size = len(file_bytes)
    with tempfile.NamedTemporaryFile(mode='w+b', suffix='.srt', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        with open(tmp_path, 'r', encoding='utf-8', errors='ignore') as f:
            content = f.read()
        lines = content.split('\n')
        count = 0
        subtitle_texts = []
        i = 0
        while i < len(lines):
            line = lines[i].strip()
            if line.isdigit():
                if i + 1 < len(lines) and '-->' in lines[i + 1]:
                    count += 1
                    text_lines = []
                    j = i + 2
                    while j < len(lines) and lines[j].strip():
                        text_lines.append(lines[j].strip())
                        j += 1
                    if text_lines:
                        subtitle_texts.append(' '.join(text_lines))
            i += 1
        sample_content = ' | '.join(subtitle_texts[:5]) if subtitle_texts else ''
        full_text = ' '.join(subtitle_texts)
        has_valid_format = count > 0 and '-->' in content and (file_size > 100)
        return {'count': count, 'file_size': file_size, 'has_valid_format': has_valid_format, 'sample_content': sample_content, 'full_text': full_text}
    finally:
        os.unlink(tmp_path)

