def get_docx_inline_citations__83c43d6b(env, config: Dict[str, Any]) -> list:
    """Extract all in-text citations from a specific paragraph.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'paragraph_index'

    Returns:
        list: List of citation strings found (e.g., ['Macht and Dettmer (2006)', ...])
    """
    file_path = config.get('path', '')
    paragraph_index = config.get('paragraph_index', 0)
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return []
    import tempfile
    with tempfile.NamedTemporaryFile(delete=False, suffix='.docx') as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        if 0 <= paragraph_index < len(doc.paragraphs):
            text = doc.paragraphs[paragraph_index].text
            citations = []
            pattern1 = re.findall('[A-Z][a-z]+(?:\\s+(?:and|&)\\s+[A-Z][a-z]+)?\\s*\\(\\d{4}\\)', text)
            citations.extend(pattern1)
            pattern2 = re.findall('\\([A-Z][a-z]+(?:\\s+(?:and|&)\\s+[A-Z][a-z]+)?,\\s*\\d{4}\\)', text)
            citations.extend(pattern2)
            return citations
        return []
    finally:
        import os
        os.unlink(tmp_path)

def get_docx_summary_section__4e7505e04651a9c61cfa1ecf50e02a5a(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Extract summary section information from a DOCX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the VM file path

    Returns:
        dict: {'has_summary': bool, 'paper_count': int, 'summary_text': str}
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        logger.error(f"Failed to get file from VM: {config['path']}")
        return {'has_summary': False, 'paper_count': 0, 'summary_text': ''}
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        paper_count = sum((1 for para in doc.paragraphs if para.text.strip().startswith('Title:')))
        has_summary = False
        summary_text = ''
        summary_index = -1
        total_paragraphs = len(doc.paragraphs)
        for i in range(len(doc.paragraphs) - 1, -1, -1):
            text = doc.paragraphs[i].text.strip()
            if 'summary' in text.lower() or 'total' in text.lower():
                has_summary = True
                summary_text = text
                summary_index = i
                break
        is_at_end = False
        if has_summary:
            threshold = max(total_paragraphs - 5, int(total_paragraphs * 0.7))
            is_at_end = summary_index >= threshold
        result = {'has_summary': has_summary and is_at_end, 'paper_count': paper_count, 'summary_text': summary_text, 'summary_index': summary_index, 'total_paragraphs': total_paragraphs, 'is_at_end': is_at_end}
        logger.info(f'Extracted summary info: {result}')
        return result
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

def get_docx_italic_status__b3517b42(env, config: Dict[str, Any]) -> List[bool]:
    """Check if each paragraph has italic formatting applied.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        List of booleans indicating if each paragraph has italic text
    """
    file_path = config.get('path')
    if not file_path:
        return []
    try:
        file_bytes = env.controller.get_file(file_path)
        if not file_bytes:
            return []
        import tempfile
        import os
        with tempfile.NamedTemporaryFile(delete=False, suffix='.docx') as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        try:
            doc = Document(tmp_path)
            italic_statuses = []
            for para in doc.paragraphs:
                if para.text.strip():
                    runs_with_text = [run for run in para.runs if run.text.strip()]
                    if not runs_with_text:
                        has_italic = False
                    else:
                        has_italic = all((run.font.italic is True for run in runs_with_text))
                    italic_statuses.append(has_italic)
            return italic_statuses
        finally:
            os.unlink(tmp_path)
    except Exception as e:
        return []

