def get_min_and_chart__773734fb(env, config):
    """
    Get information about MIN formula in a specific cell and check for pie chart existence.

    This function:
    1. Checks if the specified cell contains a MIN formula
    2. Extracts the actual value in that cell
    3. Checks if a pie chart exists in the worksheet

    Args:
        env: Environment object
        config: Configuration dict with:
            - 'path': path to the Excel file
            - 'sheet': sheet index (default 0)
            - 'cell': cell coordinate to check for MIN formula (e.g., 'G2')

    Returns:
        dict: {
            'has_min_formula': bool,
            'cell_value': float or None,
            'formula': str or None,
            'has_chart': bool,
            'chart_type': str or None (e.g., 'pieChart')
        }
    """
    file_path = config.get('path', '/home/user/BoomerangSales.xlsx')
    sheet_idx = config.get('sheet', 0)
    cell_coord = config.get('cell', 'G2')
    with open(file_path, 'rb') as f:
        file_content = f.read()
    wb = openpyxl.load_workbook(BytesIO(file_content))
    if isinstance(sheet_idx, int):
        sheet = wb.worksheets[sheet_idx]
    else:
        sheet = wb[sheet_idx]
    cell = sheet[cell_coord]
    cell_value = cell.value
    formula = cell.value if isinstance(cell.value, str) and cell.value.startswith('=') else None
    has_min_formula = False
    if formula:
        formula_upper = formula.upper()
        has_min_formula = 'MIN(' in formula_upper
    computed_value = None
    if has_min_formula:
        wb_data = openpyxl.load_workbook(BytesIO(file_content), data_only=True)
        if isinstance(sheet_idx, int):
            sheet_data = wb_data.worksheets[sheet_idx]
        else:
            sheet_data = wb_data[sheet_idx]
        cell_data = sheet_data[cell_coord]
        computed_value = cell_data.value
        try:
            computed_value = float(computed_value) if computed_value is not None else None
        except (ValueError, TypeError):
            computed_value = None
    charts = sheet._charts
    has_chart = len(charts) > 0
    chart_type = None
    has_pie_chart = False
    if charts:
        for chart in charts:
            chart_type = chart.tagname
            if 'pie' in chart_type.lower():
                has_website_reference = False
                try:
                    for series in chart.series:
                        if hasattr(series, 'cat') and series.cat:
                            cat_ref = str(series.cat)
                            if '$B$' in cat_ref or "'Sheet'!$B$" in cat_ref:
                                has_website_reference = True
                                break
                            if 'B2:B' in cat_ref or 'B:B' in cat_ref:
                                has_website_reference = True
                                break
                except (AttributeError, TypeError):
                    pass
                if has_website_reference:
                    has_pie_chart = True
                    break
                elif not has_pie_chart:
                    has_pie_chart = True
                    chart_type = chart.tagname
    return {'has_min_formula': has_min_formula, 'cell_value': computed_value, 'formula': formula, 'has_chart': has_chart, 'has_pie_chart': has_pie_chart, 'chart_type': chart_type}

