def get_cs_max_year__a0de86bd3e0a331a83b39cd8c4fb9536(env, config):
    """Extract all years (2019-2023) data from CS-GRF-Trends.xlsx and identify max year

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: {
            'all_years': {year: {'applications': int, 'supported': int}, ...},
            'max_year': int,
            'max_applications': int,
            'max_supported': int
        }
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return None
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        all_years = {}
        max_apps = 0
        max_year = None
        max_supported = 0
        for row in ws.iter_rows(min_row=2, max_col=3, values_only=True):
            if row[0] and row[1]:
                try:
                    year = int(row[0])
                    apps = int(row[1])
                    supported = int(row[2]) if row[2] else 0
                    all_years[year] = {'applications': apps, 'supported': supported}
                    if apps > max_apps:
                        max_apps = apps
                        max_year = year
                        max_supported = supported
                except (ValueError, TypeError):
                    continue
        return {'all_years': all_years, 'max_year': max_year, 'max_applications': max_apps, 'max_supported': max_supported}
    finally:
        os.unlink(tmp_path)

def get_combined_contact_verification__8f6d6531(env, config: dict):
    """Get both file count and database count for combined verification.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'file_path' and 'db_path' keys

    Returns:
        dict: Dictionary with 'file_count' and 'db_count' keys
    """
    file_path = config.get('file_path', '')
    db_path = config.get('db_path', '')
    file_count = 0
    file_bytes = env.controller.get_file(file_path)
    if file_bytes:
        content = file_bytes.decode('utf-8').strip()
        numbers = re.findall('\\d+', content)
        if numbers:
            file_count = int(numbers[0])
    db_count = 0
    db_bytes = env.controller.get_file(db_path)
    if db_bytes:
        with tempfile.NamedTemporaryFile(mode='wb', delete=False, suffix='.sqlite') as tmp_file:
            tmp_file.write(db_bytes)
            tmp_db_path = tmp_file.name
        try:
            connection = sqlite3.connect(tmp_db_path)
            cursor = connection.cursor()
            cursor.execute('SELECT COUNT(*) FROM moz_cards')
            count = cursor.fetchone()[0]
            connection.close()
            db_count = int(count)
        except Exception as e:
            print(f'Error querying Thunderbird database: {e}')
            db_count = 0
        finally:
            if os.path.exists(tmp_db_path):
                os.remove(tmp_db_path)
    return {'file_count': file_count, 'db_count': db_count}

