def get_docx_text_font_size__8df145e3(env, config):
    """Extract font size for specific text in a DOCX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'dest', and 'search_text'

    Returns:
        float: Font size in points, or -1 if text not found
    """
    vm_path = config.get('path', '/home/user/Desktop/View_Person_Organizational_Summary.docx')
    dest = config.get('dest', 'temp.docx')
    search_text = config.get('search_text', '')
    file_bytes = env.controller.get_file(vm_path)
    if file_bytes is None:
        return -1
    cache_path = os.path.join(env.cache_dir, dest)
    with open(cache_path, 'wb') as f:
        f.write(file_bytes)
    doc = Document(cache_path)
    for paragraph in doc.paragraphs:
        for run in paragraph.runs:
            if search_text.lower() in run.text.lower():
                if run.font.size:
                    return float(run.font.size.pt)
                else:
                    return 11.0
    return -1

