def get_odt_word_italic_status__0c0e499fa9cb3914f3c0c212ceead5ed(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract italic formatting status for specific words in ODT file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'target_word'

    Returns:
        Dict with word instances and their italic status
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'instances': [], 'all_italic': False, 'count': 0}
    with tempfile.NamedTemporaryFile(suffix='.odt', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = load(tmp_path)
        target_word = config.get('target_word', '')
        word_instances = []
        word_pattern = re.compile('\\b' + re.escape(target_word) + '\\b', re.IGNORECASE)
        for para in doc.getElementsByType(P):
            para_text = teletype.extractText(para)
            matches = list(word_pattern.finditer(para_text))
            if not matches:
                continue
            for match in matches:
                match_start = match.start()
                match_end = match.end()
                matched_text = match.group()
                is_italic = False
                current_pos = 0
                found_element = None

                def traverse_nodes(node):
                    """Recursively traverse text nodes to find match position."""
                    nonlocal current_pos, found_element
                    if found_element:
                        return
                    if hasattr(node, 'data') and isinstance(node.data, str):
                        text_content = node.data
                        node_start = current_pos
                        node_end = current_pos + len(text_content)
                        if node_start <= match_start < node_end:
                            found_element = ('text_node', None)
                        current_pos = node_end
                    elif hasattr(node, 'childNodes'):
                        if node.qname == (u'urn:oasis:names:tc:opendocument:xmlns:text:1.0', u'span'):
                            span_text = teletype.extractText(node)
                            node_start = current_pos
                            node_end = current_pos + len(span_text)
                            if node_start <= match_start < node_end:
                                found_element = ('span', node)
                            current_pos = node_end
                        else:
                            for child in node.childNodes:
                                traverse_nodes(child)
                traverse_nodes(para)
                if found_element:
                    (element_type, element) = found_element
                    if element_type == 'span' and element is not None:
                        is_italic = _check_italic_formatting(element, doc)
                    else:
                        is_italic = False
                word_instances.append({'text': matched_text, 'is_italic': is_italic})
        all_italic = len(word_instances) > 0 and all((inst['is_italic'] for inst in word_instances))
        return {'instances': word_instances, 'all_italic': all_italic, 'count': len(word_instances)}
    finally:
        os.unlink(tmp_path)

