def get_password_manager_disabled__f026813c7c7451bc8affe295513022af(env, config: Dict[str, str]):
    """
    Check if password manager (offer to save passwords) is disabled in Chrome.
    Returns "true" if password saving is disabled, "false" if enabled.
    """
    os_type = env.vm_platform
    if os_type == 'Windows':
        preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('LOCALAPPDATA'),\n                                            'Google\\Chrome\\User Data\\Default\\Preferences'))")['output'].strip()
    elif os_type == 'Darwin':
        preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), 'Library/Application Support/Google/Chrome/Default/Preferences'))")['output'].strip()
    elif os_type == 'Linux':
        if 'arm' in platform.machine():
            preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), 'snap/chromium/common/chromium/Default/Preferences'))")['output'].strip()
        else:
            preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), '.config/google-chrome/Default/Preferences'))")['output'].strip()
    else:
        raise Exception('Unsupported operating system')
    try:
        content = env.controller.get_file(preference_file_path)
        data = json.loads(content)
        password_manager_enabled = data.get('profile', {}).get('password_manager_enabled', True)
        if 'credentials_enable_service' in data:
            credentials_enabled = data.get('credentials_enable_service', True)
            return 'true' if not credentials_enabled else 'false'
        return 'true' if not password_manager_enabled else 'false'
    except Exception as e:
        logger.error(f'Error checking password manager setting: {e}')
        return 'false'

def get_docx_word_count__0ed3fac7(env, config):
    """Get word count and content from a docx file for validation.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: Dictionary containing:
            - word_count: Number of words in the document
            - content: Full text content of the document
            - file_exists: Whether the file exists at the specified path
            - filename: Name of the file
    """
    file_path = config.get('path')
    if not file_path:
        return {'word_count': 0, 'content': '', 'file_exists': False, 'filename': ''}
    try:
        file_bytes = env.controller.get_file(file_path)
        if not file_bytes:
            return {'word_count': 0, 'content': '', 'file_exists': False, 'filename': os.path.basename(file_path) if file_path else ''}
        import tempfile
        with tempfile.NamedTemporaryFile(delete=False, suffix='.docx') as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        try:
            doc = Document(tmp_path)
            word_count = 0
            content_lines = []
            for paragraph in doc.paragraphs:
                text = paragraph.text.strip()
                if text:
                    content_lines.append(text)
                    word_count += len(text.split())
            full_content = ' '.join(content_lines)
            return {'word_count': word_count, 'content': full_content, 'file_exists': True, 'filename': os.path.basename(file_path)}
        finally:
            os.unlink(tmp_path)
    except Exception as e:
        print(f'Error getting word count: {e}')
        return {'word_count': 0, 'content': '', 'file_exists': False, 'filename': os.path.basename(file_path) if file_path else ''}

def get_docx_word_count__78c2239d(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Get word count and text content from a DOCX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: {'word_count': int, 'text': str, 'path': str}
    """
    from docx import Document
    from io import BytesIO
    path = config['path']
    file_bytes = env.controller.get_file(path)
    if not file_bytes:
        logger.error(f'Could not retrieve file: {path}')
        return {'word_count': 0, 'text': '', 'path': path}
    try:
        doc = Document(BytesIO(file_bytes))
        paragraphs_text = [p.text for p in doc.paragraphs if p.text.strip()]
        text = ' '.join(paragraphs_text)
        for table in doc.tables:
            for row in table.rows:
                for cell in row.cells:
                    if cell.text.strip():
                        text += ' ' + cell.text
        text = ' '.join(text.split())
        word_count = len(text.split())
        logger.info(f'Word count: {word_count}, text length: {len(text)} chars')
        return {'word_count': word_count, 'text': text, 'path': path}
    except Exception as e:
        logger.error(f'Error reading DOCX file: {e}')
        return {'word_count': 0, 'text': '', 'path': path}

