def get_writer_default_font_size__ebf969c2(env, config: Dict[str, Any]):
    """Extract the default font size for LibreOffice Writer.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' to registrymodifications.xcu file

    Returns:
        str: The default font size or None if not found
    """
    from desktop_env.evaluators.getters.file import get_vm_file
    config_file_path = get_vm_file(env, config)
    if not config_file_path:
        logger.error('Failed to get config file')
        return None
    try:
        tree = ET.parse(config_file_path)
        root = tree.getroot()
        namespace = {'oor': 'http://openoffice.org/2001/registry'}
        for elem in root.findall('.//item[@oor:path="/org.openoffice.Office.Writer/DefaultFont"]', namespace):
            for prop in elem.findall('.//prop[@oor:name="StandardHeight"]', namespace):
                for value in prop.findall('value', namespace):
                    return value.text
        logger.warning('Default font size not found in config')
        return None
    except Exception as e:
        logger.error(f'Error parsing config file: {e}')
        return None

def get_docx_titlecase_info__c94a695d(env, config):
    """Extract text to check for title case formatting.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: Information about text case
    """
    vm_path = config.get('path', '/home/user/Desktop/presentation_instruction_2023_Feb.docx')
    file_bytes = env.controller.get_file(vm_path)
    if not file_bytes:
        return {'all_text_runs': []}
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(delete=False, suffix='.docx') as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        text_runs = []
        for para in doc.paragraphs:
            for run in para.runs:
                text = run.text.strip()
                if text and len(text) > 1:
                    text_runs.append(text)
        for table in doc.tables:
            for row in table.rows:
                for cell in row.cells:
                    for para in cell.paragraphs:
                        for run in para.runs:
                            text = run.text.strip()
                            if text and len(text) > 1:
                                text_runs.append(text)
        return {'all_text_runs': text_runs}
    finally:
        os.unlink(tmp_path)

