def get_docx_paragraph_count__807a7693(env, config: Dict[str, Any]) -> int:
    """
    Count the number of non-empty paragraphs in a .docx file.

    Args:
        env: Environment object with controller for file access
        config: Configuration dict containing:
            - path: str - Path to the .docx file

    Returns:
        int: Number of non-empty paragraphs in the document
    """
    docx_path = config.get('path')
    if not docx_path:
        logger.error('[DOCX_PARAGRAPH_COUNT] No path specified in config')
        return 0
    logger.info(f'[DOCX_PARAGRAPH_COUNT] Counting paragraphs in: {docx_path}')
    try:
        file_content = env.controller.get_file(docx_path)
        if not file_content:
            logger.error(f'[DOCX_PARAGRAPH_COUNT] Failed to read file: {docx_path}')
            return 0
        import os
        temp_dir = env.cache_dir
        temp_docx_path = os.path.join(temp_dir, 'temp_paragraph_count.docx')
        with open(temp_docx_path, 'wb') as f:
            f.write(file_content)
        logger.info(f'[DOCX_PARAGRAPH_COUNT] Saved temporary file: {temp_docx_path}')
        namespace = {'w': 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
        paragraph_count = 0
        with zipfile.ZipFile(temp_docx_path, 'r') as docx:
            xml_content = docx.read('word/document.xml')
            tree = ET.XML(xml_content)
            for paragraph in tree.findall('.//w:p', namespace):
                texts = []
                for text_elem in paragraph.findall('.//w:t', namespace):
                    if text_elem.text:
                        texts.append(text_elem.text)
                if texts:
                    para_text = ''.join(texts).strip()
                    if para_text:
                        paragraph_count += 1
        try:
            os.remove(temp_docx_path)
        except:
            pass
        logger.info(f'[DOCX_PARAGRAPH_COUNT] Found {paragraph_count} non-empty paragraphs')
        return paragraph_count
    except Exception as e:
        logger.error(f'[DOCX_PARAGRAPH_COUNT] Error counting paragraphs: {e}')
        logger.error(f'[DOCX_PARAGRAPH_COUNT] Exception type: {type(e).__name__}')
        return 0

