def get_vm_file(env, config: Dict[str, Any]):
    """Get file from VM - simplified version for this getter."""
    path = config['path']
    dest = config.get('dest', os.path.basename(path))
    try:
        file_content = env.controller.get_file(path)
        if file_content is None:
            logger.warning(f'Failed to get file from VM: {path}')
            return None
        cache_path = os.path.join(env.cache_dir, dest)
        os.makedirs(env.cache_dir, exist_ok=True)
        with open(cache_path, 'wb') as f:
            f.write(file_content)
        return cache_path
    except Exception as e:
        logger.error(f'Error getting file {path}: {e}')
        return None

def get_docx_font_props__f376f0fd(env, config: dict) -> Dict[str, Any]:
    """Get font properties and content verification of merged document.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'dest' keys

    Returns:
        Dict with font properties, content verification, and merge verification results
    """
    from docx import Document
    from collections import Counter
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'font_name': None, 'font_size': None, 'has_content': False, 'total_runs': 0, 'arial_runs': 0, 'size_11_runs': 0, 'document_text': '', 'merge_verified': False, 'source_files_count': 0, 'merged_content_count': 0}
    temp_path = f"/tmp/{config['dest']}"
    with open(temp_path, 'wb') as f:
        f.write(file_bytes)
    try:
        doc = Document(temp_path)
        font_names = []
        font_sizes = []
        all_text = []
        total_runs = 0
        arial_runs = 0
        size_11_runs = 0
        for para in doc.paragraphs:
            for run in para.runs:
                total_runs += 1
                text = run.text.strip()
                if text:
                    all_text.append(text)
                if run.font.name:
                    font_names.append(run.font.name)
                    if run.font.name.lower() == 'arial':
                        arial_runs += 1
                if run.font.size:
                    size_pt = run.font.size.pt
                    font_sizes.append(size_pt)
                    if abs(size_pt - 11.0) < 0.5:
                        size_11_runs += 1
        most_common_font = None
        if font_names:
            font_counter = Counter(font_names)
            most_common_font = font_counter.most_common(1)[0][0]
        most_common_size = None
        if font_sizes:
            size_counter = Counter(font_sizes)
            most_common_size = size_counter.most_common(1)[0][0]
        document_text = '\n'.join(all_text)
        has_content = len(document_text.strip()) > 0
        merge_verified = False
        source_files_count = 0
        merged_content_count = 0
        source_dir = '/home/user/Desktop/doc_proc'
        try:
            source_dir_bytes = env.controller.execute_bash_command(f"find {source_dir} -name '*.txt' -type f")
            if source_dir_bytes:
                source_files = source_dir_bytes.decode('utf-8').strip().split('\n')
                source_files = [f for f in source_files if f]
                source_files_count = len(source_files)
                for source_file in source_files:
                    try:
                        file_content_bytes = env.controller.get_file(source_file)
                        if file_content_bytes:
                            file_content = file_content_bytes.decode('utf-8', errors='ignore').strip()
                            if file_content:
                                signature = file_content[:100] if len(file_content) > 100 else file_content
                                first_line = file_content.split('\n')[0].strip()
                                if signature in document_text or first_line in document_text:
                                    merged_content_count += 1
                    except Exception:
                        pass
                if source_files_count > 0:
                    merge_verified = merged_content_count >= source_files_count * 0.8
        except Exception:
            pass
        return {'font_name': most_common_font, 'font_size': most_common_size, 'has_content': has_content, 'total_runs': total_runs, 'arial_runs': arial_runs, 'size_11_runs': size_11_runs, 'document_text': document_text, 'merge_verified': merge_verified, 'source_files_count': source_files_count, 'merged_content_count': merged_content_count}
    finally:
        if os.path.exists(temp_path):
            os.remove(temp_path)

def get_docx_paragraph_count__851dfebf(env, config: dict):
    """Count non-empty paragraphs in a docx file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'dest' parameters

    Returns:
        dict: Contains paragraph_count
    """
    try:
        file_bytes = env.controller.get_file(config['path'])
        if not file_bytes:
            return None
        import os
        cache_path = os.path.join(env.cache_dir, config['dest'])
        os.makedirs(os.path.dirname(cache_path), exist_ok=True)
        with open(cache_path, 'wb') as f:
            f.write(file_bytes)
        doc = Document(cache_path)
        paragraph_count = sum((1 for para in doc.paragraphs if para.text.strip()))
        result = {'paragraph_count': paragraph_count}
        logger.info(f'Paragraph count: {result}')
        return result
    except Exception as e:
        logger.error(f'Error counting paragraphs: {e}')
        return None

def get_docx_first_para_bold__dc18eefc8b3e67fb89d1187d2c823901(env, config: Dict[str, Any]) -> bool:
    """Check if the first paragraph (title) is bold.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        bool: True if first paragraph is bold, False otherwise
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return False
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        if len(doc.paragraphs) == 0:
            return False
        first_para = doc.paragraphs[0]
        if len(first_para.runs) == 0:
            return False
        for run in first_para.runs:
            if not run.bold:
                return False
        return True
    except Exception as e:
        print(f'Error reading docx: {e}')
        return False
    finally:
        os.unlink(tmp_path)

