def get_docx_page_count__6a1b8297(env, config: dict):
    """Extract page count from a docx file.

    Note: Page count in DOCX files is approximate as the actual page count
    depends on rendering (margins, fonts, etc.). We detect explicit page breaks
    and section breaks to count pages.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with parameters:
            - path: VM path to the docx file

    Returns:
        int: Estimated page count in the document (counts explicit page breaks)
    """
    try:
        vm_path = config.get('path', '/home/user/Desktop/View_Person_Organizational_Summary.docx')
        file_bytes = env.controller.get_file(vm_path)
        if not file_bytes:
            logger.error(f'Failed to get file from VM: {vm_path}')
            return 0
        import tempfile
        import os
        with tempfile.NamedTemporaryFile(delete=False, suffix='.docx') as tmp_file:
            tmp_file.write(file_bytes)
            tmp_path = tmp_file.name
        try:
            doc = Document(tmp_path)
            page_count = 1
            for paragraph in doc.paragraphs:
                page_breaks = paragraph._element.xpath('.//w:br[@w:type="page"]')
                page_count += len(page_breaks)
            section_count = len(doc.sections)
            if section_count > 1:
                page_count = max(page_count, section_count)
            logger.info(f'Detected page count: {page_count} (based on {page_count - 1} explicit page breaks and {section_count} sections)')
            return page_count
        finally:
            os.unlink(tmp_path)
    except Exception as e:
        logger.error(f'Error counting pages in docx: {e}')
        return 0

def get_paragraph_alignment__e080f058717771903c4f724d44da312c(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Extract alignment information for specific paragraph(s) in the document.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the docx file

    Returns:
        Dict containing:
        - first_para_alignment: alignment of first non-empty paragraph
        - alignments: list of alignments for all non-empty paragraphs
    """
    file_path = config.get('path', '')
    if not file_path:
        return {'first_para_alignment': None, 'alignments': []}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'first_para_alignment': None, 'alignments': []}
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        alignments = []
        first_alignment = None
        for para in doc.paragraphs:
            if para.text.strip():
                alignment = para.paragraph_format.alignment
                if first_alignment is None:
                    first_alignment = alignment
                alignments.append(alignment)
        return {'first_para_alignment': first_alignment, 'alignments': alignments}
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

