def get_srt_format_valid__cc7ce7a704603cef84fe46b9a63a12a3(env, config: dict):
    """
    Check if SRT file has valid format (timestamps, sequence numbers, text entries).

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the SRT file

    Returns:
        dict: {'valid_format': bool, 'has_timestamps': bool, 'has_sequence': bool, 'has_text_entries': bool}
    """
    path = config.get('path', '/home/user/subtitles.srt')
    file_bytes = env.controller.get_file(path)
    if file_bytes is None:
        return {'valid_format': False, 'has_timestamps': False, 'has_sequence': False, 'has_text_entries': False}
    with tempfile.NamedTemporaryFile(mode='w+b', suffix='.srt', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        with open(tmp_path, 'r', encoding='utf-8', errors='ignore') as f:
            content = f.read()
        timestamp_pattern = '\\d{2}:\\d{2}:\\d{2},\\d{3}\\s*-->\\s*\\d{2}:\\d{2}:\\d{2},\\d{3}'
        has_timestamps = bool(re.search(timestamp_pattern, content))
        lines = content.split('\n')
        has_sequence = False
        for line in lines:
            if line.strip().isdigit():
                has_sequence = True
                break
        has_text_entries = False
        srt_entries = content.strip().split('\n\n')
        for entry in srt_entries:
            entry_lines = entry.strip().split('\n')
            if len(entry_lines) >= 3:
                first_line = entry_lines[0].strip()
                second_line = entry_lines[1].strip()
                if first_line.isdigit():
                    if re.match(timestamp_pattern, second_line):
                        for i in range(2, len(entry_lines)):
                            if entry_lines[i].strip():
                                has_text_entries = True
                                break
                if has_text_entries:
                    break
        valid_format = has_timestamps and has_sequence and has_text_entries
        return {'valid_format': valid_format, 'has_timestamps': has_timestamps, 'has_sequence': has_sequence, 'has_text_entries': has_text_entries}
    finally:
        os.unlink(tmp_path)

