def get_docx_bold__1e11b8812f21045043113b8b0bfd681f(env, config):
    """Extract bold formatting information for specific paragraphs.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: Mapping of paragraph indices to boolean indicating if all text is bold
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        bold_status = {}
        content_idx = 0
        for (para_idx, para) in enumerate(doc.paragraphs):
            if para.text.strip():
                content_idx += 1
                if len(para.runs) > 0:
                    all_bold = all((run.bold for run in para.runs if run.text.strip()))
                    bold_status[content_idx] = all_bold
                else:
                    bold_status[content_idx] = False
        return bold_status
    finally:
        os.unlink(tmp_path)

