def get_docx_para_underline__f11d1f2c(env, config: dict) -> Optional[bool]:
    """Check if specific text 'CHIN9505' is underlined in the document.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'paragraph_index'

    Returns:
        True if all runs containing 'CHIN9505' are underlined, False otherwise, None if not found
    """
    file_path = config.get('path')
    target_text = 'CHIN9505'
    if not file_path:
        return None
    try:
        doc = Document(file_path)
        for para in doc.paragraphs:
            para_text = para.text
            if target_text in para_text:
                found_target = False
                all_target_runs_underlined = True
                for run in para.runs:
                    if target_text in run.text:
                        found_target = True
                        if not run.underline:
                            all_target_runs_underlined = False
                            break
                if found_target:
                    return all_target_runs_underlined
                current_pos = 0
                run_positions = []
                for run in para.runs:
                    run_text = run.text
                    run_start = current_pos
                    run_end = current_pos + len(run_text)
                    run_positions.append((run_start, run_end, run))
                    current_pos = run_end
                target_start = para_text.find(target_text)
                if target_start != -1:
                    target_end = target_start + len(target_text)
                    found_target = False
                    all_target_runs_underlined = True
                    for (run_start, run_end, run) in run_positions:
                        if run_start < target_end and run_end > target_start:
                            found_target = True
                            if not run.underline:
                                all_target_runs_underlined = False
                                break
                    if found_target:
                        return all_target_runs_underlined
        return None
    except Exception as e:
        return None

