def get_italic_terms__75cc2eac1024bd136a0d9e32696fbcbc(env, config):
    """Extract information about italic formatting for specific terms.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'target_word' keys

    Returns:
        dict: Information about italic occurrences
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'italic_count': 0, 'total_count': 0}
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        target_word = config.get('target_word', 'flavanols')
        italic_count = 0
        total_count = 0
        for para in doc.paragraphs:
            for run in para.runs:
                if target_word.lower() in run.text.lower():
                    occurrences = run.text.lower().count(target_word.lower())
                    total_count += occurrences
                    if run.italic:
                        italic_count += occurrences
        return {'italic_count': italic_count, 'total_count': total_count}
    finally:
        os.unlink(tmp_path)

