def get_cs_rate_comparison__49466292d6c0f075e7fe40fde708d1b6(env, config):
    """Extract success rates and identify lowest year from CS-GRF-Comparison.xlsx

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: {'rates': {year: rate}, 'lowest_year': year, 'lowest_rate': rate}
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return None
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        rates = {}
        min_rate = float('inf')
        min_year = None
        for row in ws.iter_rows(min_row=2, max_col=4, values_only=True):
            if row[0] and row[3] is not None:
                try:
                    year = int(row[0])
                    rate = float(row[3])
                    if 2019 <= year <= 2023:
                        rates[year] = rate
                        if rate < min_rate:
                            min_rate = rate
                            min_year = year
                except (ValueError, TypeError):
                    continue
        if rates and min_year:
            return {'rates': rates, 'lowest_year': min_year, 'lowest_rate': min_rate}
        return None
    finally:
        os.unlink(tmp_path)

def get_docx_indent__69f3b37e(vm_file_path, config: dict):
    """Extract paragraph indentation information from DOCX file.

    This getter processes the vm_file by reading the DOCX file at vm_file_path,
    analyzing paragraph formatting, and extracting detailed indentation data.
    The result is then passed to the metric for comparison.

    Framework design: This getter reads vm_file_path (downloaded DOCX) and returns
    processed data (dict with indented and non-indented indices) to the metric function.

    Args:
        vm_file_path: Local path to the downloaded DOCX file (vm_file result type)
        config: Configuration dict

    Returns:
        Dict with:
            - 'indented_paragraphs': List[int] of paragraph indices with correct indent (0.45-0.55 inches)
            - 'all_indented': List[int] of all paragraphs with any significant indent (>= 0.2 inches)
    """
    if not vm_file_path:
        return {'indented_paragraphs': [], 'all_indented': []}
    try:
        from docx.shared import Inches
        doc = Document(vm_file_path)
        correctly_indented = []
        all_indented = []
        for (i, para) in enumerate(doc.paragraphs):
            if para.paragraph_format.left_indent:
                indent_inches = para.paragraph_format.left_indent.inches
                if 0.45 <= indent_inches <= 0.55:
                    correctly_indented.append(i)
                if indent_inches >= 0.2:
                    all_indented.append(i)
        return {'indented_paragraphs': correctly_indented, 'all_indented': all_indented}
    except Exception:
        return {'indented_paragraphs': [], 'all_indented': []}

def get_default_text_editor__889dc22fd159a46b29eaff6ff2d70479(env, config: dict):
    """Gets the default text editor application.

    Args:
        env: DesktopEnv instance
        config: Configuration dict (not used but required by framework)

    Returns:
        str: The default text editor .desktop file name (e.g., 'gedit.desktop')
    """
    import requests
    os_type = env.vm_platform
    if os_type == 'Linux':
        mime_types = ['text/plain', 'text/x-log', 'text/x-readme']
        apps = []
        vm_ip = env.vm_ip
        port = env.server_port
        for mime_type in mime_types:
            command = ['xdg-mime', 'query', 'default', mime_type]
            response = requests.post(f'http://{vm_ip}:{port}/execute', json={'command': command, 'shell': False})
            if response.status_code == 200:
                app = response.json().get('output', '').strip()
                if app:
                    apps.append(app)
        if len(apps) == 0:
            return 'unknown'
        else:
            return Counter(apps).most_common(1)[0][0]
    else:
        raise Exception('Unsupported operating system', os_type)

