def get_docx_fontsize__12091044930a41211a2e74faf0d6730b(env, config):
    """Extract font size information for specific paragraphs.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: Mapping of paragraph indices to font size in points
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        font_sizes = {}
        content_idx = 0
        for (para_idx, para) in enumerate(doc.paragraphs):
            if para.text.strip():
                content_idx += 1
                sizes = []
                for run in para.runs:
                    if run.text.strip() and run.font.size:
                        sizes.append(run.font.size.pt)
                if sizes:
                    font_sizes[content_idx] = sizes[0]
                else:
                    font_sizes[content_idx] = None
        return font_sizes
    finally:
        os.unlink(tmp_path)

def get_m3u_playlist_entries__fc0503218737b45d736109a0a7f08ce1(env, config: dict):
    """Read .m3u playlist file and extract MP3 entries.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        list: List of MP3 file paths found in playlist
    """
    file_path = config.get('path', '')
    if not file_path:
        logger.warning('No file path provided')
        return []
    try:
        file_bytes = env.controller.get_file(file_path)
        if not file_bytes:
            logger.warning(f'Playlist file not found: {file_path}')
            return []
        content = file_bytes.decode('utf-8')
        lines = content.strip().split('\n')
        mp3_entries = []
        for line in lines:
            line = line.strip()
            if line and (not line.startswith('#')) and line.endswith('.mp3'):
                mp3_entries.append(line)
        logger.debug(f'Found {len(mp3_entries)} MP3 entries in playlist: {mp3_entries}')
        return mp3_entries
    except Exception as e:
        logger.error(f'Error reading playlist {file_path}: {e}')
        return []

def get_docx_para_underline_font__04f89cb9530131b0072d02e14f11a259(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract underline status and font name from a specific paragraph in a .docx file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM file path) and 'para_index' (0-based paragraph index)

    Returns:
        Dict with keys:
        - 'all_underlined': bool - whether all runs in the paragraph are underlined
        - 'font_name': str - the font name if all runs have the same font, None if fonts are mixed or paragraph is empty
        - 'error': str - error message if any
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'all_underlined': False, 'font_name': None, 'error': 'File not found'}
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        para_index = config.get('para_index', 0)
        if para_index >= len(doc.paragraphs):
            return {'all_underlined': False, 'font_name': None, 'error': f'Paragraph index {para_index} out of range'}
        para = doc.paragraphs[para_index]
        runs = [r for r in para.runs if r.text.strip()]
        if not runs:
            return {'all_underlined': False, 'font_name': None, 'error': 'No text runs in paragraph'}
        all_underlined = all((r.font.underline for r in runs))
        font_name = runs[0].font.name if runs else None
        all_same_font = all((r.font.name == font_name for r in runs)) if runs else False
        if not all_same_font:
            font_name = None
        return {'all_underlined': all_underlined, 'font_name': font_name, 'error': None}
    except Exception as e:
        return {'all_underlined': False, 'font_name': None, 'error': str(e)}
    finally:
        os.unlink(tmp_path)

def get_docx_most_frequent_computer__ebf9ee9c1f1b016943d5a9bfb251b119(env, config):
    """Extract the text written at the end of the docx file by the user.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with parameters (e.g., {'path': '/home/user/file.docx'})

    Returns:
        str: The text found at the end of the document (cleaned and stripped)
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return ''
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        non_empty_paragraphs = [para.text.strip() for para in doc.paragraphs if para.text.strip()]
        if not non_empty_paragraphs:
            return ''
        last_text = non_empty_paragraphs[-1]
        import re
        numbers = re.findall('\\b\\d+\\b', last_text)
        if numbers:
            return numbers[0]
        return last_text
    except Exception as e:
        logger.error(f'Error processing docx file: {e}')
        return ''
    finally:
        os.unlink(tmp_path)

