                for cell in row.cells:
                    for para in cell.paragraphs:
                        for run in para.runs:
                            text = run.text
                            if text and text.isupper() and (len(text.strip()) > 0):
                                uppercase_runs.append(text)
                                if run.bold:
                                    bold_uppercase_runs.append(text)
