def get_invoice_quantity_sum__3ae73d48883e179c149bcb7c19ff6986(env, config: dict) -> Optional[Dict[str, Any]]:
    """Extract complete invoice data structure from Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict containing invoice data structure with items, quantities, headers, and sum,
        or None if not found
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return None
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        headers = []
        if ws.max_row >= 1:
            first_row = list(ws.iter_rows(min_row=1, max_row=1))[0]
            headers = [cell.value for cell in first_row if cell.value is not None]
        items = []
        quantity_sum = 0
        for row in ws.iter_rows(min_row=2, max_row=ws.max_row):
            item_name = row[0].value
            if item_name is None:
                continue
            if str(item_name).strip().lower() == 'total':
                break
            quantity = row[1].value
            if quantity is not None:
                items.append({'item_name': str(item_name).strip(), 'quantity': int(quantity)})
                quantity_sum += int(quantity)
        return {'headers': headers, 'items': items, 'item_count': len(items), 'quantity_sum': quantity_sum}
    finally:
        os.unlink(tmp_path)

def get_docx_underline__bfde1b03(env, config: dict) -> Dict[str, Any]:
    """Get underline status, font size of first paragraph, and document content.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'dest' keys

    Returns:
        Dict with 'is_underline', 'font_size', 'all_underlined', 'all_correct_size',
        'content', 'word_count', and 'paragraph_count' keys
    """
    import os
    from docx import Document
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'is_underline': False, 'font_size': None, 'all_underlined': False, 'all_correct_size': False, 'content': '', 'word_count': 0, 'paragraph_count': 0}
    temp_path = f"/tmp/{config['dest']}"
    with open(temp_path, 'wb') as f:
        f.write(file_bytes)
    try:
        doc = Document(temp_path)
        if len(doc.paragraphs) == 0:
            return {'is_underline': False, 'font_size': None, 'all_underlined': False, 'all_correct_size': False, 'content': '', 'word_count': 0, 'paragraph_count': 0}
        first_para = doc.paragraphs[0]
        if len(first_para.runs) == 0:
            return {'is_underline': False, 'font_size': None, 'all_underlined': False, 'all_correct_size': False, 'content': '', 'word_count': 0, 'paragraph_count': 0}
        all_underlined = True
        all_correct_size = True
        expected_size = 12.0
        for run in first_para.runs:
            if not run.text.strip():
                continue
            run_underline = run.underline if run.underline is not None else False
            if not run_underline:
                all_underlined = False
            if run.font.size:
                run_size = run.font.size.pt
                if abs(run_size - expected_size) >= 0.5:
                    all_correct_size = False
            else:
                all_correct_size = False
        first_run = first_para.runs[0]
        is_underline = first_run.underline if first_run.underline is not None else False
        font_size = None
        if first_run.font.size:
            font_size = first_run.font.size.pt
        full_content = '\n'.join([para.text for para in doc.paragraphs])
        word_count = len(full_content.split())
        paragraph_count = len([p for p in doc.paragraphs if p.text.strip()])
        return {'is_underline': is_underline, 'font_size': font_size, 'all_underlined': all_underlined, 'all_correct_size': all_correct_size, 'content': full_content, 'word_count': word_count, 'paragraph_count': paragraph_count}
    finally:
        if os.path.exists(temp_path):
            os.remove(temp_path)

