def get_docx_para_font_size__69243b4a6741565a05acda769123bbd1(env, config: dict):
    """Extract font size information for a specific paragraph.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'paragraph_index' keys

    Returns:
        dict: Information about font sizes in the paragraph
    """
    file_path = config.get('path')
    if not file_path:
        return {}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        target_para_idx = config.get('paragraph_index', 0)
        if target_para_idx >= len(doc.paragraphs):
            return {'all_target_size': False}
        para = doc.paragraphs[target_para_idx]
        target_size = config.get('target_size', 16)
        if not para.runs:
            return {'all_target_size': False}
        font_sizes = []
        for run in para.runs:
            if run.text.strip():
                if run.font.size is not None:
                    font_sizes.append(run.font.size.pt)
                else:
                    font_sizes.append(None)
        all_target_size = all((size is not None and size == target_size for size in font_sizes))
        return {'all_target_size': all_target_size, 'font_sizes': font_sizes, 'target_size': target_size}
    finally:
        os.unlink(tmp_path)

def get_docx_font_size_third_para__bb7c00a491c6ff21c93d4fdd14e8e8b6(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract font size from the third paragraph of a DOCX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the DOCX file

    Returns:
        Dict with 'font_size' in points (float) - average of all run font sizes
    """
    file_path = config.get('path', '')
    if not file_path:
        logger.error('No file path provided in config')
        return {'font_size': None}
    try:
        file_bytes = env.controller.get_file(file_path)
        if not file_bytes:
            logger.error(f'Failed to retrieve file: {file_path}')
            return {'font_size': None}
        with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        try:
            doc = Document(tmp_path)
            non_empty_paras = [para for para in doc.paragraphs if para.text.strip()]
            if len(non_empty_paras) < 3:
                logger.warning('Less than 3 non-empty paragraphs found')
                return {'font_size': None}
            third_para = non_empty_paras[2]
            if not third_para.runs:
                logger.warning('Third paragraph has no runs')
                return {'font_size': None}
            font_sizes = []
            for run in third_para.runs:
                if run.text.strip() and run.font.size:
                    font_sizes.append(run.font.size.pt)
            if not font_sizes:
                logger.warning('No font sizes found in third paragraph')
                return {'font_size': None}
            if len(set(font_sizes)) == 1:
                font_size = font_sizes[0]
            else:
                font_size = max(set(font_sizes), key=font_sizes.count)
            logger.info(f'Third paragraph font size: {font_size}')
            return {'font_size': font_size}
        finally:
            os.unlink(tmp_path)
    except Exception as e:
        logger.error(f'Error processing DOCX file: {e}')
        return {'font_size': None}

