def get_top_half_match__2a0763f4(env, config):
    """
    Check if the result image matches the top half of the source image.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - 'result_path': Path to the result image
            - 'source_path': Path to the source image (in cache)

    Returns:
        dict: {'matches': bool, 'similarity': float} or None on error
    """
    try:
        result_path_vm = config.get('result_path', '/home/user/Desktop/tophalf.png')
        source_path = config.get('source_path', 'tilearray.png')
        result_content = env.controller.get_file(result_path_vm)
        if not result_content:
            logger.error(f'Failed to get result image: {result_path_vm}')
            return None
        local_result = os.path.join(env.cache_dir, 'temp_result.png')
        with open(local_result, 'wb') as f:
            f.write(result_content)
        local_source = os.path.join(env.cache_dir, source_path)
        if not os.path.exists(local_source):
            logger.error(f'Source image not found: {local_source}')
            return None
        result_img = Image.open(local_result)
        source_img = Image.open(local_source)
        (source_width, source_height) = source_img.size
        top_half = source_img.crop((0, 0, source_width, source_height // 2))
        if result_img.size != top_half.size:
            logger.warning(f'Size mismatch: result {result_img.size} vs top half {top_half.size}')
            return {'matches': False, 'similarity': 0.0}
        if result_img.mode != 'RGB':
            result_img = result_img.convert('RGB')
        if top_half.mode != 'RGB':
            top_half = top_half.convert('RGB')
        result_array = np.array(result_img)
        top_array = np.array(top_half)
        min_dim = min(result_array.shape[0], result_array.shape[1])
        win_size = min(7, min_dim if min_dim % 2 == 1 else min_dim - 1)
        try:
            similarity = ssim(result_array, top_array, win_size=win_size, channel_axis=2)
        except TypeError:
            similarity = ssim(result_array, top_array, win_size=win_size, multichannel=True)
        matches = similarity >= 0.95
        logger.info(f'Top half match: {matches}, similarity: {similarity}')
        return {'matches': matches, 'similarity': similarity}
    except Exception as e:
        logger.error(f'Error checking top half: {e}')
        import traceback
        logger.error(traceback.format_exc())
        return None

