def get_ext_info__9baceeed6f794b327257ca3ebfd3fa75(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Get extension names, paths, enabled state, and developer mode status from Chrome Preferences.

    Args:
        env: Desktop environment instance
        config: Configuration dict

    Returns:
        Dict with 'names', 'paths', 'enabled_states', and 'dev_mode_states' keys containing lists of extension info
    """
    os_type = env.vm_platform
    if os_type == 'Windows':
        preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('LOCALAPPDATA'), 'Google\\Chrome\\User Data\\Default\\Preferences'))")['output'].strip()
    elif os_type == 'Darwin':
        preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), 'Library/Application Support/Google/Chrome/Default/Preferences'))")['output'].strip()
    elif os_type == 'Linux':
        if 'arm' in platform.machine():
            preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), 'snap/chromium/common/chromium/Default/Preferences'))")['output'].strip()
        else:
            preference_file_path = env.controller.execute_python_command("import os; print(os.path.join(os.getenv('HOME'), '.config/google-chrome/Default/Preferences'))")['output'].strip()
    else:
        raise Exception('Unsupported operating system')
    try:
        content = env.controller.get_file(preference_file_path)
        data = json.loads(content)
        all_extensions_names = []
        all_extensions_paths = []
        all_extensions_enabled = []
        all_extensions_dev_mode = []
        all_extensions = data.get('extensions', {}).get('settings', {})
        for ext_id in all_extensions.keys():
            ext_data = all_extensions[ext_id]
            name = ext_data.get('manifest', {}).get('name', '')
            path = ext_data.get('path', '')
            state = ext_data.get('state', 0)
            is_enabled = state == 1
            from_webstore = ext_data.get('from_webstore', True)
            is_dev_mode = not from_webstore and path != ''
            if name:
                all_extensions_names.append(name)
                all_extensions_enabled.append(is_enabled)
                all_extensions_dev_mode.append(is_dev_mode)
            if path:
                all_extensions_paths.append(path)
        logger.info(f'Found {len(all_extensions_names)} extensions with names')
        logger.info(f'Found {len(all_extensions_paths)} extensions with paths')
        logger.info(f'Enabled states: {all_extensions_enabled}')
        logger.info(f'Developer mode states: {all_extensions_dev_mode}')
        return {'names': all_extensions_names, 'paths': all_extensions_paths, 'enabled_states': all_extensions_enabled, 'dev_mode_states': all_extensions_dev_mode}
    except Exception as e:
        logger.error(f'Error reading Chrome Preferences file: {e}')
        return {'names': [], 'paths': [], 'enabled_states': [], 'dev_mode_states': []}

