def get_multi_getter(env, config: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """
    Execute multiple getters and combine their results into a single dictionary.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'getters' key containing a dict of getter configurations

    Returns:
        Dictionary mapping getter names to their results
        Returns None if config is invalid
    """
    if not config or 'getters' not in config:
        return None
    getters_config = config['getters']
    results = {}
    getter_functions = {'docx_table_data__b9d381e31aa7072686a4f3a7ed6d2565': get_docx_table_data__b9d381e31aa7072686a4f3a7ed6d2565, 'xlsx_data__b9d381e31aa7072686a4f3a7ed6d2565': get_xlsx_data__b9d381e31aa7072686a4f3a7ed6d2565}
    for (getter_name, getter_config) in getters_config.items():
        getter_type = getter_config.get('type')
        if getter_type in getter_functions:
            getter_func = getter_functions[getter_type]
            results[getter_name] = getter_func(env, getter_config)
        else:
            results[getter_name] = None
    return results

def get_docx_line_spacing__32927c4d(env, config: Dict[str, Any]) -> List[float]:
    """Extract line spacing from each paragraph in a docx file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        List of line spacing values for each paragraph
    """
    file_path = config.get('path')
    if not file_path:
        return []
    try:
        file_bytes = env.controller.get_file(file_path)
        if not file_bytes:
            return []
        import tempfile
        import os
        with tempfile.NamedTemporaryFile(delete=False, suffix='.docx') as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        try:
            doc = Document(tmp_path)
            spacings = []
            for para in doc.paragraphs:
                if para.text.strip():
                    spacing = para.paragraph_format.line_spacing
                    if spacing is not None:
                        spacings.append(float(spacing))
                    else:
                        spacings.append(1.0)
            return spacings
        finally:
            os.unlink(tmp_path)
    except Exception as e:
        return []

def get_project_structure__61841fd9(env, config):
    """Get project directory structure.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'directory' path

    Returns:
        Dict with subdirectory counts
    """
    directory = config.get('directory', '/home/user')
    command = f'find {directory} -mindepth 1 -maxdepth 1 -type d | wc -l'
    result = env.controller.run_bash_script(command, timeout=10)
    if result and result.get('status') == 'success':
        try:
            subdir_count = int(result['output'].strip())
            return {'subdirectories': subdir_count}
        except:
            return {'subdirectories': 0}
    return {'subdirectories': 0}

