def get_bib_entry_types__e655ed71(env, config: Dict[str, Any]) -> Dict[str, int]:
    """
    Count BibTeX entries by type (inproceedings, article, etc.).

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict[str, int]: Mapping of entry type to count
    """
    file_path = config.get('path', '/home/user/Desktop/references.bib')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    content = file_bytes.decode('utf-8', errors='ignore')
    pattern = '@(\\w+)\\s*\\{'
    types = re.findall(pattern, content, re.IGNORECASE)
    type_counts = {}
    for entry_type in types:
        entry_type_lower = entry_type.lower()
        type_counts[entry_type_lower] = type_counts.get(entry_type_lower, 0) + 1
    return type_counts

def get_docx_underline_status__f66b7686(env, config: Dict[str, Any]) -> List[bool]:
    """Check if each paragraph has underline formatting applied.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        List of booleans indicating if each paragraph has underline text
    """
    file_path = config.get('path')
    if not file_path:
        return []
    try:
        file_bytes = env.controller.get_file(file_path)
        if not file_bytes:
            return []
        with tempfile.NamedTemporaryFile(delete=False, suffix='.docx') as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        try:
            doc = Document(tmp_path)
            underline_statuses = []
            for para in doc.paragraphs:
                if para.text.strip():
                    runs_with_text = [run for run in para.runs if run.text.strip()]
                    if runs_with_text:
                        has_underline = all((run.font.underline is not None and run.font.underline is not False for run in runs_with_text))
                        underline_statuses.append(has_underline)
            if len(underline_statuses) != 3:
                pass
            return underline_statuses
        finally:
            os.unlink(tmp_path)
    except Exception as e:
        return []

