def get_line_spacing_info__1de3e8723a73abd976276bbf7361d9c1(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Extract line spacing information for all paragraphs in the document.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the docx file

    Returns:
        Dict containing:
        - paragraph_spacings: list of line spacing values for each non-empty paragraph
        - all_same: bool, whether all paragraphs have same spacing
        - common_spacing: the spacing value if all same, else None
    """
    file_path = config.get('path', '')
    if not file_path:
        return {'paragraph_spacings': [], 'all_same': False, 'common_spacing': None}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'paragraph_spacings': [], 'all_same': False, 'common_spacing': None}
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        spacings = []
        for para in doc.paragraphs:
            if para.text.strip():
                spacing = para.paragraph_format.line_spacing
                spacings.append(spacing)
        all_same = len(set(spacings)) == 1 if spacings else False
        common_spacing = spacings[0] if all_same and spacings else None
        return {'paragraph_spacings': spacings, 'all_same': all_same, 'common_spacing': common_spacing}
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

def get_docx_abstract_count__f8bbb9eb(env, config):
    """Count abstract entries in docx.

    Args:
        env: DesktopEnv instance
        config: Configuration dict

    Returns:
        int: Number of abstract entries
    """
    import os
    from docx import Document
    path = config['path']
    dest = config.get('dest', os.path.basename(path))
    cache_path = os.path.join(env.cache_dir, dest)
    file_bytes = env.controller.get_file(path)
    if not file_bytes:
        return 0
    with open(cache_path, 'wb') as f:
        f.write(file_bytes)
    doc = Document(cache_path)
    paragraphs = [p.text.strip() for p in doc.paragraphs if p.text.strip()]
    abstract_count = sum((1 for p in paragraphs if p.startswith('Abstract:')))
    return abstract_count

